# ─── DATA MODELS ─────────────────────────────────────────────────
@dataclass
class MemoryEntry:
    role: str  # "user" | "assistant"
    text: str
    timestamp: float = field(default_factory=time.time)


@dataclass
class ConversationMemory:
    entries: deque = field(default_factory=lambda: deque(maxlen=300))
    summary: str = ""
    session_summaries: list = field(default_factory=list)  # Last 10 session summaries
    session_id: str = ""  # Current session identifier
    _lock: asyncio.Lock = field(default_factory=asyncio.Lock, repr=False)

    async def add(self, role: str, text: str):
        """Add a memory entry with timestamp for time-based expiry."""
        async with self._lock:
            self.entries.append(MemoryEntry(role=role, text=text))

    async def context_window(
        self, n: int = 8, max_age_s: float = 3600.0, cap: int = 40
    ) -> list[dict]:
        """Return entries for the LLM context window.

        Time-aware persistent chat memory: everything from the last
        `max_age_s` (default 1 hour) is eligible, capped at `cap` entries.
        Important entries (name, preferences, "remember", tasks) are pinned
        so they survive even a heavy conversation. Falls back to the last n
        entries when everything is older than the window.
        """
        async with self._lock:
            entries = list(self.entries)
            if not entries:
                return []

            now = time.time()
            recent = [e for e in entries if now - e.timestamp <= max_age_s]
            if not recent:
                recent = entries[-n:]

            important_keywords = [
                "name",
                "call me",
                "my name",
                "remember",
                "important",
                "favorite",
                "favourite",
                "i like",
                "i love",
                "i hate",
                "i live",
                "i work",
                "birthday",
                "task:",
                "deadline",
                "meeting",
                "project",
                "goal",
                "preference",
            ]
            user_name = (
                getattr(self, "_user_name", None)
                or os.environ.get("USER_NAME", "").lower()
            )
            if user_name:
                important_keywords.append(user_name)

            window = recent[-cap:]
            # Pin important entries from earlier in the hour
            for e in recent[:-cap] if len(recent) > cap else []:
                text_lower = e.text.lower()
                if any(kw and kw in text_lower for kw in important_keywords):
                    window.insert(0, e)
            if len(window) > cap + 6:
                window = window[-(cap + 6) :]

            return [{"role": e.role, "content": e.text} for e in window]

    async def snapshot(self) -> list:
        async with self._lock:
            return list(self.entries)

    async def to_dict(self) -> dict:
        async with self._lock:
            return {
                "summary": self.summary,
                "entries": [asdict(e) for e in self.entries],
                "session_summaries": self.session_summaries[-10:],  # Keep last 10
                "session_id": self.session_id,
            }

    async def set_summary(self, summary: str):
        async with self._lock:
            self.summary = summary

    async def add_session_summary(self, summary: str, session_id: str = ""):
        """Add a session summary to the history for cross-session context."""
        async with self._lock:
            entry = {
                "summary": summary,
                "session_id": session_id or self.session_id,
                "timestamp": time.time(),
                "entry_count": len(self.entries),
            }
            self.session_summaries.append(entry)
            # Keep only last 10 session summaries
            if len(self.session_summaries) > 10:
                self.session_summaries = self.session_summaries[-10:]

    async def get_recent_session_summaries(self, n: int = 3) -> list[dict]:
        """Get the last N session summaries for catch-up context."""
        async with self._lock:
            return self.session_summaries[-n:] if self.session_summaries else []

    async def len(self) -> int:
        async with self._lock:
            return len(self.entries)

    async def clear(self):
        async with self._lock:
            self.entries.clear()
            self.summary = ""

    @classmethod
    def from_dict(cls, d: dict):
        mem = cls(summary=d.get("summary", ""))
        for e in d.get("entries", []):
            mem.entries.append(MemoryEntry(**e))
        mem.session_summaries = d.get("session_summaries", [])
        mem.session_id = d.get("session_id", "")
        return mem


