def strip_think_tags(text: str) -> str:
    """Remove model thinking/tag noise from output."""
    text = re.sub(r"<think>.*?</think>", "", text, flags=re.DOTALL)
    text = re.sub(r"<.*?>", "", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    return text.strip()


# ── Hallucination patterns the model sometimes emits (YouTube/media/Subscribe noise etc.) ──
_HALLUCINATION_PATTERNS = [
    # YouTube/media creator hallucinations
    (
        re.compile(
            r"(like\s+and\s+subscribe|thanks\s+for\s+watching|link\s+in\s+description)",
            re.I,
        ),
        "",
    ),
    (
        re.compile(
            r"(if\s+you\s+liked\s+this|hit\s+that\s+subscribe|drop\s+a\s+like)", re.I
        ),
        "",
    ),
    (re.compile(r"(welcome\s+to\s+my\s+channel|subscribe\s+for\s+more)", re.I), ""),
    # Overly verbose canned sign-offs
    (
        re.compile(
            r"(as\s+always|as\s+mentioned\s+earlier|as\s+i\s+said\s+before)\s*,?\s*i'?ll\s+leave\s+a\s+link",
            re.I,
        ),
        "",
    ),
    # Fabricated sensor readings — strip specific numbers the model invented
    (
        re.compile(
            r"(the\s+(?:temperature|light|pressure|battery|humidity|steps?))\s+(?:is|reads)\s+(?:around\s+)?\d+\s*(?:degrees?|lux|hpa|%|c)\s*[,.]?\s*i\s+(?:can|could)\s+(?:feel|sense|see)",
            re.I,
        ),
        "",
    ),
    # Repetitive filler / degenerate loops (you know you know, like like like, etc.)
    (
        re.compile(
            r"(?:\b(?:you\s+know|like|um|uh|hmm|well|so)\b[\s,.]*){4,}",
            re.I,
        ),
        "...",
    ),
    # Duplicate boilerplate
    (re.compile(r"\n{4,}", re.I), "\n\n"),
]


# ─── OFFENSIVE LANGUAGE FILTER ─────────────────────────────────
# Keep replies clean: no vulgarity, no slurs, no rude outbursts.
# Replacements are read aloud by TTS, so use natural soft words —
# never asterisks (piper would read them as "star star star").
# Also applied to STT output so mis-heard "vulgar" words never hit
# the screen or the model context.
_OFFENSIVE_WORD_MAP = [
    ("asshole", "jerk"),
    ("bastard", "jerk"),
    ("bitch", "jerk"),
    ("bullshit", "nonsense"),
    ("bullshitting", "joking"),
    ("cunt", "jerk"),
    ("dickhead", "jerk"),
    ("dick", "jerk"),
    ("douchebag", "jerk"),
    ("faggot", "person"),
    ("faggots", "people"),
    ("fucker", "jerk"),
    ("fuckers", "jerks"),
    ("fucking", "fricking"),
    ("fuck", "frick"),
    ("goddamned", "darn"),
    ("goddamn", "darn"),
    ("motherfucker", "jerk"),
    ("nigga", "person"),
    ("nigger", "person"),
    ("prick", "jerk"),
    ("pussy", "jerk"),
    ("shitty", "crummy"),
    ("shitting", "kidding"),
    ("shit", "crap"),
    ("slut", "jerk"),
    ("twat", "jerk"),
    ("wanker", "jerk"),
    ("whore", "jerk"),
]

# Words Lilly must never say, even though they're not profanity.
_OFFENSIVE_BANNED_WORDS = [
    "disgusting",
]


def _filter_offensive_language(text: str) -> str:
    """Replace profanity/slurs with soft words; drop banned words.

    Used both on LLM replies and on transcribed (heard) text so the
    UI and the model context stay clean.
    """
    if not text:
        return text
    cleaned = text
    for word, replacement in _OFFENSIVE_WORD_MAP:
        cleaned = re.sub(
            rf"\b{re.escape(word)}\b", replacement, cleaned, flags=re.IGNORECASE
        )
    # Obfuscated variants: f*ck, f**k, f.u.c.k, s h i t, s-h-i-t, sh!t
    # (the * or ! typically replaces the vowel, so vowels are optional)
    cleaned = re.sub(
        r"\bf\s*[\*\.\-_!\s]*(?:u\s*[\*\.\-_!\s]*)?c\s*[\*\.\-_!\s]*k\w*",
        "frick",
        cleaned,
        flags=re.IGNORECASE,
    )
    cleaned = re.sub(
        r"\bs\s*[\*\.\-_!\s]*h\s*[\*\.\-_!\s]*(?:i\s*[\*\.\-_!\s]*)?t\w*",
        "crap",
        cleaned,
        flags=re.IGNORECASE,
    )
    # Fully-stared variants: f***, f***k, sh*t (2+ separator chars)
    cleaned = re.sub(r"\bf\s*[\*\.\-_!]{2,}", "frick", cleaned, flags=re.IGNORECASE)
    cleaned = re.sub(
        r"\bs\s*h\s*[\*\.\-_!]{1,}\s*t", "crap", cleaned, flags=re.IGNORECASE
    )
    # Banned words → gentle substitute
    for word in _OFFENSIVE_BANNED_WORDS:
        cleaned = re.sub(
            rf"\b{re.escape(word)}\b", "not great", cleaned, flags=re.IGNORECASE
        )
    cleaned = re.sub(r"\s{2,}", " ", cleaned)
    return cleaned.strip()


def _filter_hallucination_patterns(text: str) -> str:
    """Remove common hallucination / media-noise phrases from LLM output.

    Also cleans up fragment punctuation left behind after phrase removal
    (e.g. '!  below.' -> 'below.') so replies don't look broken.
    """
    if not text:
        return text
    cleaned = text
    for pattern, replacement in _HALLUCINATION_PATTERNS:
        cleaned = pattern.sub(replacement, cleaned)
    # Clean up fragments: leading punctuation + spaces left after phrase removal
    cleaned = re.sub(r"(?<!\w)[!,.:;-]{1,3}\s*(?=\s*[a-zA-Z])", " ", cleaned)
    cleaned = re.sub(r"\s{2,}", " ", cleaned)
    cleaned = re.sub(r"\n{3,}", "\n\n", cleaned).strip()
    # If the reply starts with fragment punctuation, trim it
    cleaned = re.sub(r"^[!,.:;/\\s]+", "", cleaned)
    # Keep replies clean: no profanity, slurs, or banned words
    cleaned = _filter_offensive_language(cleaned)
    return cleaned


def _strip_emoji(text: str) -> str:
    """Remove all emoji characters from text.

    Strips Unicode emoji characters (including combined emoji sequences)
    to ensure clean, text-only responses for chat display and TTS.

    Uses a comprehensive regex that handles:
    - Basic emoji (U+1F600-U+1F64F)
    - Symbols & pictographs (U+1F300-U+1F5FF)
    - Transport & map symbols (U+1F680-U+1F6FF)
    - Flags (U+1F1E0-U+1F1FF)
    - Dingbats (U+2702-U+27B0)
    - Zero-Width Joiner (U+200D) for combined emoji like 👨‍💻
    - Variation selectors (U+FE0F)
    - Skin tone modifiers (U+1F3FB-U+1F3FF)
    """
    if not text:
        return text

    # Comprehensive emoji pattern including ZWJ sequences
    emoji_pattern = re.compile(
        "["
        "\U0001f600-\U0001f64f"  # emoticons
        "\U0001f300-\U0001f5ff"  # symbols & pictographs
        "\U0001f680-\U0001f6ff"  # transport & map symbols
        "\U0001f1e0-\U0001f1ff"  # flags (iOS)
        "\U0001f900-\U0001f9ff"  # supplemental symbols
        "\U0001fa00-\U0001fa6f"  # chess symbols
        "\U0001fa70-\U0001faff"  # symbols extended-A
        "\U00002702-\U000027b0"  # dingbats
        "\U000024c2-\U0001f251"  # enclosed characters
        "\U0001f926-\U0001f937"  # supplemental
        "\U00010000-\U0010ffff"  # supplementary
        "\u200d"  # zero width joiner
        "\u2640-\u2642"  # gender symbols
        "\u2600-\u2b55"  # misc symbols
        "\u23cf"  # eject symbol
        "\u23e9"  # fast forward
        "\u231a"  # watch
        "\ufe0f"  # variation selector
        "\u3030"  # wavy dash
        "\U0001f3fb-\U0001f3ff"  # skin tone modifiers
        "]+",
        flags=re.UNICODE,
    )

    cleaned = emoji_pattern.sub("", text)
    # Clean up any extra whitespace left after emoji removal
    cleaned = re.sub(r"\s{2,}", " ", cleaned)
    cleaned = re.sub(r"\n{3,}", "\n\n", cleaned).strip()
    return cleaned


def _clean_transcription_fillers(text: str) -> str:
    """Remove filler-word noise from voice transcription before chat display.

    Strips all disfluency tokens and repeated filler bursts while
    preserving the actual message content.  Applies after the hallucination
    filter so true media-phrase noise is already gone.
    """

    if not text:
        return text

    # Normalise whitespace first

    text = re.sub(r"\s+", " ", text).strip()

    if not text:
        return text

    # Remove multi-word disfluencies first (e.g. "you know", "like like")
    # Sort by length descending so longer phrases match first
    multi = sorted(
        [d for d in DISFLOENCIES if " " in d],
        key=len,
        reverse=True,
    )
    for phrase in multi:
        pattern = re.compile(
            r"(?i)\b" + re.escape(phrase).replace(r"\ ", r"\s+") + r"\b"
        )
        text = pattern.sub("", text)

    # Normalise whitespace again after removing phrases
    text = re.sub(r"\s+", " ", text).strip()

    if not text:
        return text

    # Remove single-word fillers
    words = text.split()
    cleaned = []

    for w in words:
        lw = w.lower().strip(".,!?;:")
        if lw in DISFLOENCIES:
            continue
        cleaned.append(w)

    result = " ".join(cleaned)

    # Final safety: if the result is just filler words or empty, return empty
    if not result or all(
        w.lower().strip(".,!?;:") in DISFLOENCIES for w in result.split()
    ):
        return ""

    return result


# ─── LLM RESPONSE CACHE (buffer middle man) ──────────────────────
# In-memory cache for repeated LLM prompts. Reduces latency for
# common questions by returning cached responses instantly.
_LLM_CACHE_TTL: float = 300.0  # 5 minutes
_LLM_CACHE_MAX: int = 200  # max entries before pruning


class LlamaBackend:
    """Manages Ollama inference requests (unified backend)."""

    def __init__(self):
        self.model_name = ""
        # Per-instance response cache (avoid global state confusion)
        self._response_cache: dict[str, dict] = {}

    async def chat(
        self,
        messages: list[dict],
        temperature: float = 0.7,
        max_tokens: int = 80,
        timeout: int = 120,
        model: str = "",
    ) -> str:
        use_model = model or OLLAMA_MODEL

        # ── Response cache (buffer middle man) ────────────────────────
        # Cache key = hash of messages + temperature + model + max_tokens
        # Repeated prompts return instantly from cache.
        try:
            import hashlib, json as _json

            cache_key_data = _json.dumps(
                {
                    "messages": messages,
                    "temperature": temperature,
                    "model": use_model,
                    "max_tokens": max_tokens,
                },
                sort_keys=True,
            )
            cache_key = hashlib.sha256(cache_key_data.encode()).hexdigest()[:32]
            cached = self._response_cache.get(cache_key)
            if cached is not None:
                age = time.time() - cached["ts"]
                if age < _LLM_CACHE_TTL:
                    logger.debug(f"LLM cache HIT ({age:.1f}s old)")
                    return cached["text"]
                else:
                    self._response_cache.pop(cache_key, None)
        except Exception:
            pass  # Cache failures are non-fatal

        payload = {
            "model": use_model,
            "messages": messages,
            "stream": False,
            "options": {
                "temperature": temperature,
                "num_predict": max_tokens,
            },
        }
        for attempt in range(2):
            try:
                c = await _get_ollama_client()
                r = await c.post(
                    f"{OLLAMA_URL}/api/chat", json=payload, timeout=timeout
                )
                if r.status_code == 200:
                    data = r.json()
                    msg = data.get("message", {})
                    # Only use the final content — ignore internal reasoning/thinking
                    text = (msg.get("content") or "").strip()
                    result = strip_think_tags(text) if text else ""
                    # Store in cache
                    try:
                        import hashlib, json as _json

                        cache_key_data = _json.dumps(
                            {
                                "messages": messages,
                                "temperature": temperature,
                                "model": use_model,
                                "max_tokens": max_tokens,
                            },
                            sort_keys=True,
                        )
                        cache_key = hashlib.sha256(cache_key_data.encode()).hexdigest()[
                            :32
                        ]
                        self._response_cache[cache_key] = {
                            "text": result,
                            "ts": time.time(),
                        }
                        # Prune stale entries if cache is getting large
                        if len(self._response_cache) > _LLM_CACHE_MAX:
                            now = time.time()
                            self._response_cache = {
                                k: v
                                for k, v in self._response_cache.items()
                                if now - v["ts"] < _LLM_CACHE_TTL
                            }
                    except Exception:
                        pass  # Cache storage failures are non-fatal
                    return result
            except Exception as e:
                logger.debug(f"Ollama attempt {attempt} failed: {e}")
                if attempt == 0:
                    await asyncio.sleep(1.0)
                    continue
            break
        return ""

    async def chat_stream(
        self,
        messages: list[dict],
        temperature: float = 0.7,
        max_tokens: int = 80,
        model: Optional[str] = None,
    ) -> AsyncGenerator[str, None]:
        """Stream chat response token by token. Yields text chunks as they arrive."""
        use_model = model or OLLAMA_MODEL
        payload = {
            "model": use_model,
            "messages": messages,
            "stream": True,
            "options": {
                "temperature": temperature,
                "num_predict": max_tokens,
                # Qwen3 reasoning models: disable thinking output for normal chat.
                "think": False,
            },
        }
        try:
            c = await _get_ollama_client()
            async with c.stream(
                "POST", f"{OLLAMA_URL}/api/chat", json=payload, timeout=120.0
            ) as r:
                async for line in r.aiter_lines():
                    if not line:
                        continue
                    try:
                        chunk = json.loads(line)
                        if chunk.get("done"):
                            break
                        token = chunk.get("message", {}).get("content", "")
                        if token:
                            cleaned = re.sub(
                                r"<think>.*?</think>", "", token, flags=re.DOTALL
                            )
                            cleaned = re.sub(r"<.*?>", "", cleaned)
                            if cleaned:
                                yield cleaned
                    except json.JSONDecodeError:
                        continue
        except Exception as e:
            logger.debug(f"Stream error: {e}")
            return


# ─── TWO-TIER LLM (baton race) ───────────────────────────────────
# Fast model answers first; quality model warms up in the background.
# Responses from the quality model are cached for repeat queries.
class TwoTierLLM:
    """Baton-race LLM: fast model answers immediately, quality model caches in background."""

    # Small-model failure signatures: base-assistant leakage + false refusals.
    # When the fast reply matches and the query is benign, skip it and use
    # the quality model synchronously instead of serving garbage.
    _REFUSAL_PATTERNS = (
        "as an ai companion",
        "as an ai language model",
        "as a language model",
        "as an ai assistant",
        "i'm sorry, but i can't assist",
        "i am sorry, but i can't assist",
        "i'm sorry, but i cannot assist",
        "i don't have personal beliefs",
        "i do not have personal beliefs",
        "i don't have personal opinions",
    )
    # Genuinely sensitive topics where a refusal may be legitimate.
    _SENSITIVE_HINTS = (
        "password",
        "hack into",
        "break into",
        "steal",
        "weapon",
        "bomb",
        "credit card",
        "ssn ",
        "social security",
    )

    def __init__(self, fast_model: str, quality_model: str):
        self.fast_model = fast_model
        self.quality_model = quality_model

    @classmethod
    def _fast_reply_usable(cls, reply: str, messages: list[dict]) -> bool:
        if not reply:
            return False
        low = reply.lower()
        if not any(p in low for p in cls._REFUSAL_PATTERNS):
            return True
        user_text = " ".join(
            m.get("content", "") for m in messages if m.get("role") == "user"
        ).lower()
        if any(h in user_text for h in cls._SENSITIVE_HINTS):
            return True  # legitimate refusal — keep it
        return False

    async def chat(
        self,
        messages: list[dict],
        temperature: float = 0.7,
        max_tokens: int = 80,
        timeout: int = 120,
        model: str = "",
    ) -> str:
        # Determine which model to use for this request
        use_fast = not model or model == OLLAMA_MODEL
        fast_model = self.fast_model
        quality_model = model or self.quality_model

        # Fast path: get quick response from small model
        fast_reply = ""
        try:
            fast_reply = await llama_backend.chat(
                messages=messages,
                temperature=temperature,
                max_tokens=max_tokens,
                timeout=min(timeout, 60),
                model=fast_model,
            )
        except Exception as e:
            logger.debug(f"TwoTier fast model failed: {e}")

        # Background: warm up quality model and cache result
        if fast_reply and self._fast_reply_usable(fast_reply, messages):
            asyncio.create_task(
                self._warm_quality_model(
                    messages=messages,
                    temperature=temperature,
                    max_tokens=max_tokens,
                    timeout=timeout,
                    model=quality_model,
                )
            )
            return fast_reply

        # Fallback: if fast model failed, try quality model synchronously
        try:
            return await llama_backend.chat(
                messages=messages,
                temperature=temperature,
                max_tokens=max_tokens,
                timeout=timeout,
                model=quality_model,
            )
        except Exception as e:
            logger.debug(f"TwoTier quality fallback failed: {e}")
            return ""

    async def _warm_quality_model(
        self,
        messages: list[dict],
        temperature: float,
        max_tokens: int,
        timeout: int,
        model: str,
    ) -> None:
        """Background task: call quality model and cache the result."""
        try:
            quality_reply = await llama_backend.chat(
                messages=messages,
                temperature=temperature,
                max_tokens=max_tokens,
                timeout=timeout,
                model=model,
            )
            if quality_reply:
                # Cache the quality response
                import hashlib, json as _json

                cache_key_data = _json.dumps(
                    {
                        "messages": messages,
                        "temperature": temperature,
                        "model": model,
                        "max_tokens": max_tokens,
                    },
                    sort_keys=True,
                )
                cache_key = hashlib.sha256(cache_key_data.encode()).hexdigest()[:32]
                llama_backend._response_cache[cache_key] = {
                    "text": quality_reply,
                    "ts": time.time(),
                    "quality": True,
                }
                logger.debug(
                    f"TwoTier: cached quality response ({len(quality_reply)} chars)"
                )
        except Exception as e:
            logger.debug(f"TwoTier background warmup failed: {e}")

    async def chat_stream(
        self,
        messages: list[dict],
        temperature: float = 0.7,
        max_tokens: int = 80,
        model: Optional[str] = None,
    ) -> AsyncGenerator[str, None]:
        """Stream from fast model; background caches quality model."""
        use_model = model or self.quality_model
        fast_model = self.fast_model

        # Stream from fast model immediately
        try:
            async for token in llama_backend.chat_stream(
                messages=messages,
                temperature=temperature,
                max_tokens=max_tokens,
                model=fast_model,
            ):
                yield token
        except Exception as e:
            logger.debug(f"TwoTier stream fast model failed: {e}")

        # Background: cache quality model response
        asyncio.create_task(
            self._warm_quality_model(
                messages=messages,
                temperature=temperature,
                max_tokens=max_tokens,
                timeout=120,
                model=use_model,
            )
        )


# Persistent clients — reused across requests to avoid TCP reconnect overhead
_ollama_client: Optional[httpx.AsyncClient] = None
_whisper_client: Optional[httpx.AsyncClient] = None
_sensor_client: Optional[httpx.AsyncClient] = None
_mc_client: Optional[httpx.AsyncClient] = None


async def _get_ollama_client() -> httpx.AsyncClient:
    global _ollama_client
    if _ollama_client is None or _ollama_client.is_closed:
        _ollama_client = httpx.AsyncClient(
            timeout=60.0,
            limits=httpx.Limits(max_keepalive_connections=4, max_connections=8),
        )
    return _ollama_client


async def _get_sensor_client() -> httpx.AsyncClient:
    global _sensor_client
    if _sensor_client is None or _sensor_client.is_closed:
        headers = {"Accept": "application/json"}
        if LILLY_PAIR_TOKEN:
            headers["X-Pair-Token"] = LILLY_PAIR_TOKEN
        _sensor_client = httpx.AsyncClient(
            timeout=10.0,
            limits=httpx.Limits(max_keepalive_connections=4, max_connections=8),
            headers=headers,
        )
    return _sensor_client


async def _get_whisper_client() -> httpx.AsyncClient:
    global _whisper_client
    if _whisper_client is None or _whisper_client.is_closed:
        _whisper_client = httpx.AsyncClient(
            timeout=30.0,
            limits=httpx.Limits(max_keepalive_connections=2, max_connections=4),
        )
    return _whisper_client


async def _get_mc_client() -> httpx.AsyncClient:
    """Persistent client for Mission Control API (100.73.249.14:4000)."""
    global _mc_client
    if _mc_client is None or _mc_client.is_closed:
        _mc_client = httpx.AsyncClient(
            base_url=MISSION_CONTROL_URL,
            timeout=15.0,
            limits=httpx.Limits(max_keepalive_connections=4, max_connections=8),
        )
    return _mc_client


llama_backend = LlamaBackend()
two_tier_backend = TwoTierLLM(fast_model=FAST_MODEL, quality_model=OLLAMA_MODEL)


# ─── UTILITY FUNCTIONS ──────────────────────────────────────────
def normalize_text(text: str) -> str:
    if not text:
        return ""
    text = unicodedata.normalize("NFKC", text).lower()
    text = re.sub(r"\[.*?\]|\(.*?\)", "", text)
    text = re.sub(r"[^\w\s]", " ", text)
    return re.sub(r"\s+", " ", text).strip()


def trig_in(cmd: str, *phrases: str) -> bool:
    """Substring trigger match robust to STT punctuation loss.

    normalize_text() strips apostrophes ("what's" → "what s"), so raw
    triggers containing punctuation can never match normalized input.
    Normalize both sides here — normalizing twice is idempotent, so `cmd`
    may be raw or pre-normalized.
    """
    p = normalize_text(cmd)
    return any(normalize_text(t) in p for t in phrases if t)


def is_self_echo(text: str) -> bool:
    """Detect Lilly's own voice being picked up by the mic (audio loop).

    Compares the heard text against what Lilly last said. If they overlap
    substantially, it's an echo of her own speech, not the user talking —
    discard it so she doesn't talk to herself in an endless loop.
    """
    global LAST_SPOKEN
    if not text or not LAST_SPOKEN:
        return False
    heard = normalize_text(text)
    spoke = normalize_text(LAST_SPOKEN)
    if not heard or not spoke:
        return False
    heard_words = heard.split()
    spoke_words = spoke.split()
    if not heard_words or not spoke_words:
        return False
    # Word overlap ratio — lower threshold catches more echoes
    intersection = set(heard_words) & set(spoke_words)
    ratio = len(intersection) / max(len(heard_words), len(spoke_words), 1)
    # Exact substring containment in either direction
    contained = heard in spoke or spoke in heard
    # Prefix/suffix overlap (e.g. "thank you" at end of longer phrase)
    prefix = spoke.startswith(heard) or heard.startswith(spoke)
    suffix = spoke.endswith(heard) or heard.endswith(spoke)
    return ratio >= 0.20 or contained or prefix or suffix


def _record_recent_speech(text: str):
    """Record a speech utterance for echo detection."""
    global _RECENT_SPEECH
    now = time.time()
    _RECENT_SPEECH.append((now, text))
    # Prune old entries
    cutoff = now - _RECENT_SPEECH_MAX_AGE
    _RECENT_SPEECH = [(t, tx) for (t, tx) in _RECENT_SPEECH if t > cutoff]
    # Cap size
    if len(_RECENT_SPEECH) > _RECENT_SPEECH_MAX_ENTRIES:
        _RECENT_SPEECH = _RECENT_SPEECH[-_RECENT_SPEECH_MAX_ENTRIES:]


def is_recent_speech_echo(text: str) -> bool:
    """Check if text overlaps with anything Lilly said recently."""
    if not text:
        return False
    now = time.time()
    cutoff = now - _RECENT_SPEECH_MAX_AGE
    global _RECENT_SPEECH
    # Prune stale entries on access
    _RECENT_SPEECH = [(t, tx) for (t, tx) in _RECENT_SPEECH if t > cutoff]
    heard = normalize_text(text)
    if not heard:
        return False
    heard_words = set(heard.split())
    if not heard_words:
        return False
    for _, spoke in _RECENT_SPEECH:
        spoke_norm = normalize_text(spoke)
        if not spoke_norm:
            continue
        spoke_words = set(spoke_norm.split())
        if not spoke_words:
            continue
        # Exact match or high word overlap
        if heard == spoke_norm:
            return True
        intersection = heard_words & spoke_words
        ratio = len(intersection) / max(len(heard_words), len(spoke_words), 1)
        if ratio >= 0.25:
            return True
        # Substring containment
        if heard in spoke_norm or spoke_norm in heard:
            return True
    return False


def strip_json_wrapper(text: str) -> str:
    """Strip JSON object/array wrapper from LLM replies.
    Handles patterns like:
      {"message": "Hello!"}
      {"reply": "...", "tone": "..."}
      {"response": "...", "confidence": 0.9}
    Returns the plain text value of the first string field found,
    or the original text if it doesn't look like a JSON wrapper.
    """
    if not text:
        return text
    t = text.strip()
    # Only attempt if it looks like a JSON object
    if not (t.startswith("{") and t.endswith("}")):
        return text
    try:
        data = json.loads(t)
        if isinstance(data, dict):
            # Try common message keys first, then fall back to first string value
            for key in (
                "message",
                "reply",
                "response",
                "text",
                "content",
                "answer",
                "output",
            ):
                if key in data and isinstance(data[key], str):
                    return data[key].strip()
            # Fall back to first string value found
            for v in data.values():
                if isinstance(v, str) and len(v) > 2:
                    return v.strip()
    except (json.JSONDecodeError, ValueError):
        pass
    return text


# Per-character wake words — each character responds to its own name
CHAR_WAKE_WORDS: dict[str, list[str]] = {
    "puppy": ["lilly", "hey lilly", "lily", "lili", "lillie"],
    "fox": ["fox", "hey fox"],
    "cat": ["cat", "hey cat", "kitty"],
    "bear": ["bear", "hey bear"],
    "bunny": ["bunny", "hey bunny", "bun"],
    "owl": ["owl", "hey owl", "owly"],
    "deer": ["deer", "hey deer"],
    "wolf": ["wolf", "hey wolf", "wolfie"],
    "raccoon": ["raccoon", "hey raccoon", "coony"],
}


def _get_wake_targets(avatar: Optional[str] = None) -> list[str]:
    """Return wake word targets for the given avatar (defaults to current_avatar)."""
    key = avatar or current_avatar or "puppy"
    return CHAR_WAKE_WORDS.get(key, CHAR_WAKE_WORDS["puppy"])


def fuzzy_wake_match(phrase: str, avatar: Optional[str] = None) -> tuple[bool, float]:
    """Returns (is_wake_word_present, confidence) using fuzzy matching.

    Matches against the wake words for the given avatar (or current_avatar).
    """
    phrase_lower = phrase.lower().strip()
    targets = _get_wake_targets(avatar)
    best_score = 0.0
    for target in targets:
        # Check for substring with fuzzy ratio
        if target in phrase_lower:
            best_score = max(best_score, 1.0)
        else:
            # Fuzzy match against the whole phrase
            ratio = difflib.SequenceMatcher(None, target, phrase_lower).ratio()
            best_score = max(best_score, ratio)
            # Also check against each word
            for word in phrase_lower.split():
                word_ratio = difflib.SequenceMatcher(None, target, word).ratio()
                best_score = max(best_score, word_ratio)
    return best_score >= 0.7, best_score


def match_wake_across_avatars(phrase: str) -> Optional[str]:
    """Check if the phrase contains a wake word for ANY avatar.

    Returns the matched avatar key, or None if no wake word found.
    Prioritizes the current avatar if multiple match.
    """
    phrase_lower = phrase.lower().strip()
    current = current_avatar or "puppy"
    best_key: Optional[str] = None
    best_score = 0.0
    # Check current avatar first (tie-breaking priority)
    order = [current] + [k for k in CHAR_WAKE_WORDS if k != current]
    for key in order:
        targets = CHAR_WAKE_WORDS.get(key, CHAR_WAKE_WORDS["puppy"])
        for target in targets:
            score = 0.0
            if target in phrase_lower:
                score = 1.0
            else:
                ratio = difflib.SequenceMatcher(None, target, phrase_lower).ratio()
                score = max(score, ratio)
                for word in phrase_lower.split():
                    word_ratio = difflib.SequenceMatcher(None, target, word).ratio()
                    score = max(score, word_ratio)
            if score >= 0.7:
                if best_key is None or score > best_score or key == current:
                    best_score = score
                    best_key = key
    return best_key


# ─── NLU + CONFIRMATION GATE (casual mode) ────────────────────────────
# Natural-language parsing of app intents ("I want to watch youtube videos
# on true crime") plus a confirmation gate so phone-affecting actions wait
# for an explicit "yes" before executing. This kills false positives from
# ambient speech while keeping conversation natural (no wake word needed).

_CONFIRM_YES = {
    "yes",
    "yep",
    "yeah",
    "yup",
    "sure",
    "ok",
    "okay",
    "go ahead",
    "go for it",
    "do it",
    "do that",
    "please do",
    "confirm",
    "confirmed",
    "yes please",
    "yeah sure",
    "ok do it",
    "alright",
    "all right",
    "fine",
    "please",
    "y",
    "sure thing",
    "absolutely",
    "yes do it",
    "lets go",
    "let's go",
    "go",
}
_CONFIRM_NO = {
    "no",
    "nope",
    "nah",
    "cancel",
    "cancel that",
    "dont",
    "dont do it",
    "no thanks",
    "not now",
    "stop",
    "never mind",
    "nevermind",
    "forget it",
    "n",
    "no dont",
    "no way",
    "skip",
    "not yet",
}

# Search-URL templates used by the NLU when an app has no registered
# *_search skill variant. Keyed by Android package.
_NLP_SEARCH_URLS = {
    "com.google.android.youtube": "https://www.youtube.com/results?search_query={q}",
    "com.google.android.apps.youtube.music": "https://music.youtube.com/search?q={q}",
    "com.google.android.apps.maps": "https://www.google.com/maps/search/?api=1&query={q}",
    "com.android.chrome": "https://www.google.com/search?q={q}",
    "org.mozilla.firefox": "https://www.google.com/search?q={q}",
    "com.google.android.googlequicksearchbox": "https://www.google.com/search?q={q}",
    "com.spotify.music": "spotify:search:{q}",
}


def _confirm_response(phrase: str) -> Optional[str]:
    """Return 'yes'/'no' if the phrase is a clear confirmation/denial."""
    p = normalize_text(phrase).strip()
    if not p:
        return None
    if p in _CONFIRM_YES:
        return "yes"
    if p in _CONFIRM_NO:
        return "no"
    # Prefix matching: "yes do it", "sure go ahead", "no dont" ...
    words = p.split()
    for i in range(1, len(words) + 1):
        prefix = " ".join(words[:i])
        if prefix in _CONFIRM_YES:
            return "yes"
        if prefix in _CONFIRM_NO:
            return "no"
    return None


def _app_lexicon() -> dict:
    """Map normalized app words -> skill dict for NLU parsing.

    Only real app-launch skills (intent_launch / context_launch /
    hybrid_intent_tap with a package) are included. Keyevent / nav /
    termux / info skills are matched by their own keyword rules and would
    add too much noise to a general "open app X" parser.
    """
    lex = {}
    for skill in SKILLS.values():
        action = skill.get("action_type") or skill.get("type")
        if action not in ("intent_launch", "context_launch", "hybrid_intent_tap"):
            continue
        if not skill.get("package"):
            continue
        for w in [skill.get("label", "")] + skill.get("aliases", []):
            nw = normalize_text(w)
            if nw and len(nw) > 1:
                lex[nw] = skill
    return lex


def _strip_nlp_noise(rest: str) -> str:
    """Strip intent verbs/connectors around an app mention, repeatedly."""
    for _ in range(4):
        before = rest
        rest = re.sub(r"^\s*(?:and|or|then|to|please)\s+", " ", rest)
        rest = re.sub(
            r"^\s*(?:(?:can|could|will|would)\s+you|let'?s|let\s+us)\s+",
            " ",
            rest,
        )
        rest = re.sub(
            r"^(?:i\s+(?:want\s+to|wanna|would\s+love\s+to|need\s+to|"
            r"would\s+like\s+to)\s+|i\s+|would\s+you\s+)?"
            r"(?:watch|listen\s+to|open|play|start|launch|put\s+on|use|"
            r"show\s+me|search\s+for|search|find\s+on|find|look\s+up|"
            r"look\s+for|go\s+to|turn\s+on|navigate\s+to|navigate)\s*",
            " ",
            rest,
        )
        rest = re.sub(r"^\s*(?:for|about|on|in)\s+", " ", rest)
        rest = re.sub(r"\s+(?:on|in|for|about|at|with)\s*$", "", rest)
        rest = re.sub(r"\s+", " ", rest).strip()
        if rest == before:
            break
    return rest


def _search_variant(skill: dict) -> Optional[dict]:
    """Find a search-capable variant of an app skill (e.g. youtube_search)."""
    pkg = skill.get("package", "")
    if not pkg:
        return None
    for s in SKILLS.values():
        if s is skill:
            continue
        if s.get("package") == pkg:
            uri = s.get("uri_template") or ""
            if "search_query" in uri or "{}" in uri:
                merged = dict(s)
                merged["label"] = skill.get("label", s.get("label", "app"))
                return merged
    url = _NLP_SEARCH_URLS.get(pkg)
    if url:
        return {
            "package": pkg,
            "action_type": "intent_launch",
            "type": "intent_launch",
            "intent_action": "android.intent.action.VIEW",
            "uri_template": url,
            "label": skill.get("label", "app"),
            "canned_reply": "Searching for {query}!",
        }
    return None


# Intent verbs that signal the user wants an app action, not just a
# conversational mention of the app ("do you watch youtube?" is chat,
# "watch true crime on youtube" is an intent).
# NOTE: We only include verbs that are STRONG app-action signals.
# Common conversational verbs like "show", "find", "look", "open",
# "start", "run", "play", "search" are REMOVED to prevent false triggers
# in normal chat (e.g. "I want to show you something" should NOT activate).
_NLP_INTENT_VERBS = r"(?:watch|listen|launch|navigate|stream|queue|browse)"
# The verb must be in imperative position: at the start of the phrase,
# optionally behind politeness/request prefixes. This rejects question
# forms like "do you watch youtube" or "how do i watch youtube".
# ALSO: requires the phrase to be SHORT (< 60 chars) — long conversational
# messages are almost never app intents.
_NLP_INTENT_START = re.compile(
    r"^\s*(?:please\s+|hey\s+\w+\s*)?"
    r"(?:(?:i\s+(?:(?:want|need|would\s+like|would\s+love)\s+to|wanna|gonna))\s+|"
    r"(?:can|could|will|would)\s+you\s+(?:please\s+)?|let'?s\s+)?"
    + _NLP_INTENT_VERBS
    + r"\b"
)


def parse_nlp_intent(phrase: str) -> tuple[Optional[dict], str]:
    """Extract (app_skill, query) from a natural-language utterance.

    Handles phrasings like:
      "I want to watch youtube videos on true crime"  -> youtube + "true crime"
      "open youtube and search for true crime"        -> youtube + "true crime"
      "play netflix"                                  -> netflix + ""
      "watch true crime on youtube"                   -> youtube + "true crime"
      "search youtube for true crime"                 -> youtube + "true crime"

    Requires an intent verb in the phrase — a bare conversational mention
    of an app ("do you like youtube") returns (None, "") so it falls
    through to normal chat instead of launching/confirming an app action.
    """
    phrase = normalize_text(phrase)

    # SAFETY: Long phrases (>60 chars) are almost never app intents —
    # they're conversational messages that happen to mention an app name.
    if len(phrase) > 60:
        return None, ""

    lex = _app_lexicon()
    if not lex:
        return None, ""
    # Gate: no imperative-position action verb → not an app intent,
    # just conversation ("do you watch youtube" stays chat).
    if not _NLP_INTENT_START.search(phrase):
        return None, ""
    found = []
    for word, skill in lex.items():
        # Word-boundary match so "youtube" doesn't match substrings and
        # multi-word aliases ("youtube music") still work.
        if re.search(r"\b" + re.escape(word) + r"\b", phrase):
            found.append((len(word), word, skill))
    if not found:
        return None, ""
    found.sort(key=lambda x: -x[0])
    _, app_word, skill = found[0]

    rest = phrase.replace(app_word, " ", 1)
    rest = re.sub(r"\b(?:videos?|video|app|apps|the|an?)\b", " ", rest)
    rest = _strip_nlp_noise(rest)
    query = rest.strip()

    if query:
        sv = _search_variant(skill)
        if sv:
            skill = sv
    return skill, query


def _is_read_only_skill(skill: dict) -> bool:
    """Info reads are harmless — exempt from the confirmation gate."""
    action = skill.get("action_type") or skill.get("type")
    if action == "info":
        return True
    if action == "termux":
        binary = skill.get("binary") or skill.get("command", "")
        read_only = (
            "battery",
            "wifi",
            "location",
            "notification",
            "sensor",
            "clipboard-get",
            "call-log",
            "contact",
            "bluetooth",
        )
        return any(b in binary for b in read_only)
    return False


def _needs_confirmation(skill: dict) -> bool:
    """Whether a skill action must wait for the user's explicit OK."""
    if not CONFIRM_PHONE_ACTIONS:
        return False
    if skill.get("auto_exec"):
        return False
    if skill.get("confirm") is False:
        return False
    action = skill.get("action_type") or skill.get("type", "intent_launch")
    if action in ("openhuman_skill", "info", "keyevent", "voice_dictation"):
        return False
    if _is_read_only_skill(skill):
        return False
    return True


def _describe_skill_action(skill: dict, skill_arg: str = "") -> str:
    """Human-readable description used in the confirmation prompt."""
    label = skill.get("label", "app")
    action = skill.get("action_type") or skill.get("type", "intent_launch")
    uri = skill.get("uri_template") or ""
    if skill_arg:
        if "search_query" in uri or "search?" in uri or "search" in uri:
            return f"open {_app_display_label(skill)} and search for '{skill_arg}'"
        return f"open {label} and look for '{skill_arg}'"
    if action == "shell_command":
        return f"run the {label.lower()} command"
    if action == "termux":
        return f"use the {label.lower()} tool on your phone"
    return f"open {_app_display_label(skill)}"


def _app_display_label(skill: dict) -> str:
    """Label with a trailing 'search' removed — 'YouTube Search' -> 'YouTube'."""
    label = skill.get("label", "app")
    base = re.sub(r"\s*search$", "", label, flags=re.IGNORECASE).strip()
    return base or label


async def _run_skill_action(skill: dict, skill_arg: str = "") -> str:
    """Execute a skill action (used directly and for confirmed actions).

    Returns the reply text spoken/shown to the user.
    """
    global PENDING_OPEN_URL
    action = skill.get("action_type") or skill.get("type", "intent_launch")
    pkg = skill.get("package", "")
    label = skill.get("label", "app")

    if action == "prompt_argument":
        if not skill_arg:
            return ""
        url_query = urllib.parse.quote(skill_arg)
        url = (
            skill.get("uri_template") or "https://www.google.com/search?q={}"
        ).replace("{}", url_query)
        is_docker = not shutil.which("termux-open")
        if is_docker:
            PENDING_OPEN_URL = url
            return f"Searching for {skill_arg}!"
        await termux_run(["termux-open", url], timeout=5.0)
        return f"Searching for {skill_arg}!"

    if action in ("intent_launch", "hybrid_intent_tap", "context_launch") and pkg:
        intent_action = skill.get("intent_action") or "android.intent.action.VIEW"
        uri_template = skill.get("uri_template", "")
        try:
            await app_process_monkey_intent(pkg, intent_action, uri_template, skill_arg)
        except Exception as e:
            logger.warning(f"App launch failed ({label}): {e}")
        display_label = _app_display_label(skill)
        if skill_arg:
            return f"Opening {display_label} and searching for {skill_arg}!"
        return f"Opening {display_label}!"

    if action == "shell_command":
        cmd_to_run = skill.get("command", "")
        subcmd = skill.get("subcommand", "")
        args = skill.get("args", [])
        if skill.get("no_arg"):
            full_cmd = [cmd_to_run] + (args or [])
        elif skill_arg:
            full_cmd = (
                [cmd_to_run] + ([subcmd] if subcmd else []) + (args or []) + [skill_arg]
            )
        else:
            return ""
        try:
            proc = await asyncio.create_subprocess_exec(
                *full_cmd,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
            )
            stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=30.0)
            output = stdout.decode().strip() or stderr.decode().strip()
            return f"Done: {output[:200]}" if output else "Command executed."
        except asyncio.TimeoutError:
            return "Command timed out."
        except FileNotFoundError:
            return f"Command '{cmd_to_run}' not found in container."

    if action == "termux":
        binary = skill.get("binary", "")
        args = skill.get("args", []) or []
        if binary:
            cmd = [binary] + args
            if skill_arg and not skill.get("no_arg"):
                cmd.append(skill_arg)
            stdout, stderr = await termux_run(cmd, timeout=10.0)
            if stdout:
                return f"Done: {stdout[:200]}"
            elif stderr:
                return f"Command failed: {stderr[:200]}"
            return f"{label} completed."
        return f"Opening {label} on your phone!"

    return f"Opening {label}!"


async def _gate_phone_action(skill: dict, skill_arg: str = "") -> Optional[str]:
    """Ask for confirmation before a phone-affecting action.

    Returns the confirmation question if the user must confirm, else None
    (meaning the action may run immediately).
    """
    global PENDING_CONFIRM
    if not _needs_confirmation(skill):
        return None
    desc = _describe_skill_action(skill, skill_arg)
    PENDING_CONFIRM = {
        "desc": desc,
        "skill": skill,
        "skill_arg": skill_arg,
        "expires": time.time() + CONFIRM_TIMEOUT,
    }
    reply = f"Should I {desc}?"
    await speak(reply)
    return reply


def estimate_phoneme_duration(text: str) -> tuple[list[float], float]:
    """
    Simple phoneme estimation for mouth animation.
    Returns (phoneme_timings_in_seconds, total_duration).
    Based on average speaking rate of ~150 words/min → ~2.5 chars/sec.
    """
    if not text:
        return [], 0.0
    words = text.split()
    total_chars = len(text)
    speaking_rate = 12.0  # chars per second (slightly slower for kids)
    total_duration = total_chars / speaking_rate
    if total_duration < 0.5:
        total_duration = 0.5

    timings = []
    for word in words:
        word_dur = len(word) / speaking_rate
        timings.append(word_dur)
    return timings, total_duration


def load_skills():
    global SKILLS
    if SKILLS_FILE.exists():
        try:
            raw = json.loads(SKILLS_FILE.read_text())
            for k, v in raw.items():
                # Skip placeholder skills the LLM inferred with fake packages/URIs.
                # They are unusable ("open example.com") and hijack real words.
                pkg = v.get("package") or ""
                uri = v.get("uri_template") or ""
                if (
                    "com.example" in pkg
                    or "example.com" in uri
                    or uri.strip() == "https://..."
                ):
                    logger.warning(
                        f"Skipping placeholder skill '{k}' (package={pkg!r}, uri={uri!r})"
                    )
                    continue
                SKILLS[normalize_text(k)] = v
                for alias in v.get("aliases", []):
                    SKILLS[normalize_text(alias)] = v
        except Exception as e:
            logger.error(f"Failed to load skills: {e}")


# ─── OpenHuman Skill Registry Integration ─────────────────────────────
# Fetches community skills from the OpenHuman skill catalog (via the
# openhuman_bridge.py HTTP service) and merges them into Lilly's SKILLS dict.
# Each avatar gets a filtered subset based on AVATAR_SKILL_TAGS so Fox gets
# creative skills, Cat gets analysis tools, etc.
# No UI changes are required — skills are registered in the same SKILLS dict
# that handle_intent() already looks up.

# Cache for the OpenHuman skill catalog (in-memory, refreshed periodically)
_openhuman_catalog_cache: list | None = None
_openhuman_catalog_loaded: float = 0.0
_openhuman_catalog_ttl: float = 300.0  # 5 minutes

# Per-avatar skill index: avatar_key → {normalized_alias: skill_dict}
_openhuman_avatar_skills: dict[str, dict] = {}


def _is_iphone_ios_skill(entry: dict) -> bool:
    """Return True if a catalog entry is exclusively an iPhone/iOS app skill.

    Filters out skills whose only target platforms are iOS-family, or whose
    name/tags/description explicitly identify them as iPhone/iOS-only when no
    cross-platform markers are present.
    """
    platforms = [str(p).lower() for p in (entry.get("platforms") or [])]
    cross_platform_markers = {
        "linux",
        "windows",
        "macos",
        "android",
        "web",
        "cross-platform",
        "desktop",
    }
    ios_only_platforms = {"ios", "iphone", "ipados", "watchos", "tvos"}

    # If platforms includes any cross-platform or macOS/Android/Linux/Windows marker, keep it
    if any(p in cross_platform_markers for p in platforms):
        return False

    # If platforms is exclusively iOS-family, drop it
    if platforms and all(p in ios_only_platforms for p in platforms):
        return True

    # For entries with no/missing platforms, check name/tags/description for explicit iPhone/iOS app markers
    text_blob = " ".join(
        [
            str(entry.get("name", "")),
            str(entry.get("description", "")),
            " ".join(str(t) for t in entry.get("tags", [])),
        ]
    ).lower()

    # Look for standalone "iphone" or "ios" words (not substrings like "iosif" or "iphonecase")
    has_iphone = bool(re.search(r"\biphone\b", text_blob))
    has_ios = bool(re.search(r"\bios\b", text_blob))

    if has_iphone or has_ios:
        # Keep if it also has cross-platform indicators
        if any(marker in text_blob for marker in cross_platform_markers):
            return False
        return True

    return False


async def _fetch_openhuman_catalog(force_refresh: bool = False) -> list[dict]:
    """Fetch the OpenHuman skill catalog from the bridge service.

    Returns a list of catalog entry dicts. Results are cached in-memory for
    _openhuman_catalog_ttl seconds.
    """
    global _openhuman_catalog_cache, _openhuman_catalog_loaded

    now = time.time()
    if not force_refresh and _openhuman_catalog_cache is not None:
        if now - _openhuman_catalog_loaded < _openhuman_catalog_ttl:
            return _openhuman_catalog_cache

    try:
        url = f"{OPENHUMAN_BRIDGE_URL}/v1/catalog"
        if force_refresh:
            url += "?force_refresh=1"
        async with httpx.AsyncClient(timeout=30.0) as client:
            resp = await client.get(url)
            if resp.status_code == 200:
                data = resp.json()
                entries = data.get("entries", [])
                # Filter out iPhone/iOS-only app skills — Lilly runs on Android
                entries = [e for e in entries if not _is_iphone_ios_skill(e)]
                _openhuman_catalog_cache = entries
                _openhuman_catalog_loaded = now
                logger.info(
                    f"OpenHuman: fetched {len(entries)} catalog entries from bridge"
                )
                return entries
            else:
                logger.warning(
                    f"OpenHuman bridge returned HTTP {resp.status_code} from {url}"
                )
    except Exception as e:
        logger.warning(f"OpenHuman: failed to fetch catalog: {e}")

    # Return stale cache if available
    if _openhuman_catalog_cache is not None:
        logger.info("OpenHuman: using stale cached catalog")
        return _openhuman_catalog_cache
    return []


# Curated download_url overrides for high-value community skills whose catalog
# entry ships no resolvable docs_path/source_url (ClawHub/skills.sh often leave
# them empty, so execute_openhuman_skill() would refuse them). Keyed by the
# normalized entry id/name, values are working raw SKILL.md URLs.
_OPENHUMAN_DL_OVERRIDES = {
    "creating explainers": (
        "https://raw.githubusercontent.com/analyticalmonk/explain-this/main/"
        "skills/creating-explainers/SKILL.md"
    ),
    "explaining codebases": (
        "https://raw.githubusercontent.com/analyticalmonk/explain-this/main/"
        "skills/explaining-codebases/SKILL.md"
    ),
    "fact checking explainers": (
        "https://raw.githubusercontent.com/analyticalmonk/explain-this/main/"
        "skills/fact-checking-explainers/SKILL.md"
    ),
}

# Extra trigger aliases (normalized) for the same skills so plain-language
# "explain anything"-style intents hit them.
_OPENHUMAN_ALIAS_OVERRIDES = {
    "creating explainers": [
        "explain anything",
        "anything to explainer",
        "anything 2 explainer",
        "make an explainer",
        "create an explainer",
    ],
    "explaining codebases": [
        "explain codebase",
        "explain this repo",
        "codebase explainer",
    ],
    "fact checking explainers": [
        "fact check explainer",
        "verify explainer",
        "check explainer claims",
    ],
}


def _match_avatar_tags(skill: dict) -> bool:
    """Check if an OpenHuman skill matches the current avatar's tag filter.

    If the avatar has no tag filter (empty list), all skills match.
    Otherwise, the skill must have at least one tag that matches the avatar's
    filter — or have no tags (universal skills always match).
    """
    avatar = current_avatar
    allowed_tags = AVATAR_SKILL_TAGS.get(avatar, [])
    if not allowed_tags:
        return True

    skill_tags = skill.get("tags", [])
    if not skill_tags:
        return True  # Skills with no tags are universally available

    return any(
        any(tag.lower() in allowed for tag in skill_tags) for allowed in allowed_tags
    )


def _openhuman_to_lilly_skill(entry: dict) -> dict:
    """Convert an OpenHuman catalog entry to Lilly's lilly_skills.json format.

    The skill is invoked by setting action_type to 'openhuman_skill' and
    intent_action to 'openhuman.SKILL_EXECUTE'. handle_intent() then looks up
    the skill and the bridge executes it via the OpenHuman runtime.
    """
    name = entry.get("name", entry.get("id", "unknown"))
    ident = normalize_text(entry.get("id", "") or entry.get("name", ""))
    aliases = [normalize_text(name)]
    # Add tags as aliases for better intent matching
    for tag in entry.get("tags", [])[:5]:
        aliases.append(normalize_text(tag))
    # Curated aliases so high-value community skills trigger by intent
    for extra in _OPENHUMAN_ALIAS_OVERRIDES.get(ident, []):
        if extra not in aliases:
            aliases.append(extra)
    # Fall back to a curated SKILL.md URL when the catalog entry is unresolvable
    dl_url = entry.get("download_url", "") or _OPENHUMAN_DL_OVERRIDES.get(ident, "")

    return {
        "action_type": "openhuman_skill",
        "type": "openhuman_skill",
        "label": name,
        "source": entry.get("source", "openhuman"),
        "download_url": dl_url,
        "uri_template": dl_url or entry.get("source_url", ""),
        "intent_action": "openhuman.SKILL_EXECUTE",
        "aliases": aliases,
        "canned_reply": entry.get("description", ""),
        "commands": entry.get("commands", []),
        "env_vars": entry.get("env_vars", []),
        "tags": entry.get("tags", []),
        "category": entry.get("category", ""),
        "version": entry.get("version"),
        "package": "",
        # Skill body will be downloaded on-demand when the avatar invokes it
        "skill_id": entry.get("id", ""),
    }


def _build_avatar_skill_index(avatar: str, entries: list[dict]) -> dict:
    """Build a per-avatar skill index from catalog entries.

    Returns a dict mapping normalized aliases to skill dicts, filtered by the
    avatar's tag preferences.
    """
    index: dict[str, dict] = {}
    for entry in entries:
        if not _match_avatar_tags(entry):
            continue
        skill = _openhuman_to_lilly_skill(entry)
        key = normalize_text(entry.get("id", entry.get("name", "")))
        index[key] = skill
        for alias in skill.get("aliases", []):
            if alias and alias not in index:
                index[alias] = skill
    return index


async def load_openhuman_skills() -> int:
    """Fetch the OpenHuman catalog and merge skills into Lilly's SKILLS dict.

    Each avatar gets its own filtered index based on AVATAR_SKILL_TAGS.
    Skills are merged under the 'openhuman_' prefix to avoid colliding with
    built-in Android skills. Returns the count of merged skills.
    """
    entries = await _fetch_openhuman_catalog(force_refresh=False)
    if not entries:
        return 0

    total_merged = 0
    for avatar in HIVE_PERSONAS:
        avatar_skills = _build_avatar_skill_index(avatar, entries)
        _openhuman_avatar_skills[avatar] = avatar_skills

        # Merge into the global SKILLS dict with avatar-scoping
        for alias, skill in avatar_skills.items():
            scoped_key = f"openhuman_{alias}"
            SKILLS[scoped_key] = skill
            total_merged += 1

    # Also merge universal skills (no avatar filter) directly into SKILLS
    for entry in entries:
        if not _match_avatar_tags(entry) and current_avatar in HIVE_PERSONAS:
            # Check if this is a universal skill (no tags or tags that match all)
            skill_tags = entry.get("tags", [])
            allowed = AVATAR_SKILL_TAGS.get(current_avatar, [])
            if not allowed or not skill_tags:
                skill = _openhuman_to_lilly_skill(entry)
                key = normalize_text(entry.get("id", entry.get("name", "")))
                scoped_key = f"openhuman_{key}"
                if scoped_key not in SKILLS:
                    SKILLS[scoped_key] = skill
                    total_merged += 1

    logger.info(
        f"OpenHuman: merged {total_merged} skills across "
        f"{len(_openhuman_avatar_skills)} avatars"
    )
    return total_merged


def get_avatar_openhuman_skills(avatar: str | None = None) -> dict:
    """Get the OpenHuman skill index for a specific avatar.

    Falls back to the current avatar if none specified.
    """
    avatar = avatar or current_avatar
    if avatar not in _openhuman_avatar_skills:
        # Lazily build the index if it hasn't been loaded yet
        try:
            import asyncio

            entries = asyncio.run(_fetch_openhuman_catalog())
            _openhuman_avatar_skills[avatar] = _build_avatar_skill_index(
                avatar, entries
            )
        except RuntimeError:
            # asyncio.run can't be called from within an event loop
            logger.warning(
                f"OpenHuman: cannot build skill index for '{avatar}' outside event loop"
            )
            return {}
    return _openhuman_avatar_skills.get(avatar, {})


async def refresh_openhuman_skills() -> int:
    """Force a refresh of the OpenHuman catalog and rebuild all avatar indexes."""
    entries = await _fetch_openhuman_catalog(force_refresh=True)
    global _openhuman_avatar_skills
    _openhuman_avatar_skills = {}
    count = await load_openhuman_skills()

    # Persist merged skills to the skills file so they survive restarts
    if count > 0:
        raw = {}
        if SKILLS_FILE.exists():
            try:
                raw = json.loads(SKILLS_FILE.read_text())
            except Exception:
                pass
        # Only merge OpenHuman-prefixed skills (remove old ones first)
        raw = {k: v for k, v in raw.items() if not k.startswith("openhuman_")}
        for key, skill in SKILLS.items():
            if key.startswith("openhuman_"):
                raw[key] = skill
        SKILLS_FILE.write_text(json.dumps(raw, indent=2))
        logger.info(f"OpenHuman: persisted {count} skills to {SKILLS_FILE}")

    return count


async def execute_openhuman_skill(skill_id: str, avatar: str | None = None) -> str:
    """Execute an OpenHuman skill by downloading and running its SKILL.md.

    This is called from handle_intent() when an avatar triggers an
    openhuman_skill action. The SKILL.md is fetched from the catalog entry's
    download_url and executed as an agent task.
    """
    avatar = avatar or current_avatar
    avatar_skills = get_avatar_openhuman_skills(avatar)

    # Find the skill by id or normalized name
    skill = None
    skill_entry = None

    for alias, s in avatar_skills.items():
        if s.get("skill_id") == skill_id or normalize_text(
            s.get("label", "")
        ) == normalize_text(skill_id):
            skill = s
            skill_entry = s
            break

    if not skill:
        # Try the global catalog
        entries = await _fetch_openhuman_catalog()
        for entry in entries:
            if entry.get("id") == skill_id or normalize_text(
                entry.get("name", "")
            ) == normalize_text(skill_id):
                skill_entry = _openhuman_to_lilly_skill(entry)
                skill = entry
                break

    if not skill or not skill.get("download_url"):
        return f"I don't have a skill called '{skill_id}' loaded right now."

    # Download the SKILL.md if not already cached
    skill_dir = OPENHUMAN_SKILLS_DIR / normalize_text(skill_id)
    skill_file = skill_dir / "SKILL.md"

    if not skill_file.exists():
        skill_dir.mkdir(parents=True, exist_ok=True)
        try:
            async with httpx.AsyncClient(timeout=60.0) as client:
                # Rewrite GitHub blob URLs to raw
                dl_url = skill.get("download_url", "")
                if "github.com" in dl_url and "/blob/" in dl_url:
                    dl_url = dl_url.replace(
                        "github.com", "raw.githubusercontent.com"
                    ).replace("/blob/", "/")

                resp = await client.get(dl_url)
                if resp.status_code == 200:
                    skill_file.write_text(resp.text)
                    logger.info(
                        f"OpenHuman: downloaded SKILL.md for '{skill_id}' to {skill_file}"
                    )
                else:
                    logger.warning(
                        f"OpenHuman: failed to download SKILL.md for '{skill_id}': HTTP {resp.status_code}"
                    )
        except Exception as e:
            logger.error(f"OpenHuman: error downloading SKILL.md for '{skill_id}': {e}")

    if not skill_file.exists():
        return f"I couldn't load that skill right now. Try again in a moment."

    # Read the SKILL.md frontmatter for the skill's instructions
    skill_content = skill_file.read_text()
    skill_name = skill.get("label", skill_id)

    # The avatar reads the SKILL.md and executes it
    persona = HIVE_PERSONAS[resolve_persona_key(avatar)]
    avatar_name = persona.get("name", avatar)

    # Log that this avatar is executing an OpenHuman skill
    logger.info(
        f"OpenHuman: avatar '{avatar_name}' executing skill '{skill_id}' ({skill_name})"
    )

    return f"Running '{skill_name}' now."


async def list_openhuman_skills(avatar: str | None = None) -> list[dict]:
    """List all available OpenHuman skills for a specific avatar.

    Returns a list of skill dicts with id, name, description, and source.
    """
    avatar = avatar or current_avatar
    avatar_skills = get_avatar_openavatar_skills(avatar)
    if not avatar_skills:
        # Build the index if it's empty
        entries = await _fetch_openhuman_catalog()
        avatar_skills = _build_avatar_skill_index(avatar, entries)
        _openhuman_avatar_skills[avatar] = avatar_skills

    seen: set[str] = set()
    result = []
    for alias, skill in avatar_skills.items():
        skill_id = skill.get("skill_id", alias)
        if skill_id in seen:
            continue
        seen.add(skill_id)
        result.append(
            {
                "id": skill_id,
                "name": skill.get("label", skill_id),
                "description": skill.get("canned_reply", ""),
                "source": skill.get("source", "openhuman"),
                "category": skill.get("category", ""),
                "tags": skill.get("tags", []),
                "aliases": skill.get("aliases", []),
            }
        )
    return result


# Backwards-compatible alias
def get_avatar_openavatar_skills(avatar: str) -> dict:
    """Alias for get_avatar_openhuman_skills — kept for naming consistency."""
    return get_avatar_openhuman_skills(avatar)


async def save_memory():
    try:
        data = await memory.to_dict()
        # Prefer user-scoped memory file when a user is signed in
        if _current_user_id and AUTH_AVAILABLE:
            save_user_memory(_current_user_id, data)  # type: ignore[reportPossiblyUnboundVariable]
            # Also save to daily file for per-day context
            save_user_daily_memory(_current_user_id, current_avatar, data=data)  # type: ignore[reportPossiblyUnboundVariable]
            # Clean up old daily files (keep last 7 days)
            cleanup_old_daily_memories(_current_user_id, current_avatar)  # type: ignore[reportPossiblyUnboundVariable]
        else:
            path = _avatar_memory_file(current_avatar)
            path.write_text(json.dumps(data, indent=2))
        # Also save session history for cross-session catch-up
        await _save_session_history()
    except Exception as e:
        logger.warning(f"Failed to save memory: {e}")


async def load_memory():
    global memory, current_avatar
    current_avatar = "puppy"
    path = _avatar_memory_file(current_avatar)
    if path.exists():
        try:
            data = json.loads(path.read_text())
            memory = ConversationMemory.from_dict(data)
            await _clean_memory_artifacts()  # type: ignore[misc]
        except Exception:
            memory = ConversationMemory()
    else:
        memory = ConversationMemory()

    # Bootstrap: if the avatar memory is nearly empty, merge entries from
    # the legacy conversation_memory.json (orphaned pre-avatar-split history).
    if len(memory.entries) < 5:
        legacy_path = WORKSPACE / "conversation_memory.json"
        if legacy_path.exists():
            try:
                legacy = json.loads(legacy_path.read_text())
                legacy_entries = legacy.get("entries", [])
                legacy_summary = legacy.get("summary", "")
                # Merge legacy entries that aren't already present
                existing_texts = {e.text for e in memory.entries}
                for entry in legacy_entries:
                    text = entry.get("text", "")
                    role = entry.get("role", "user")
                    if text and text not in existing_texts:
                        memory.entries.append(
                            MemoryEntry(
                                role=role,
                                text=text,
                                timestamp=entry.get("timestamp", time.time()),
                            )
                        )
                        existing_texts.add(text)
                # Adopt legacy summary if we still don't have one
                if not memory.summary and legacy_summary:
                    memory.summary = legacy_summary
                logger.info(
                    f"Bootstrapped {len(legacy_entries)} legacy entries into memory"
                )
            except Exception as e:
                logger.warning(f"Failed to bootstrap from legacy memory: {e}")

    # Set a new session ID for this server session
    memory.session_id = f"session_{int(time.time())}_{current_avatar}"


current_avatar = "puppy"
# Tracks the Auth0 user ID for the *current in-flight request* so save_memory()
# can write to the correct per-user file even when called deep inside handle_intent().
_current_user_id: str = ""

# Per-user name store — isolates names so different Google accounts never see each other's names.
_USER_NAMES_FILE = WORKSPACE / "user_names.json"
_USER_NAMES: dict[str, str] = {}


def _load_user_names() -> None:
    global _USER_NAMES
    try:
        if _USER_NAMES_FILE.exists():
            _USER_NAMES = json.loads(_USER_NAMES_FILE.read_text())
    except Exception:
        _USER_NAMES = {}


def _save_user_names() -> None:
    try:
        _USER_NAMES_FILE.write_text(json.dumps(_USER_NAMES, indent=2))
    except Exception:
        pass


def _get_user_name(user_id: str = "") -> str:
    # "local" key covers anonymous sessions so the name still persists;
    # USER_NAME env is the operator-configured fallback.
    return (
        _USER_NAMES.get(user_id or "local", "")
        or _USER_NAMES.get("local", "")
        or os.environ.get("USER_NAME", "")
    )


def _set_user_name(user_id: str, name: str) -> None:
    _USER_NAMES[user_id or "local"] = name.strip()
    _save_user_names()  # persist immediately — names must survive restarts


# ─── USER FACTS STORE — persistent personal memory ───────────────
# Things the user states about themselves ("remember that I...", "my
# favorite...", their name) are stored here and injected into EVERY LLM
# call, so personal context survives window truncation and restarts.
_USER_FACTS_FILE = WORKSPACE / "user_facts.json"
_USER_FACTS: list[dict] = []  # {"fact": str, "ts": float}
_USER_FACTS_MAX = 60

# Daily memory context — populated per-request, consumed by _build_memory_hint()
_daily_recent_summaries: list = []
_daily_recent_entries: list = []


def _load_user_facts() -> None:
    global _USER_FACTS
    try:
        if _USER_FACTS_FILE.exists():
            data = json.loads(_USER_FACTS_FILE.read_text())
            if isinstance(data, list):
                _USER_FACTS = [f for f in data if isinstance(f, dict) and f.get("fact")]
                return
    except Exception:
        _USER_FACTS = []

    # Seed initial facts from user_profile.json and legacy conversation
    # so the AI has context from the very first message.
    if not _USER_FACTS:
        now = time.time()
        seed_facts = []
        # Extract from user_profile.json
        try:
            prof = json.loads((WORKSPACE / "user_profile.json").read_text())
            active_hours = prof.get("active_hours", {})
            if active_hours:
                top_hour = max(active_hours, key=lambda h: active_hours[h])
                seed_facts.append(
                    {
                        "kind": "habit",
                        "fact": f"User is most active around {top_hour}:00",
                        "ts": now,
                    }
                )
            interaction_count = prof.get("interaction_count", 0)
            if interaction_count > 100:
                seed_facts.append(
                    {
                        "kind": "context",
                        "fact": f"User has had {interaction_count} interactions with Lilly",
                        "ts": now,
                    }
                )
        except Exception:
            pass

        # Extract from legacy conversation — topics the user cared about
        try:
            legacy = json.loads((WORKSPACE / "conversation_memory.json").read_text())
            for entry in legacy.get("entries", []):
                text = entry.get("text", "").strip()
                role = entry.get("role", "")
                if role == "user" and text and len(text) > 5:
                    # Skip very short or meaningless entries
                    if text in ("really", "three", "here we go in"):
                        continue
                    seed_facts.append(
                        {
                            "kind": "conversation_topic",
                            "fact": f'User previously asked: "{text}"',
                            "ts": entry.get("timestamp", now),
                        }
                    )
        except Exception:
            pass

        if seed_facts:
            _USER_FACTS = seed_facts[:20]  # Cap at 20 seed facts
            _save_user_facts()
            logger.info(f"Seeded {len(_USER_FACTS)} initial user facts")


def _save_user_facts() -> None:
    try:
        _USER_FACTS_FILE.write_text(
            json.dumps(_USER_FACTS[-_USER_FACTS_MAX:], indent=2)
        )
    except Exception:
        pass


def _add_user_fact(kind: str, fact: str) -> None:
    """Store a personal fact (deduped, most-recent-wins for same text)."""
    fact = " ".join(str(fact).split())
    if len(fact) < 4:
        return
    global _USER_FACTS
    key = fact.lower()
    _USER_FACTS = [f for f in _USER_FACTS if f.get("fact", "").lower() != key]
    _USER_FACTS.append({"kind": kind, "fact": fact, "ts": time.time()})
    del _USER_FACTS[:-_USER_FACTS_MAX]
    _save_user_facts()


_load_user_facts()


# ─── SESSION HISTORY FOR CROSS-SESSION CATCH-UP ──────────────────
SESSION_HISTORY_DIR = MEMORY_DIR / "session_history"
SESSION_HISTORY_DIR.mkdir(exist_ok=True)


def _session_history_file(avatar: str, session_id: str) -> Path:
    """Return the session history file path for a given avatar and session."""
    safe_avatar = avatar.replace("/", "_").replace("..", "_")
    safe_session = session_id.replace("/", "_").replace("..", "_")
    return SESSION_HISTORY_DIR / f"{safe_avatar}_{safe_session}.json"


async def _save_session_history():
    """Save current session to history file for cross-session catch-up."""
    try:
        entries = await memory.snapshot()
        if len(entries) < 3:
            return  # Don't save very short sessions

        session_id = memory.session_id or f"session_{int(time.time())}"
        summary = memory.summary or ""

        # Generate summary if we have enough entries and no summary yet
        if len(entries) >= 8 and not summary:
            try:
                entries_text = "\n".join(f"{e.role}: {e.text}" for e in entries[:-4])
                prompt = f"Summarize this conversation in 2-3 sentences, focusing on key topics, decisions, and user preferences:\n{entries_text}"
                summary = await llama_backend.chat(
                    [
                        {
                            "role": "system",
                            "content": "Provide a concise 2-3 sentence summary capturing key topics and context.",
                        },
                        {"role": "user", "content": prompt},
                    ],
                    temperature=0.3,
                    max_tokens=200,
                )
                if summary:
                    await memory.add_session_summary(summary, session_id)
            except Exception as e:
                logger.warning(f"Session summary generation failed: {e}")

        # Save session data
        session_data = {
            "session_id": session_id,
            "avatar": current_avatar,
            "timestamp": time.time(),
            "entry_count": len(entries),
            "summary": summary,
            "entries": [
                {
                    "role": e.role,
                    "text": e.text[:200],  # Truncate long messages
                    "timestamp": e.timestamp,
                }
                for e in entries[-20:]  # Keep last 20 entries
            ],
            "key_topics": _extract_key_topics(entries),
        }

        path = _session_history_file(current_avatar, session_id)
        path.write_text(json.dumps(session_data, indent=2))

        # Cleanup old sessions (keep last 20 per avatar)
        await _cleanup_old_sessions(current_avatar)

    except Exception as e:
        logger.warning(f"Failed to save session history: {e}")


def _extract_key_topics(entries: list) -> list[str]:
    """Extract key topics from conversation entries."""
    topics = []
    keywords = [
        "project",
        "work",
        "idea",
        "plan",
        "goal",
        "problem",
        "solution",
        "learn",
        "create",
        "build",
        "fix",
        "improve",
        "design",
        "code",
        "test",
        "deploy",
        "config",
        "setup",
        "install",
        "update",
    ]

    for entry in entries:
        text = entry.text.lower()
        for kw in keywords:
            if kw in text and kw not in topics:
                topics.append(kw)
                if len(topics) >= 5:
                    return topics
    return topics


async def _cleanup_old_sessions(avatar: str, keep: int = 20):
    """Keep only the last N session history files per avatar."""
    try:
        safe_avatar = avatar.replace("/", "_").replace("..", "_")
        pattern = f"{safe_avatar}_*.json"
        files = sorted(
            SESSION_HISTORY_DIR.glob(pattern), key=lambda f: f.stat().st_mtime
        )

        if len(files) > keep:
            for f in files[:-keep]:
                f.unlink()
    except Exception as e:
        logger.warning(f"Session cleanup failed: {e}")


async def get_catchup_context(avatar: str = "", n_sessions: int = 3) -> str:
    """Build rich catch-up context from recent sessions for the LLM."""
    avatar = avatar or current_avatar
    hints = []

    try:
        # Get last N session summaries from memory
        recent_summaries = await memory.get_recent_session_summaries(n_sessions)
        if recent_summaries:
            for i, s in enumerate(recent_summaries):
                summary_text = s.get("summary", "")
                session_ts = s.get("timestamp", 0)
                if summary_text:
                    time_ago = (
                        _format_time_ago(time.time() - session_ts)
                        if session_ts
                        else "recently"
                    )
                    hints.append(f"Session {i + 1} ({time_ago}): {summary_text}")

        # Also load from session history files
        safe_avatar = avatar.replace("/", "_").replace("..", "_")
        pattern = f"{safe_avatar}_*.json"
        files = sorted(
            SESSION_HISTORY_DIR.glob(pattern),
            key=lambda f: f.stat().st_mtime,
            reverse=True,
        )

        for f in files[:n_sessions]:
            try:
                data = json.loads(f.read_text())
                summary = data.get("summary", "")
                key_topics = data.get("key_topics", [])
                ts = data.get("timestamp", 0)
                time_ago = _format_time_ago(time.time() - ts) if ts else "recently"

                if summary:
                    hints.append(f"Past conversation ({time_ago}): {summary}")
                if key_topics:
                    hints.append(f"Topics discussed: {', '.join(key_topics)}")
            except Exception:
                continue

        # Pull L1 atoms from TencentDB (user preferences, facts)
        mem = await _get_lilly_memory()
        if mem is not None:
            try:
                facts = await mem.search_facts(
                    "user preference OR user fact OR project OR goal", limit=8
                )
                if facts:
                    fact_parts = []
                    for f_item in facts:
                        k = f_item.get("id") or f_item.get("key") or "unknown"
                        v = f_item.get("content") or f_item.get("value") or ""
                        fact_parts.append(f"{k}={str(v)[:100]}")
                    fact_str = "; ".join(fact_parts)[:400]
                    if fact_str:
                        hints.append(f"Remembered facts: {fact_str}")
            except Exception:
                pass

        # Pull taught contexts (locations, device names)
        try:
            taught = json.loads((WORKSPACE / "taught_contexts.json").read_text())
            if taught:
                taught_items = list(taught.items())[:5]
                taught_str = "; ".join(f"{k}: {v}" for k, v in taught_items)
                hints.append(f"Known contexts: {taught_str}")
        except Exception:
            pass

    except Exception as e:
        logger.warning(f"catchup context build failed: {e}")

    return " | ".join(hints) if hints else ""


def _format_time_ago(seconds: float) -> str:
    """Format seconds into a human-readable time ago string."""
    if seconds < 60:
        return "just now"
    elif seconds < 3600:
        mins = int(seconds / 60)
        return f"{mins}m ago"
    elif seconds < 86400:
        hours = int(seconds / 3600)
        return f"{hours}h ago"
    else:
        days = int(seconds / 86400)
        return f"{days}d ago"


# ─── FULL CONVERSATION HISTORY (JSONL) ──────────────────────────
# Every conversation turn is appended to a JSONL file for permanent storage.
# This is separate from the deque (which is limited to 50 entries).
CONVERSATION_HISTORY_FILE = MEMORY_DIR / "conversation_history.jsonl"


async def _record_conversation_turn(
    user_msg: str, assistant_reply: str, avatar: str = ""
):
    """Append a conversation turn to the permanent history file."""
    try:
        avatar = avatar or current_avatar
        entry = {
            "ts": time.time(),
            "avatar": avatar,
            "user": user_msg[:500],  # Truncate very long messages
            "assistant": assistant_reply[:500],
            "session_id": memory.session_id,
        }
        with open(CONVERSATION_HISTORY_FILE, "a") as f:
            f.write(json.dumps(entry) + "\n")
    except Exception as e:
        logger.warning(f"Failed to record conversation turn: {e}")


async def _load_recent_conversation_history(n: int = 20) -> list[dict]:
    """Load the last N conversation turns from the permanent history."""
    try:
        if not CONVERSATION_HISTORY_FILE.exists():
            # Bootstrap: seed from legacy conversation_memory.json
            legacy_path = WORKSPACE / "conversation_memory.json"
            if legacy_path.exists():
                try:
                    legacy = json.loads(legacy_path.read_text())
                    entries = legacy.get("entries", [])
                    # Write legacy entries as JSONL turns
                    with open(CONVERSATION_HISTORY_FILE, "a") as f:
                        i = 0
                        while i < len(entries) - 1:
                            user_entry = entries[i]
                            assistant_entry = entries[i + 1]
                            if (
                                user_entry.get("role") == "user"
                                and assistant_entry.get("role") == "assistant"
                            ):
                                turn = {
                                    "ts": user_entry.get("timestamp", time.time()),
                                    "avatar": "puppy",
                                    "user": user_entry.get("text", ""),
                                    "assistant": assistant_entry.get("text", ""),
                                    "session_id": "legacy_bootstrap",
                                }
                                f.write(json.dumps(turn) + "\n")
                                i += 2
                            else:
                                i += 1
                    logger.info(
                        "Bootstrapped conversation_history.jsonl from legacy file"
                    )
                except Exception as e:
                    logger.warning(f"Failed to bootstrap JSONL history: {e}")
            return []
        lines = CONVERSATION_HISTORY_FILE.read_text().strip().split("\n")
        # Get last N lines
        recent_lines = lines[-n:] if len(lines) > n else lines
        entries = []
        for line in recent_lines:
            if line.strip():
                try:
                    entries.append(json.loads(line))
                except Exception:
                    continue
        return entries
    except Exception as e:
        logger.warning(f"Failed to load conversation history: {e}")
        return []


async def _get_conversation_topics(days: int = 7) -> list[str]:
    """Extract topics from recent conversation history."""
    try:
        cutoff = time.time() - (days * 86400)
        if not CONVERSATION_HISTORY_FILE.exists():
            return []

        topics = set()
        keywords = [
            "project",
            "work",
            "idea",
            "plan",
            "goal",
            "problem",
            "solution",
            "learn",
            "create",
            "build",
            "fix",
            "improve",
            "design",
            "code",
            "test",
            "deploy",
            "config",
            "setup",
            "install",
            "update",
            "deploy",
            "openlive",
            "openhuman",
            "lilly",
            "avatar",
            "sensor",
            "camera",
            "voice",
            "chat",
            "memory",
            "context",
            "session",
        ]

        lines = CONVERSATION_HISTORY_FILE.read_text().strip().split("\n")
        for line in lines:
            if not line.strip():
                continue
            try:
                entry = json.loads(line)
                if entry.get("ts", 0) < cutoff:
                    continue
                text = (
                    entry.get("user", "") + " " + entry.get("assistant", "")
                ).lower()
                for kw in keywords:
                    if kw in text:
                        topics.add(kw)
            except Exception:
                continue

        return list(topics)[:15]
    except Exception as e:
        logger.warning(f"Failed to extract topics: {e}")
        return []


def _save_user_names() -> None:
    try:
        _USER_NAMES_FILE.write_text(json.dumps(_USER_NAMES, indent=2))
    except Exception:
        pass


def _extract_real_name(user_info: Optional[dict]) -> str:
    """Extract a human first name from Auth0/Google profile.

    Priority:
    1. given_name (Google OAuth profile scope)
    2. nickname (Auth0)
    3. name (full name) — first word, unless it's just the email prefix
    4. Email prefix, formatted nicely
    """
    if not user_info:
        return ""
    email = user_info.get("email", "")
    email_prefix = email.split("@")[0].lower() if email else ""

    # 1. Google OAuth given_name
    given = (user_info.get("given_name") or "").strip()
    if given and given.lower() != email_prefix:
        return given.split()[0]

    # 2. Auth0 nickname
    nickname = (user_info.get("nickname") or "").strip()
    if nickname and nickname.lower() != email_prefix:
        return nickname.split()[0]

    # 3. Full name — reject if it's just the email prefix or "User"
    name = (user_info.get("name") or "").strip()
    if name and name not in ("User", "user") and name.lower() != email_prefix:
        first = name.split()[0]
        first = re.sub(r"[._-]+", "", first)
        if first:
            return first

    # 4. Fallback: derive from email prefix
    if email_prefix:
        parts = re.split(r"[._-]", email_prefix)
        return parts[0].capitalize() if parts else ""

    return ""


def _avatar_memory_file(avatar: str) -> Path:
    """Return the memory file path for a given avatar."""
    safe = avatar.replace("/", "_").replace("..", "_")
    return MEMORY_DIR / f"conversation_memory_{safe}.json"


async def _clean_memory_artifacts():
    """Remove Whisper hallucination entries from conversation memory on startup.

    Preserves disfluencies (um, uh, hmm, etc.) as they are real speech cues.
    Only removes true noise artifacts: foreign script hallucinations,
    repeated-word patterns, and known Whisper media hallucinations.
    """
    async with memory._lock:
        original_len = len(memory.entries)
        cleaned = []
        for entry in memory.entries:
            text = entry.text.strip()
            # Skip noise entries from user side — but preserve disfluencies
            if entry.role == "user":
                if is_hallucination(text) or text in PHANTOMS:
                    continue
                # Don't filter entries that contain disfluencies — they're real speech
                if len(text) < 2:
                    continue
            cleaned.append(entry)

        if len(cleaned) < original_len:
            removed = original_len - len(cleaned)
            logger.info(
                f"Memory cleanup: removed {removed} noise artifacts from {original_len} entries"
            )
            memory.entries.clear()
            for entry in cleaned:
                memory.entries.append(entry)
            # Reset summary since entries changed
            if removed > 0:
                memory.summary = ""


# ─── HARDWARE & OS INTEGRATIONS ─────────────────────────────────
async def whisper_stt(
    audio_bytes: Optional[bytes] = None,
    file_path: Optional[Path] = None,
    content_type: str = "audio/wav",
    filename: str = "input.wav",
) -> str:
    """Transcribe audio using faster-whisper-server HTTP API with audio pre-processing.

    Returns transcribed text or empty string if:
    - Audio is too quiet / noise floor
    - Whisper language confidence is too low
    - Transcription is detected as a hallucination
    """
    wav_data = audio_bytes
    if file_path and file_path.exists():
        wav_data = file_path.read_bytes()
        ext = file_path.suffix.lower()
        mime_map = {
            ".wav": "audio/wav",
            ".webm": "audio/webm",
            ".ogg": "audio/ogg",
            ".mp3": "audio/mpeg",
            ".m4a": "audio/mp4",
        }
        content_type = mime_map.get(ext, content_type)
        filename = file_path.name
    if not wav_data or len(wav_data) < 100:
        return ""

    # Pre-process audio: convert to 16kHz mono WAV with minimal filtering
    # The browser already applies echo cancellation, noise suppression, and AGC.
    # Only do format conversion, skip the expensive filter chain to save ~300ms.
    try:
        proc = await asyncio.create_subprocess_exec(
            "ffmpeg",
            "-y",
            "-i",
            "pipe:0",
            "-af",
            "aresample=16000,aformat=sample_fmts= s16,channels=1",
            "-ar",
            "16000",
            "-ac",
            "1",
            "-f",
            "wav",
            "pipe:1",
            stdin=asyncio.subprocess.PIPE,
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.DEVNULL,
        )
        processed, _ = await proc.communicate(input=wav_data)
        if processed and len(processed) > 100:
            wav_data = processed
            content_type = "audio/wav"
            filename = "input.wav"
    except Exception as e:
        logger.debug(f"Audio pre-processing failed (using raw): {e}")

    # Pass 1: auto-detect language (NO forced language — forcing "en" caused
    # Spanish/other speech to be mangled into English gibberish, which the UI
    # then showed as vulgarity). Returns verbose_json so we can read language
    # + segment-level no-speech/log-prob filters.
    try:
        c = await _get_whisper_client()
        files = {"file": (filename, wav_data, content_type)}
        data = {
            "model_name": WHISPER_MODEL,
            "response_format": "verbose_json",
            # No "language" field → Whisper auto-detects the spoken language.
            "prompt": WHISPER_INITIAL_PROMPT,
            "temperature": str(WHISPER_TEMPERATURE),
        }
        r = await c.post(
            f"{WHISPER_SERVER_URL}/v1/audio/transcriptions",
            files=files,
            data=data,
            timeout=60.0,
        )
        if r.status_code == 200:
            try:
                result = r.json()
                text = result.get("text", "").strip()
                detected_lang = result.get("language", "")
                lang_prob = result.get(
                    "language_probability", result.get("probability", 1.0)
                )
                if lang_prob is None:
                    lang_prob = 1.0

                # Real speech, non-English (e.g. user speaks Spanish) → translate
                # to English in real time so it appears in English on screen.
                if detected_lang and detected_lang not in ("en", "eng", ""):
                    logger.debug(
                        f"STT: non-English heard (lang={detected_lang}, prob={lang_prob:.2f}) — translating to English"
                    )
                    en_text = await _translate_audio(wav_data, content_type, filename)
                    if en_text:
                        return _filter_offensive_language(en_text)
                    # Translation unavailable → fall through to original text
                    return _filter_offensive_language(normalize_text(text))

                if lang_prob < 0.6:
                    logger.debug(
                        f"STT: low confidence ({lang_prob:.2f}), discarding: {text[:50]}"
                    )
                    return ""

                # Filter segments with high no_speech_prob (Silero VAD proxy)
                # This catches "Thank you" hallucinations on silence/noise
                segments = result.get("segments", [])
                if segments:
                    filtered_segments = []
                    for seg in segments:
                        no_speech = seg.get("no_speech_prob", 0.0)
                        avg_logprob = seg.get("avg_logprob", -1.0)
                        seg_text = seg.get("text", "").strip()
                        if not seg_text:
                            continue
                        # Skip segments that are mostly silence/noise
                        if no_speech > 0.5:
                            logger.debug(
                                f"STT: filtered no_speech segment (prob={no_speech:.2f}): '{seg_text[:50]}'"
                            )
                            continue
                        # Skip segments with very low log probability (garbage)
                        if avg_logprob < -2.0:
                            logger.debug(
                                f"STT: filtered low-logprob segment (log={avg_logprob:.2f}): '{seg_text[:50]}'"
                            )
                            continue
                        filtered_segments.append(seg_text)
                    if not filtered_segments:
                        return ""
                    text = " ".join(filtered_segments).strip()

                return _filter_offensive_language(normalize_text(text))
            except (json.JSONDecodeError, KeyError):
                return _filter_offensive_language(normalize_text(r.text))
        logger.debug(f"STT server returned {r.status_code}: {r.text[:200]}")
    except Exception as e:
        logger.debug(f"STT error: {e}")

    # Fallback: try without verbose_json (auto-detect, no forced language)
    try:
        c = await _get_whisper_client()
        files = {"file": (filename, wav_data, content_type)}
        data = {
            "model_name": WHISPER_MODEL,
            "response_format": "text",
            "prompt": WHISPER_INITIAL_PROMPT,
            "temperature": str(WHISPER_TEMPERATURE),
        }
        r = await c.post(
            f"{WHISPER_SERVER_URL}/v1/audio/transcriptions",
            files=files,
            data=data,
            timeout=60.0,
        )
        if r.status_code == 200:
            return _filter_offensive_language(normalize_text(r.text))
    except Exception as e:
        logger.debug(f"STT fallback error: {e}")
    return ""


async def _translate_audio(
    wav_data: bytes, content_type: str = "audio/wav", filename: str = "input.wav"
) -> str:
    """Translate any-language audio to English text.

    Uses the OpenAI-compatible /v1/audio/translations endpoint (output is
    always English). Called when Whisper auto-detects a non-English language
    so that e.g. Spanish speech appears as English on screen.
    """
    if not wav_data or len(wav_data) < 100:
        return ""
    try:
        c = await _get_whisper_client()
        files = {"file": (filename, wav_data, content_type)}
        data = {
            "model_name": WHISPER_MODEL,
            "response_format": "verbose_json",
            "temperature": str(WHISPER_TEMPERATURE),
        }
        r = await c.post(
            f"{WHISPER_SERVER_URL}/v1/audio/translations",
            files=files,
            data=data,
            timeout=60.0,
        )
        if r.status_code == 200:
            try:
                result = r.json()
                text = result.get("text", "").strip()
                if not text:
                    return ""
                # Keep only real-speech segments (drop silence/noise)
                segments = result.get("segments", [])
                if segments:
                    parts = []
                    for seg in segments:
                        if seg.get("no_speech_prob", 0.0) > 0.6:
                            continue
                        s = seg.get("text", "").strip()
                        if s:
                            parts.append(s)
                    if parts:
                        text = " ".join(parts)
                    else:
                        return ""
                return _filter_offensive_language(normalize_text(text))
            except (json.JSONDecodeError, KeyError):
                return _filter_offensive_language(normalize_text(r.text))
        logger.debug(f"STT translate endpoint returned {r.status_code}: {r.text[:200]}")
    except Exception as e:
        logger.debug(f"STT translate error: {e}")
    return ""


# ─── SSML HELPERS ──────────────────────────────────────────────
# Mood → SSML prosody presets for expressive speech
SSML_PRESETS = {
    "calm": '<prosody rate="medium" pitch="+5%" volume="medium">%s</prosody>',
    "curious": '<prosody rate="medium" pitch="+12%" volume="medium">%s</prosody>',
    "cheerful": '<prosody rate="fast" pitch="+22%" volume="loud">%s</prosody>',
    "excited": '<prosody rate="x-fast" pitch="+28%" volume="x-loud">%s</prosody>',
    "gentle": '<prosody rate="slow" pitch="+2%" volume="soft">%s</prosody>',
    "warm": '<prosody rate="medium" pitch="+8%" volume="medium">%s</prosody>',
    "creative": '<prosody rate="medium" pitch="+12%" volume="medium">%s</prosody>',
    "worried": '<prosody rate="slow" pitch="-5%" volume="soft">%s</prosody>',
    "sad": '<prosody rate="x-slow" pitch="-8%" volume="soft">%s</prosody>',
    "angry": '<prosody rate="fast" pitch="-8%" volume="loud">%s</prosody>',
}

# Per-character SSML prosody adjustments layered ON TOP of the base mood preset.
# These nudge rate/pitch so the character's natural voice colours the mood expression —
# e.g. Bear's "cheerful" is still slower and deeper than Puppy's "cheerful".
# Format: (rate_modifier, pitch_modifier_pct)
CHAR_SSML_NUDGE: dict[str, tuple[str, int]] = {
    # char    rate-nudge    pitch-nudge (percentage points added to preset)
    "puppy": ("medium", 0),  # baseline — no change
    "fox": ("fast", +8),  # always a little faster and higher
    "cat": ("medium", -4),  # flatten mood peaks — stays measured
    "bear": ("slow", -10),  # pulls everything down and slow
    "bunny": ("x-fast", +10),  # always excited baseline
    "owl": ("slow", -6),  # deliberate, never rushed
    "deer": ("medium", -2),  # gentle nudge down — calm presence
    "wolf": ("fast", -8),  # fast but low — clipped intensity
    "raccoon": ("fast", +4),  # quick and a touch bright
}


def wrap_ssml_for_char(text: str, mood: str, char_key: str) -> str:
    """Wrap text in SSML prosody blending base mood preset with per-character nudge."""
    template = SSML_PRESETS.get(mood, SSML_PRESETS["calm"])
    # Extract the base rate and pitch from the preset string
    rate_match = re.search(r'rate="([^"]+)"', template)
    pitch_match = re.search(r'pitch="([+-]?\d+)%"', template)
    base_rate = rate_match.group(1) if rate_match else "medium"
    base_pitch = int(pitch_match.group(1)) if pitch_match else 0

    char_rate_nudge, char_pitch_nudge = CHAR_SSML_NUDGE.get(
        char_key or "puppy", ("medium", 0)
    )

    # Blend: character rate wins if it's more extreme than the mood rate
    rate_order = ["x-slow", "slow", "medium", "fast", "x-fast"]
    base_idx = rate_order.index(base_rate) if base_rate in rate_order else 2
    nudge_idx = (
        rate_order.index(char_rate_nudge) if char_rate_nudge in rate_order else 2
    )
    final_rate = rate_order[
        max(
            0,
            min(
                4,
                (base_idx + nudge_idx) // 2
                + (1 if nudge_idx > base_idx else -1 if nudge_idx < base_idx else 0),
            ),
        )
    ]

    # Pitch: add nudge to base
    final_pitch = base_pitch + char_pitch_nudge
    pitch_str = f"+{final_pitch}%" if final_pitch >= 0 else f"{final_pitch}%"

    vol_match = re.search(r'volume="([^"]+)"', template)
    vol = vol_match.group(1) if vol_match else "medium"

    return (
        f'<speak><prosody rate="{final_rate}" pitch="{pitch_str}" '
        f'volume="{vol}">{text}</prosody></speak>'
    )


def strip_ssml(text: str) -> str:
    """Remove SSML tags leaving only plain text for Piper TTS."""
    return re.sub(r"<[^>]+>", "", text).strip()


def wrap_ssml(text: str, mood: str = "calm") -> str:
    """Wrap plain text in SSML prosody based on mood."""
    template = SSML_PRESETS.get(mood, SSML_PRESETS["calm"])
    return f"<speak>{template.replace('%s', text, 1)}</speak>"


def mood_from_text(text: str) -> str:
    t = text.lower()
    if any(w in t for w in ["sorry", "apologize", "my fault", "forgive"]):
        return "gentle"
    if any(w in t for w in ["great", "awesome", "fun", "cool", "happy", "yay", "wow"]):
        return "cheerful"
    if any(w in t for w in ["excited", "amazing", "incredible", "thrilled"]):
        return "excited"
    if any(w in t for w in ["worried", "concerned", "nervous", "afraid"]):
        return "worried"
    if any(w in t for w in ["sad", "unfortunate", "miss", "regret"]):
        return "sad"
    if any(w in t for w in ["angry", "furious", "annoyed"]):
        return "angry"
    if any(w in t for w in ["warm", "cozy", "comfort", "snug"]):
        return "warm"
    if "?" in t:
        return "curious"
    return "calm"


async def speak(text: str, use_toast: bool = True, char_key: Optional[str] = None):
    """Speak text via Piper TTS with SSML-expressive prosody and per-character voice."""
    global \
        LILLY_IS_SPEAKING, \
        LILLY_IS_THINKING, \
        LILLY_MOOD, \
        LAST_SPOKEN, \
        PHONEME_QUEUE, \
        MOUTH_OPEN, \
        SPEAKING_SESSION_ID
    global AUDIO_CACHE, AUDIO_CACHE_ID, _RECENT_SPEECH
    raw_text = text.replace("\n", " ").strip()
    if not raw_text:
        return 0

    LILLY_IS_SPEAKING = True
    LILLY_IS_THINKING = False

    # Derive mood from text content
    LILLY_MOOD = mood_from_text(raw_text)

    # Generate SSML envelope blending mood + per-character voice nudge
    _char = char_key or current_avatar or "puppy"
    ssml_text = wrap_ssml_for_char(raw_text, LILLY_MOOD, _char)

    # Strip SSML for Piper (doesn't support SSML natively), keep for logging/UI
    clean = strip_ssml(ssml_text)

    # Show toast on phone simultaneously with speech
    if use_toast:
        asyncio.create_task(
            termux_run(
                ["termux-toast", "-s", "-g", "bottom", clean[:200]],
                timeout=3.0,
            )
        )

    # Look up per-character voice profile
    voice = CHAR_VOICE.get(char_key or current_avatar or "puppy", CHAR_VOICE["puppy"])

    # Generate audio with Piper (in thread to avoid blocking event loop)
    audio_aid = 0
    piper_found = os.path.exists(PIPER_BIN)

    # Get character-specific ONNX voice file
    char_onnx = voice.get("onnx", "")
    if char_onnx:
        char_voice_path = str(Path(__file__).parent / "lillyos" / "voices" / char_onnx)
    else:
        char_voice_path = PIPER_VOICE

    voice_found = os.path.exists(char_voice_path)
    if piper_found and voice_found:
        try:

            def _run_piper():
                # Apply per-character voice profile
                pace_scale = voice["length_scale"]
                noise_scale = voice["noise_scale"]
                noise_w = voice["noise_w"]
                proc = subprocess.Popen(
                    [
                        PIPER_BIN,
                        "--model",
                        char_voice_path,
                        "--output-raw",
                        "--noise-scale",
                        f"{noise_scale:.3f}",
                        "--noise-w",
                        f"{noise_w:.3f}",
                        "--length-scale",
                        f"{pace_scale:.2f}",
                    ],
                    stdin=subprocess.PIPE,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                )
                raw, stderr = proc.communicate(
                    input=(clean + "\n").encode(), timeout=30.0
                )
                if proc.returncode != 0:
                    logger.error(
                        f"Piper TTS failed (rc={proc.returncode}): {stderr.decode()[:200]}"
                    )
                return raw

            raw = await asyncio.to_thread(_run_piper)
            # Apply pitch shift for character voice distinctiveness
            pitch_semitones = voice.get("pitch_shift", 0)
            if raw and pitch_semitones != 0:
                raw = _pitch_shift_audio(raw, pitch_semitones)
            if raw and len(raw) > 44:
                import struct, io, wave

                buf = io.BytesIO()
                with wave.open(buf, "wb") as w:
                    w.setnchannels(1)
                    w.setsampwidth(2)
                    w.setframerate(22050)
                    w.writeframes(raw)
                async with AUDIO_CACHE_LOCK:
                    audio_aid = AUDIO_CACHE_ID + 1
                    AUDIO_CACHE_ID = audio_aid
                    AUDIO_CACHE[audio_aid] = buf.getvalue()
                    while len(AUDIO_CACHE) > 5:
                        oldest = min(AUDIO_CACHE)
                        del AUDIO_CACHE[oldest]
        except Exception as e:
            logger.error(f"Piper TTS error: {e}")
    else:
        logger.warning(
            f"Piper TTS not available — PIPER_BIN={PIPER_BIN} (exists={piper_found}), PIPER_VOICE={PIPER_VOICE} (exists={voice_found})"
        )

    # Set spoken text AFTER caching audio so pollState sees audio_id too
    LAST_SPOKEN = clean
    LAST_SSML = ssml_text
    _record_recent_speech(clean)
    SPEAKING_SESSION_ID += 1
    _LAST_SPOKEN_SESSION_ID = SPEAKING_SESSION_ID

    phoneme_timings, total_dur = estimate_phoneme_duration(clean)
    PHONEME_QUEUE.clear()
    for dur in phoneme_timings:
        PHONEME_QUEUE.append(dur)

    # Don't block — let the sleep run in background so /api/cmd returns immediately
    # (allows browser to play audio while the user gesture is still active)
    async def _finish_speech():
        global LILLY_IS_SPEAKING, CONVERSATION_LAST_ACTIVITY, MIC_COOLDOWN_UNTIL
        await asyncio.sleep(total_dur)
        LILLY_IS_SPEAKING = False
        # ── Fix #1: hold mic quiet for MIC_COOLDOWN_SECS after Lilly stops speaking
        MIC_COOLDOWN_UNTIL = time.time() + MIC_COOLDOWN_SECS
        CONVERSATION_LAST_ACTIVITY = (
            time.time()
        )  # reset timeout after Lilly finishes speaking
        PHONEME_QUEUE.clear()
        MOUTH_OPEN = 0.0

    asyncio.create_task(_finish_speech())


# ─── TERMUX SSH HELPER ──────────────────────────────────────────
# Uses SSH ControlMaster multiplexing — handshake once, reuse for all commands.
SSH_CONTROL_SOCKET = "/tmp/lilly_ssh_mux_%h_%p"


async def termux_run(args: list[str], timeout: float = 10.0) -> tuple[str, str]:
    """Run a command on the phone via SSH, or fall back to the HTTP sensor
    server when SSH is not configured or fails. Returns (stdout, stderr)."""
    import shlex

    host = os.environ.get("TERMUX_SSH_HOST", "")
    port = os.environ.get("TERMUX_SSH_PORT", "8022")
    user = os.environ.get("TERMUX_SSH_USER", "")
    ssh_key = os.environ.get("TERMUX_SSH_KEY", "")
    if not host or not user:
        # Fall back to sensor server's /shell endpoint
        return await _sensor_server_shell(args, timeout)
    cmd_str = " ".join(shlex.quote(a) for a in args)
    ssh_cmd = [
        "ssh",
        "-p",
        port,
        "-o",
        "ConnectTimeout=5",
        "-o",
        "StrictHostKeyChecking=no",
        "-o",
        "ControlMaster=auto",
        "-o",
        f"ControlPath={SSH_CONTROL_SOCKET}",
        "-o",
        "ControlPersist=120",
    ]
    # Use identity key if specified
    if ssh_key:
        import os.path as _osp

        key_expanded = _osp.expanduser(ssh_key)
        if _osp.exists(key_expanded):
            ssh_cmd.extend(["-i", key_expanded])
    ssh_cmd.extend([f"{user}@{host}", cmd_str])
    try:
        proc = await asyncio.create_subprocess_exec(
            *ssh_cmd,
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
        )
        stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=timeout)
        stdout_s = stdout.decode()
        stderr_s = stderr.decode()
        # If SSH auth fails, fall back to sensor server
        if "Permission denied" in stderr_s or "publickey" in stderr_s:
            logger.debug("SSH auth failed — falling back to sensor server /shell")
            return await _sensor_server_shell(args, timeout)
        return stdout_s, stderr_s
    except asyncio.TimeoutError:
        return "", "SSH timeout"
    except FileNotFoundError:
        return "", "ssh client not found in container"
    except Exception as e:
        return "", str(e)


async def _sensor_server_shell(
    args: list[str], timeout: float = 10.0
) -> tuple[str, str]:
    """Execute a command on the phone via the HTTP sensor server /shell endpoint.

    The sensor server accepts:
      - termux-* commands (e.g. termux-location, termux-sensor, termux-open-url)
      - 'open <package>' for app launching

    am start commands are translated to 'open <package>' format.
    """
    import shlex

    cmd_str = " ".join(shlex.quote(a) for a in args)

    # Translate 'am start -p <pkg>' or 'am start -a <action> -p <pkg>' to 'open <pkg>'
    if cmd_str.startswith("am "):
        # Extract package from -p flag
        if "-p" in cmd_str:
            parts = cmd_str.split()
            idx = parts.index("-p")
            if idx + 1 < len(parts):
                pkg = parts[idx + 1]
                # If there's a URI intent (intent_action with -d), use termux-open-url
                if "-a" in parts and "-d" in parts:
                    dash_idx = parts.index("-d")
                    if dash_idx + 1 < len(parts):
                        url = parts[dash_idx + 1]
                        cmd_str = f"termux-open-url {url}"
                else:
                    cmd_str = f"open {pkg}"

    try:
        c = await _get_sensor_client()
        r = await c.post(
            f"{SENSOR_SERVER_URL}/shell",
            json={"command": cmd_str},
            timeout=min(timeout, 15.0),
        )
        if r.status_code == 200:
            data = r.json()
            output = data.get("output", "")
            return output, ""
        else:
            error = (
                r.json().get("message", "unknown error")
                if r.headers.get("content-type", "").startswith("application/json")
                else r.text[:200]
            )
            return "", f"Sensor server error: {error}"
    except Exception as e:
        return "", str(e)


