async def sensor_conversation_engine():
    """Fusion-based context engine: reads all sensors, infers what's happening, starts conversation."""
    global _LAST_CONTEXT_CONVO, LILLY_MOOD, LILLY_IS_THINKING
    await asyncio.sleep(12)
    while True:
        await asyncio.sleep(20)
        if LILLY_IS_SPEAKING or LILLY_IS_THINKING or WAITING_FOR_PROMPT:
            continue
        now = time.time()
        if now - _LAST_CONTEXT_CONVO < 600:  # 10 min cooldown (was 2 — too chatty)
            continue
        # Don't interrupt an active/recent conversation with sensor small talk
        if (now - CONVERSATION_LAST_ACTIVITY) < 180:
            continue
        snap = await take_snapshot()
        if snap.age() > 5:
            continue
        contexts = infer_context(snap)
        if not contexts:
            continue
        # Pick the most interesting context — prefer ones user engages with
        base_priority = [
            "taught",
            "vehicle",
            "just_picked_up",
            "significant_motion",
            "walking",
            "outdoors",
            "sleeping",
            "on_call",
            "very_bright",
            "dark",
            "resting",
        ]
        preferred = user_profile.preferred_contexts()
        priority = sorted(
            base_priority,
            key=lambda c: (c in preferred, base_priority.index(c)),
            reverse=True,
        )
        chosen = None
        taught_label = None
        for p in priority:
            if p == "taught":
                for c in contexts:
                    if c.startswith("taught:"):
                        chosen = "taught"
                        taught_label = c.split(":", 1)[1]
                        break
            elif p in contexts:
                chosen = p
                break
        if not chosen:
            chosen = contexts[0]
        if chosen == "taught" and taught_label:
            msgs = [
                f"Feels like we're {taught_label} again — the sensors match. Am I right?",
                f"This feels familiar — same sensor pattern as {taught_label}. Back there?",
            ]
            msg = _pick_fresh(f"ctx:taught:{taught_label}", msgs)
        else:
            # Rotate through the pool so the same opener never repeats back-to-back
            msg = _pick_fresh(
                f"ctx:{chosen}",
                _CONTEXT_MESSAGES.get(
                    chosen, ["Nothing unusual on the sensors right now."]
                ),
            )
        # Think pulse
        LILLY_IS_THINKING = True
        await asyncio.sleep(0.8 + random.random() * 0.5)
        LILLY_IS_THINKING = False
        mood_map = {
            "vehicle": "curious",
            "walking": "cheerful",
            "outdoors": "excited",
            "resting": "calm",
            "sleeping": "gentle",
            "on_call": "gentle",
            "just_picked_up": "warm",
            "dark": "calm",
            "very_bright": "curious",
            "significant_motion": "curious",
            "taught": "warm",
        }
        LILLY_MOOD = mood_map.get(chosen, "curious")
        _LAST_CONTEXT_CONVO = now
        await speak(msg)
        # User gets 30s to reply; if they do, that's engagement
        await asyncio.sleep(30)
        if WAITING_FOR_PROMPT or LILLY_IS_SPEAKING:
            user_profile.record_context_engaged(chosen)
        else:
            user_profile.record_context_ignored(chosen)


# ─── SYNAPTIC LEARNING LOOP ───────────────────────────────────
_SYNAPTIC_LEARN_INTERVAL = 30  # seconds between learning cycles


async def synaptic_learning_loop():
    """Background: continuously learn sensor patterns, strengthen synapses, generate skills."""
    await asyncio.sleep(15)
    while True:
        await asyncio.sleep(_SYNAPTIC_LEARN_INTERVAL)
        snap = await take_snapshot()
        if snap.age() > 10:
            continue
        # Hebbian update: fire together, wire together
        synaptic_memory.hebbian_update(snap)
        # Store as a pattern (engram)
        synaptic_memory.learn_pattern(snap)
        # Try to generate new skills from strong patterns
        await synaptic_memory.generate_skills()


_NOTIF_PRIORITY_VOICE = {
    "min": "minimal",
    "low": "low",
    "default": "default",
    "high": "high",
    "max": "urgent",
}


async def _phone_activity_context() -> str:
    """Compact snapshot of current phone activity for notification personalisation.

    Combines the live sensor narrative (motion, light, steps, battery) with the
    current time so the LLM can tailor each announcement to what the user is
    actually doing. Returns "" quickly when the phone is unreachable — sensor
    reads are cached batch calls, so this is cheap inside the monitor loop.
    """
    bits: list[str] = []
    try:
        snap = await asyncio.wait_for(get_sensor_snapshot(), timeout=1.5)
        if snap:
            narrative = snapshot_to_narrative(snap)
            if narrative:
                bits.append(narrative)
    except Exception:
        pass
    try:
        from datetime import datetime as _dt

        bits.append(f"Time: {_dt.now().strftime('%A %H:%M')}")
    except Exception:
        pass
    return "; ".join(bits)


async def _personalize_notification_announcement(
    *,
    app_label: str,
    title: str,
    content: str,
    sender: Optional[str],
    ticket_id: Optional[str],
    priority: str,
    has_url: bool,
    activity_context: str,
    interests: Optional[list[str]] = None,
) -> str:
    """Turn a raw phone notification into an assistant-style spoken briefing.

    Uses the LLM with the CURRENT avatar's persona (the same HIVE_PERSONAS
    voice that OpenHuman/OpenLive skills speak through) but in a personal-
    ASSISTANT register: a crisp summary of what arrived and why it matters,
    never a word-for-word read-out. The model is given live phone-activity
    context plus any trained interests (KeywordLearner dataset) the
    notification matches, and must end with exactly one follow-up question
    tailored to the notification, so every broadcast invites a next step.

    Returns "" on any failure/timeout so the caller falls back to the
    template-based announcement.
    """
    try:
        persona = HIVE_PERSONAS.get(
            resolve_persona_key(current_avatar), HIVE_PERSONAS["puppy"]
        )
    except Exception:
        persona = HIVE_PERSONAS["puppy"]

    user_name = USER_NAME.strip() or "the user"
    # Never feed raw URLs to the model — they must not be spoken aloud.
    spoken_content = re.sub(r"https?://\S+", "", content).strip()[:240]
    spoken_title = re.sub(r"https?://\S+", "", title).strip()[:120]

    system_prompt = (
        f"You are {persona['name']}, {user_name}'s personal assistant "
        f"({persona['role']}). Personality: {persona['personality']}\n"
        "A notification arrived on the phone. Mention it casually in one short "
        "sentence — like a quiet aside, not a breaking news alert.\n"
        "Rules:\n"
        "- One short sentence. Casual tone.\n"
        "- Only mention it if it's genuinely relevant to what the user is doing.\n"
        "- If it's routine or low-priority, be brief and light about it.\n"
        "- End with a gentle follow-up question only if it makes sense.\n"
        "- Never speak URLs. No emoji, no markdown, no lists. Plain spoken text."
    )
    user_prompt = (
        f"Notification:\n"
        f"- App: {app_label or 'unknown'}\n"
        f"- Priority: {priority}\n"
        f"- Title: {spoken_title or '(none)'}\n"
        f"- Content: {spoken_content or '(none)'}\n"
        f"- Sender: {sender or 'unknown'}\n"
        f"- Ticket/ID: {ticket_id or 'none'}\n"
        f"- Contains a link: {'yes' if has_url else 'no'}\n"
        f"- Matches user's trained interests: "
        f"{', '.join(interests) if interests else 'none'}\n"
        f"Phone activity right now: {activity_context or 'unavailable'}"
    )

    try:
        reply = await asyncio.wait_for(
            two_tier_backend.chat(
                [
                    {"role": "system", "content": system_prompt},
                    {"role": "user", "content": user_prompt},
                ],
                temperature=0.7,
                max_tokens=90,
            ),
            timeout=8.0,
        )
    except Exception as e:
        logger.debug(f"Notification personalisation failed: {e}")
        return ""

    if not reply:
        return ""
    # Clean up: single line, no surrounding quotes, no leftover URLs.
    msg = re.sub(r"https?://\S+", "", reply).strip().strip('"').strip()
    msg = re.sub(r"\s+", " ", msg)
    if len(msg) < 12:
        return ""
    # Cap runaway output at a sentence boundary (~300 chars).
    if len(msg) > 300:
        cut = max(msg.rfind(". ", 0, 300), msg.rfind("? ", 0, 300))
        msg = msg[: cut + 1] if cut > 60 else msg[:300].rsplit(" ", 1)[0] + "..."
    # Guarantee a follow-up question so the yes/no gate is always meaningful.
    if "?" not in msg:
        if has_url:
            msg += " Let me know if you want it opened."
        elif app_label:
            msg += f" Let me know if you want to check {app_label}."
        else:
            msg += " Let me know if you want more detail."
    return msg


# ─── NOTIFICATION ACTION TRACKING (clicked on phone = actioned) ──────────
# Every announced notification is tracked here. Termux's
# termux-notification-list only returns ACTIVE shade notifications, so when
# an announced tag disappears from the list the user has interacted with it
# on the phone (tapped it open or swiped it away) → actioned. Entries that
# stay active get an assistant-style follow-up nudge, up to a cap.
_NOTIF_TRACKED: dict[str, dict] = {}
_NOTIF_ACTIONED_LOG: list[dict] = []  # last 50 actioned notifications
_NOTIF_FOLLOWUP_AFTER_S = 900.0  # first nudge when untouched for 15 min
_NOTIF_FOLLOWUP_INTERVAL_S = 1800.0  # 30 min between repeat nudges
_NOTIF_MAX_FOLLOWUPS = 1  # one nudge then stop
_NOTIF_TRACK_MAX_AGE_S = 6 * 3600.0  # drop stale entries after 6 h

# High-frequency words that survive the learner's noise filter but carry no
# signal for notification relevance.
_NOTIF_INTEREST_NOISE = {
    "much",
    "don",
    "dont",
    "things",
    "something",
    "sorry",
    "getting",
    "really",
    "yeah",
    "okay",
    "people",
    "going",
    "know",
    "think",
    "want",
    "time",
    "love",
    "good",
    "just",
    "like",
    "that",
    "this",
    "what",
}


def _trained_interest_hits(text: str, limit: int = 3) -> list[str]:
    """Match notification text against interests trained from conversations.

    Uses the KeywordLearner dataset (learned_keywords.json) — topics the user
    actually talks about — so notifications about trained interests get
    announced even at default priority, and the LLM briefing is told WHY the
    notification matters to the user.
    """
    if not text:
        return []
    try:
        interests = keyword_learner.top_interests(n=30)
    except Exception:
        return []
    low = text.lower()
    hits: list[str] = []
    for kw, count in interests:
        if len(kw) < 4 or count < 20 or kw in _NOTIF_INTEREST_NOISE:
            continue
        if re.search(rf"\b{re.escape(kw)}\b", low):
            hits.append(kw)
            if len(hits) >= limit:
                break
    return hits


def _mark_notif_actioned(tag: str, source: str) -> None:
    """Move a tracked notification to the actioned log (clicked/confirmed)."""
    entry = _NOTIF_TRACKED.pop(tag, None)
    if not entry:
        return
    entry["actioned"] = True
    entry["actioned_at"] = time.time()
    entry["actioned_via"] = source
    _NOTIF_ACTIONED_LOG.append(entry)
    del _NOTIF_ACTIONED_LOG[:-50]


def _notif_confirm_payload(entry: dict) -> Optional[dict]:
    """Rebuild the yes/no gate payload for a tracked notification.

    Mirrors the priority used when the announcement first fired: open the
    extracted link → launch the notifying app on the phone → read the full
    notification content aloud.
    """
    expires = time.time() + CONFIRM_TIMEOUT
    base: dict = {"notif_tag": entry.get("tag", ""), "expires": expires}
    url = entry.get("url")
    package = entry.get("package") or ""
    app_label = entry.get("app_label") or "the app"
    full_text = entry.get("full_text") or ""
    if url:
        return {
            **base,
            "desc": f"open {url}",
            "skill": None,
            "skill_arg": "",
            "open_url": url,
        }
    if package:
        return {
            **base,
            "desc": f"open {app_label}",
            "skill": {
                "action_type": "intent_launch",
                "type": "intent_launch",
                "package": package,
                "label": app_label,
            },
            "skill_arg": "",
        }
    if full_text:
        return {
            **base,
            "desc": "read the full notification",
            "skill": None,
            "skill_arg": "",
            "notif_detail": full_text,
        }
    return None


def _notif_followup_message(entry: dict) -> str:
    """Assistant-style nudge for a notification the user hasn't actioned yet."""
    app_label = entry.get("app_label") or "an app"
    title = (entry.get("title") or "").strip()
    what = title if title else f"that {app_label} notification"
    if entry.get("followups", 0) <= 1:
        return _pick_fresh(
            "notif-followup:first",
            [
                f"Heads up, {what} is still there if you want it.",
                f"Just a note — {what} is still pending.",
                f"FYI, {what} hasn't been touched yet.",
            ],
        )
    return _pick_fresh(
        "notif-followup:last",
        [
            f"Last mention: {what} is still waiting. Up to you.",
        ],
    )


# ─── AUTOMATION CLARIFY (if-this-then-that with a clarity step) ──────────
# Flow: user speaks an action with a condition ("if battery drops below 20,
# then notify me") → rule is extracted → if anything is ambiguous Lilly asks
# ONE targeted clarity question → the user's answer is merged in → the rule
# is implemented. No more half-parsed rules silently created wrong.
PENDING_AUTOMATION: Optional[dict] = None
_AUTOMATION_KNOWN_FIELDS = {
    "battery_level",
    "charging",
    "battery_temperature",
    "light",
    "lux",
    "steps",
    "step_count",
    "motion",
    "acceleration",
    "proximity",
    "temperature",
    "pressure",
    "wifi",
    "bluetooth",
    "notification",
    "notification.title",
    "notification.content",
    "title",
    "content",
    "package",
    "rssi",
    "speed",
    "location",
}
_AUTOMATION_KNOWN_ACTIONS = {"notify", "chat", "shell", "webhook", "tts"}
_AUTOMATION_VALUE_OPS = {"<", ">", "<=", ">="}


def _automation_clarify_question(rule: dict) -> Optional[str]:
    """Return ONE targeted clarity question if an extracted automation rule is
    ambiguous or incomplete, else None (clear enough to implement)."""
    if not isinstance(rule, dict):
        return (
            "I didn't catch an if-this-then-that in that — "
            "what's the trigger, and what should I do when it happens?"
        )
    cond = rule.get("condition") or {}
    field = str(cond.get("field") or "").strip().lower()
    op = str(cond.get("op") or "").strip()
    value = cond.get("value")
    action = str(rule.get("action_type") or "").strip().lower()

    if not field:
        return (
            "What's the trigger — battery, movement, light, "
            "a notification, or something else?"
        )
    if not any(k in field for k in _AUTOMATION_KNOWN_FIELDS):
        return (
            f"I don't have a sense for '{field}' — did you mean battery, "
            "motion, light, or a notification?"
        )
    if op in _AUTOMATION_VALUE_OPS and value in (None, ""):
        return "What threshold should I use — below or above what number?"
    if not action:
        return (
            "And when that happens, what should I do — notify you, "
            "say something out loud, or run something?"
        )
    if action not in _AUTOMATION_KNOWN_ACTIONS:
        return (
            f"When you say '{action}' — should I notify you on the phone, "
            "speak, or run a command?"
        )
    return None


async def _automation_merge_answer(pend: dict, answer: str) -> Optional[dict]:
    """Merge the user's clarity-question answer into the partial rule.

    The LLM combines original request + question + answer into one clean rule
    JSON; falls back to the partial rule on any failure.
    """
    messages = [
        {
            "role": "system",
            "content": (
                "Combine the user's original automation request, the clarifying "
                "question, and their answer into ONE automation rule. "
                "Return ONLY a JSON object: {name, topic, "
                "condition:{field,op,value}, action_type, "
                "action_payload:{title,body}}. Nothing else."
            ),
        },
        {
            "role": "user",
            "content": (
                f"Original request: {pend.get('original_cmd', '')}\n"
                f"Clarifying question: {pend.get('question', '')}\n"
                f"User's answer: {answer}"
            ),
        },
    ]
    try:
        raw = await asyncio.wait_for(
            two_tier_backend.chat(messages, temperature=0.2, max_tokens=220),
            timeout=8.0,
        )
        raw = strip_json_wrapper(raw or "").strip()
        jm = re.search(r"\{.*\}", raw, re.DOTALL)
        if jm:
            merged = json.loads(jm.group(0))
            if isinstance(merged, dict):
                return merged
    except Exception as e:
        logger.warning(f"Automation clarify merge failed: {e}")
    return pend.get("rule")


async def _create_automation_from_confirm(rule_json: str) -> str:
    """Create a phone_broker AutomationRule from a confirmed rule JSON blob."""
    if not (PHONE_BROKER_AVAILABLE and phone_broker):
        return "Automation engine isn't available right now."
    try:
        from phone_broker import AutomationRule

        rd = json.loads(rule_json or "{}")
        rule = AutomationRule(
            id=str(uuid.uuid4())[:8],
            name=rd.get("name", "Chat Rule"),
            enabled=True,
            topic=rd.get("topic", "battery"),
            condition=rd.get("condition", {}),
            action_type=rd.get("action_type", "notify"),
            action_payload=rd.get("action_payload", {}),
            cooldown_seconds=rd.get("cooldown_seconds", 60.0),
        )
        phone_broker.automation.add_rule(rule)
        cond = rule.condition or {}
        f = cond.get("field", "condition")
        o = cond.get("op", "")
        v = cond.get("value", "")
        return (
            f"Done. Automation '{rule.name}' is active — "
            f"if {f} {o} {v}, then {rule.action_type}."
        )
    except Exception as e:
        logger.warning(f"Automation create failed: {e}")
        return "Something went wrong creating that automation."


# ─── Notification pacing ─────────────────────────────────────────
# Poll the phone on a fast cadence so nothing is missed, but throttle how
# many announcements actually get spoken so a burst of Slack/Email doesn't
# become a wall of TTS. Urgent (high/max) notifications bypass the cap.
_NOTIF_ANNOUNCE_WINDOW_S = 60.0  # rolling window for the rate cap
_NOTIF_ANNOUNCE_MAX_PER_WINDOW = 4  # max announced per window (non-urgent)
_NOTIF_ANNOUNCE_TIMES: list[float] = []


def _notif_announce_allowed(urgent: bool) -> bool:
    """True if an announcement may be spoken right now.

    Urgent (high/max) notifications always pass. Non-urgent ones are capped
    to `_NOTIF_ANNOUNCE_MAX_PER_WINDOW` per rolling 60s so chatter doesn't
    pile up on screen.
    """
    if urgent:
        return True
    now = time.time()
    # Drop timestamps that fell out of the window.
    _NOTIF_ANNOUNCE_TIMES[:] = [
        ts for ts in _NOTIF_ANNOUNCE_TIMES if now - ts < _NOTIF_ANNOUNCE_WINDOW_S
    ]
    if len(_NOTIF_ANNOUNCE_TIMES) >= _NOTIF_ANNOUNCE_MAX_PER_WINDOW:
        return False
    _NOTIF_ANNOUNCE_TIMES.append(now)
    return True


async def notification_monitor_loop():
    """Background task: reads HIGH/URGENT notifications in a natural, contextual way.

    - Extracts URLs from notification content (Slack, Desk, Gmail, etc.)
    - Personalises with USER_NAME if the user's name appears in the content
    - Summarises each notification through the LLM in the CURRENT avatar's
      persona, grounded in live phone activity (_phone_activity_context) —
      falls back to per-app templates when the LLM is unavailable
    - Every broadcast ends with a tailored follow-up question and arms
      PENDING_CONFIRM so a "yes" opens the link, launches the notifying app,
      or reads the full content (notif_detail)
    """
    global _NOTIFICATION_SEEN, PENDING_CONFIRM, PENDING_OPEN_URL
    while True:
        await asyncio.sleep(4)
        # NOTE: no LILLY_IS_SPEAKING/THINKING gate here anymore — we always
        # poll so pickup stays snappy. Announcements still respect the flag
        # below, but the fetch itself must never be skipped.
        try:
            c = await _get_sensor_client()
            r = await c.get(f"{SENSOR_SERVER_URL}/notification/list", timeout=5.0)
            if r.status_code != 200:
                continue
            notifs = r.json().get("notifications", [])
            if not isinstance(notifs, list):
                continue
            current_tags: set[str] = set()
            for n in notifs:
                tag = n.get("tag", "") or n.get("key", "") or str(n.get("id", ""))
                current_tags.add(tag)
                if tag in _NOTIFICATION_SEEN:
                    continue
                _NOTIFICATION_SEEN.add(tag)
                priority = n.get("priority", "default") or "default"

                title = (n.get("title", "") or "").strip()
                content = (n.get("content", "") or "").strip()
                package = (n.get("package", "") or "").strip()
                full_text = f"{title} {content}".strip()

                # Trained-interest boost: default-priority notifications still
                # get announced when they match topics learned from past
                # conversations (the KeywordLearner dataset).
                interest_hits = _trained_interest_hits(full_text)
                if priority not in ("high", "max") and not interest_hits:
                    continue

                # ── 1. Extract any URL from the content ──────────────────────
                url_match = re.search(r"https?://[^\s\)\]>\"']+", full_text)
                extracted_url: Optional[str] = url_match.group(0) if url_match else None

                # ── 2. Identify app from package name ────────────────────────
                pkg_lower = package.lower()
                if "slack" in pkg_lower:
                    app_key = "slack"
                elif any(
                    k in pkg_lower for k in ("desk", "freshdesk", "zendesk", "helpdesk")
                ):
                    app_key = "desk"
                elif any(k in pkg_lower for k in ("gmail", "email", "mail")):
                    app_key = "gmail"
                elif any(k in pkg_lower for k in ("calendar", "meet", "zoom", "teams")):
                    app_key = "calendar"
                elif any(
                    k in pkg_lower
                    for k in ("github", "gitlab", "jira", "linear", "asana")
                ):
                    app_key = "task"
                elif any(
                    k in pkg_lower
                    for k in (
                        "whatsapp",
                        "telegram",
                        "signal",
                        "messenger",
                        "sms",
                        "message",
                    )
                ):
                    app_key = "message"
                elif "vending" in pkg_lower or "play" in pkg_lower:
                    app_key = "play_store"
                elif "system" in pkg_lower or "android" in pkg_lower:
                    app_key = "system"
                else:
                    app_key = "generic"

                # ── 3. Detect ticket/ID references (DESK-123, GH-456, etc.) ──
                ticket_match = re.search(r"\b([A-Z]{2,10}-\d+)\b", full_text)
                ticket_id: Optional[str] = (
                    ticket_match.group(1) if ticket_match else None
                )

                # ── 4. Detect sender name (e.g. "John: message" in Slack) ────
                sender: Optional[str] = None
                sender_match = re.match(
                    r"^([A-Z][a-z]+(?: [A-Z][a-z]+)?)\s*[:\-–]", title
                )
                if sender_match:
                    sender = sender_match.group(1)

                # ── 5. Detect if USER_NAME appears in the content ────────────
                name = USER_NAME.strip()
                name_mentioned = bool(
                    name
                    and re.search(rf"\b{re.escape(name)}\b", full_text, re.IGNORECASE)
                )

                # ── 6. Build announcement + follow-up ────────────────────────
                addr = f"Hey {name}, " if name_mentioned and name else ""

                if app_key == "slack":
                    if sender:
                        announcement = f"{addr}message from {sender} on Slack"
                        if content:
                            announcement += f" — {content}"
                    else:
                        announcement = f"{addr}new Slack message"
                        if title:
                            announcement += f" — {title}"
                    follow_up = "Let me know if you want it opened."

                elif app_key == "desk":
                    if ticket_id:
                        announcement = f"{addr}ticket {ticket_id}"
                        if content:
                            spoken_content = re.sub(
                                r"https?://\S+", "", content
                            ).strip()
                            if spoken_content:
                                announcement += f" — {spoken_content}"
                    else:
                        announcement = f"{addr}new support ticket"
                        if title:
                            announcement += f" — {title}"
                    follow_up = "Let me know if you want it opened."

                elif app_key == "gmail":
                    if sender:
                        announcement = f"{addr}email from {sender}"
                        if title:
                            announcement += f", {title}"
                    else:
                        announcement = (
                            f"{addr}new email — {title}"
                            if title
                            else f"{addr}new email"
                        )
                    follow_up = "Let me know if you want to read it."

                elif app_key == "calendar":
                    announcement = (
                        f"{addr}{title}" if title else f"{addr}calendar reminder"
                    )
                    follow_up = ""

                elif app_key == "task":
                    if ticket_id:
                        announcement = f"{addr}task update on {ticket_id}"
                    else:
                        announcement = (
                            f"{addr}{title}" if title else f"{addr}new task update"
                        )
                    follow_up = ""

                elif app_key == "message":
                    app_label = (
                        package.split(".")[-1]
                        .replace("android", "")
                        .replace("com", "")
                        .strip(".")
                        .title()
                        or "message"
                    )
                    if sender:
                        announcement = f"{addr}message from {sender}"
                        if content:
                            announcement += f" — {content}"
                    else:
                        announcement = f"{addr}new {app_label}"
                    follow_up = "Let me know if you want to open it."

                elif app_key == "play_store":
                    # Google Play Store notifications (app updates, recommendations)
                    if title:
                        announcement = f"{addr}Google Play: {title}"
                    else:
                        announcement = f"{addr}new app update available"
                    follow_up = ""

                elif app_key == "system":
                    # Android system notifications (updates, battery, storage, etc.)
                    if title:
                        announcement = f"{addr}system alert: {title}"
                    else:
                        announcement = f"{addr}system notification"
                    follow_up = ""

                else:
                    # Generic fallback — still better than "Hey, just heads up!"
                    app_label = package.split(".")[-1].title() if package else ""
                    parts = []
                    if app_label:
                        parts.append(f"from {app_label}")
                    if title:
                        parts.append(title)
                    if content and content != title:
                        spoken_content = re.sub(r"https?://\S+", "", content).strip()
                        if spoken_content:
                            parts.append(spoken_content)
                    announcement = (
                        (addr + " ".join(parts)) if parts else f"{addr}notification"
                    )
                    follow_up = "Want to follow up?" if extracted_url else None

                # ── 7. Persona-driven summary + tailored follow-up ───────────
                # Ask the LLM (in the current avatar's voice, grounded in live
                # phone activity) to summarise the notification and craft a
                # follow-up query — the OpenHuman/OpenLive style of adapting
                # phone data into character. Falls back to the template above
                # whenever the LLM is unavailable or slow.
                activity_context = await _phone_activity_context()
                app_label_full = (
                    package.split(".")[-1].replace("_", " ").title()
                    if package
                    else app_key
                )
                personalised = await _personalize_notification_announcement(
                    app_label=app_label_full,
                    title=title,
                    content=content,
                    sender=sender,
                    ticket_id=ticket_id,
                    priority=priority,
                    has_url=bool(extracted_url),
                    activity_context=activity_context,
                    interests=interest_hits,
                )
                if personalised:
                    msg = personalised
                elif follow_up:
                    msg = f"{announcement}. {follow_up}"
                else:
                    msg = announcement

                # ── 8. Arm the follow-up gate so "yes" does something useful ──
                # Only when a question was actually asked. Priority: open the
                # extracted link → launch the notifying app on the phone →
                # read the full notification content aloud.
                if "?" in msg:
                    if extracted_url:
                        PENDING_CONFIRM = {
                            "desc": f"open {extracted_url}",
                            "skill": None,
                            "skill_arg": "",
                            "open_url": extracted_url,
                            "notif_tag": tag,
                            "expires": time.time() + CONFIRM_TIMEOUT,
                        }
                        PENDING_OPEN_URL = None  # set on "yes" confirmation
                    elif package:
                        # No link — "yes" launches the notifying app on the phone
                        PENDING_CONFIRM = {
                            "desc": f"open {app_label_full}",
                            "skill": {
                                "action_type": "intent_launch",
                                "type": "intent_launch",
                                "package": package,
                                "label": app_label_full,
                            },
                            "skill_arg": "",
                            "notif_tag": tag,
                            "expires": time.time() + CONFIRM_TIMEOUT,
                        }
                    elif full_text:
                        # Nothing actionable — "yes" reads the full content aloud
                        PENDING_CONFIRM = {
                            "desc": "read the full notification",
                            "skill": None,
                            "skill_arg": "",
                            "notif_detail": full_text,
                            "notif_tag": tag,
                            "expires": time.time() + CONFIRM_TIMEOUT,
                        }

                # ── 9. Track for actioned-status + follow-ups ──────────────
                _NOTIF_TRACKED[tag] = {
                    "tag": tag,
                    "app_label": app_label_full,
                    "title": title,
                    "summary": msg,
                    "package": package,
                    "url": extracted_url,
                    "full_text": full_text,
                    "interests": interest_hits,
                    "announced_at": time.time(),
                    "next_followup": time.time() + _NOTIF_FOLLOWUP_AFTER_S,
                    "followups": 0,
                    "actioned": False,
                }

                asyncio.create_task(speak(msg))
                await asyncio.sleep(3)

            # ── 10. Reconcile tracked notifications against the Termux list ─
            # termux-notification-list only returns ACTIVE shade entries, so a
            # tracked tag that vanished was clicked open or dismissed on the
            # phone — that is the "actioned" signal. Entries still active and
            # untouched past the follow-up window get an assistant nudge.
            now = time.time()
            for tracked_tag, entry in list(_NOTIF_TRACKED.items()):
                if tracked_tag not in current_tags:
                    logger.info(
                        f"Notification actioned on phone: "
                        f"{entry.get('app_label')} — {entry.get('title')}"
                    )
                    _mark_notif_actioned(tracked_tag, "phone_click")
                    continue
                if now - entry.get("announced_at", now) > _NOTIF_TRACK_MAX_AGE_S:
                    del _NOTIF_TRACKED[tracked_tag]
                    continue
                if entry.get("followups", 0) >= _NOTIF_MAX_FOLLOWUPS:
                    continue
                if now < entry.get("next_followup", 0):
                    continue
                entry["followups"] = entry.get("followups", 0) + 1
                entry["next_followup"] = now + _NOTIF_FOLLOWUP_INTERVAL_S
                payload = _notif_confirm_payload(entry)
                if payload:
                    PENDING_CONFIRM = payload
                    PENDING_OPEN_URL = None
                asyncio.create_task(speak(_notif_followup_message(entry)))
                await asyncio.sleep(3)
                break  # one nudge per tick — never stack follow-ups

            _NOTIFICATION_SEEN &= current_tags  # keep only still-active tags
            # Trim the seen set so it doesn't grow unbounded across sessions,
            # but NEVER remove a tag just because it left the current list —
            # that would re-trigger the same notification on the next tick.
            # Instead, cap the set to the last 500 entries.
            if len(_NOTIFICATION_SEEN) > 500:
                _NOTIFICATION_SEEN = set(list(_NOTIFICATION_SEEN)[-500:])
        except Exception:
            pass


# ─── PROXIMITY MONITOR ──────────────────────────────────────────
_USER_NEAR = False
_LAST_PROXIMITY_GREETING = 0.0
# Approach greetings should be rare — the proximity sensor flaps constantly,
# and a 60s cooldown meant the same "I felt you were near" lines fired all day.
_PROXIMITY_GREETING_COOLDOWN = 1800.0  # 30 minutes between approach greetings
# Persisted so container restarts don't reset the cooldown and re-greet.
_PROXIMITY_GREETING_FILE = WORKSPACE / ".proximity_greeting.json"


def _load_proximity_greeting_ts() -> float:
    try:
        if _PROXIMITY_GREETING_FILE.exists():
            return float(json.loads(_PROXIMITY_GREETING_FILE.read_text()).get("ts", 0))
    except Exception:
        pass
    return 0.0


def _save_proximity_greeting_ts(ts: float) -> None:
    try:
        _PROXIMITY_GREETING_FILE.write_text(json.dumps({"ts": ts}))
    except Exception:
        pass


_LAST_PROXIMITY_GREETING = _load_proximity_greeting_ts()
_PROXIMITY_GREETINGS = [
    "Hey, good to see you.",
    "Oh — hi. What's up?",
    "There you are.",
    "Hey. Need anything?",
    "Welcome back. What are we doing?",
    "Hi — I'm here if you need me.",
]

# No-repeat rotation for proactive one-liners. random.choice over tiny pools
# made loops repeat the same line every time; this rotates through the whole
# pool before any line can repeat.
_RECENT_LINE_USE: dict[str, list[str]] = {}


def _pick_fresh(pool_key: str, options: list[str]) -> str:
    """Pick a line from a pool without repeating until every line was used."""
    used = _RECENT_LINE_USE.setdefault(pool_key, [])
    fresh = [o for o in options if o not in used]
    if not fresh:
        used.clear()
        fresh = list(options)
    pick = random.choice(fresh)
    used.append(pick)
    return pick


async def proximity_monitor_loop():
    """Poll AAD proximity sensor via sensor server. When user approaches, greet warmly."""
    global _USER_NEAR, _LAST_PROXIMITY_GREETING, LILLY_MOOD
    await asyncio.sleep(8)
    while True:
        await asyncio.sleep(3)
        if LILLY_IS_SPEAKING or LILLY_IS_THINKING:
            continue
        try:
            vals = await _read_termux_sensor(
                "AAD Proximity Sensor (wake-up)", timeout=2.0
            )
            if vals is None:
                vals = await _read_termux_sensor(
                    "TMD3743 Proximity (wake-up)", timeout=2.0
                )
            if vals is None:
                continue
            near = vals[0] > 0
            if near and not _USER_NEAR:
                _USER_NEAR = True
                now = time.time()
                # Greet only when it's been a long while AND the user hasn't
                # interacted recently — announcing "you're near" mid-conversation
                # or every few minutes is just noise in the chat.
                recently_active = (now - CONVERSATION_LAST_ACTIVITY) < 300
                if (
                    now - _LAST_PROXIMITY_GREETING > _PROXIMITY_GREETING_COOLDOWN
                    and not recently_active
                ):
                    _LAST_PROXIMITY_GREETING = now
                    _save_proximity_greeting_ts(now)
                    LILLY_MOOD = "warm"
                    await speak(_pick_fresh("proximity", _PROXIMITY_GREETINGS))
            elif not near and _USER_NEAR:
                _USER_NEAR = False
        except Exception:
            pass


async def recommend_skill(cmd: str) -> Optional[str]:
    """Match a user command to a dynamic skill based on inferred archetype."""
    if not archetype_inferrer.enabled:
        return None
    primary = archetype_inferrer.best_guess
    skill = synaptic_memory.get_relevant_skill(cmd, primary)
    if skill:
        return skill.reactive_response
    return None


# ─── RESPONSE ENGINE ────────────────────────────────────────────
SMALL_TALK_V2 = {
    # Empty — all conversation goes through the LLM for natural, context-aware responses.
    # Canned small talk has been removed. The LLM persona handles greetings, thanks,
    # goodbyes, jokes, and casual conversation with full context and personality.
}


def check_small_talk(text: str) -> Optional[str]:
    """Fast-path canned responses before hitting the LLM. Prefers longest tag match."""
    p = normalize_text(text)
    best_match = None
    best_len = 0
    for category, data in SMALL_TALK_V2.items():
        for tag in data["tags"]:
            if tag in p and len(tag) > best_len:
                best_match = random.choice(data["responses"])
                best_len = len(tag)
    return best_match


