# ── APPROVAL FEED: shared awareness across all 9 avatars ──────────────────────
# A small JSONL log in MEMORY_DIR that every avatar appends to. When a new
# entry appears (approval granted, comment, idea update), the next time any
# avatar starts a turn it reads the log and mentions relevant items, so all 9
# personalities stay in sync without needing a live bus.

# ─── Avatar Task Queue ──────────────────────────────────────────────────
# Each avatar has a task queue. Tasks can be assigned by the admin or by
# Lilly (the alpha). When an avatar is called via wake word, it sees its
# pending tasks and can share progress or ask questions.
#
# Flow:
#   1. Admin assigns task to avatar (e.g. "Fox, write a poem about AI")
#   2. Task goes into AVATAR_TASKS[avatar_key] queue
#   3. Avatar runs task in background (if coding agent) or waits for activation
#   4. When avatar is called ("Hey Fox"), it sees its tasks in context
#   5. Avatar can share progress, ask questions, or report completion

import uuid as _uuid
from dataclasses import dataclass, field as _field


@dataclass
class AvatarTask:
    id: str = ""
    avatar: str = ""
    description: str = ""
    status: str = "pending"  # pending | running | completed | failed | needs_input
    created_at: float = 0.0
    started_at: float = 0.0
    completed_at: float = 0.0
    result: str = ""
    assigned_by: str = "admin"  # admin | lilly | self
    session_id: str = ""  # agent session ID if running via coding agent
    progress: list = _field(default_factory=list)  # progress updates
    question: str = ""  # question the avatar wants to ask
    discussion: list = _field(default_factory=list)  # group-chat transcript

    def __post_init__(self):
        if not self.id:
            self.id = str(_uuid.uuid4())[:8]
        if not self.created_at:
            self.created_at = time.time()

    def to_dict(self) -> dict:
        return {
            "id": self.id,
            "avatar": self.avatar,
            "description": self.description,
            "status": self.status,
            "created_at": self.created_at,
            "started_at": self.started_at,
            "completed_at": self.completed_at,
            "result": self.result,
            "assigned_by": self.assigned_by,
            "session_id": self.session_id,
            "progress": self.progress[-5:],  # last 5 updates
            "question": self.question,
            "discussion": self.discussion[-12:],  # last 12 group-chat lines
        }


# Per-avatar task queues (keyed by avatar name: "fox", "cat", etc.)
# Initialized lazily after HIVE_PERSONAS is defined (see _ensure_avatar_tasks_loaded)
AVATAR_TASKS: dict[str, list[AvatarTask]] = {}
AVATAR_TASKS_FILE = MEMORY_DIR / "avatar_tasks.json"


def _load_avatar_tasks():
    """Load persisted avatar tasks from disk."""
    global AVATAR_TASKS
    if AVATAR_TASKS_FILE.exists():
        try:
            data = json.loads(AVATAR_TASKS_FILE.read_text())
            for avatar_key, tasks_list in data.items():
                AVATAR_TASKS[avatar_key] = [AvatarTask(**t) for t in tasks_list]
        except Exception:
            pass


def _save_avatar_tasks():
    """Persist avatar tasks to disk."""
    try:
        data = {k: [t.to_dict() for t in v] for k, v in AVATAR_TASKS.items()}
        AVATAR_TASKS_FILE.write_text(json.dumps(data, indent=2))
    except Exception:
        pass


# ─── Notification feed (toasts + hamburger panel) ──────────────────────
# Backed by a small JSON file in MEMORY_DIR so it survives container recreates.
# Types: task_complete, task_failed, group_discussion, approval_request, system.

NOTIFICATIONS_FILE = MEMORY_DIR / "notifications.json"


def _load_notifications() -> list[dict]:
    if NOTIFICATIONS_FILE.exists():
        try:
            items = json.loads(NOTIFICATIONS_FILE.read_text())
            if isinstance(items, list):
                return items
        except Exception:
            pass
    return []


def _save_notifications(items: list[dict]):
    try:
        NOTIFICATIONS_FILE.write_text(json.dumps(items, indent=2))
    except Exception:
        pass


# ── Sound-alert identifiers (persistent) ───────────────────────────────
# Which detected identifiers make Lilly beep in her vision feed. Stored so
# the user's choices survive reloads and match on class OR make/model.
DEFAULT_ALERT_OBJECTS = ["person", "dog", "cat"]
ALERTS_FILE = MEMORY_DIR / "alerts.json"


def _load_alert_config() -> dict:
    cfg = {
        "objects": list(DEFAULT_ALERT_OBJECTS),
        "sound_enabled": False,
        "boxes_enabled": True,
    }
    if ALERTS_FILE.exists():
        try:
            data = json.loads(ALERTS_FILE.read_text())
            if isinstance(data, dict):
                if isinstance(data.get("objects"), list):
                    cfg["objects"] = [str(o) for o in data["objects"] if str(o).strip()]
                for k in ("sound_enabled", "boxes_enabled"):
                    if k in data:
                        cfg[k] = bool(data[k])
        except Exception:
            pass
    return cfg


def _save_alert_config(cfg: dict):
    try:
        ALERTS_FILE.write_text(json.dumps(cfg, indent=2))
    except Exception:
        pass


def push_notification(
    n_type: str = "info",
    title: str = "",
    body: str = "",
    agent: str = "",
    task_id: str = "",
    context: Optional[dict] = None,
) -> dict:
    """Append a notification (toast on the web UI, list in the hamburger panel)."""
    items = _load_notifications()
    notif = {
        "id": str(_uuid.uuid4())[:8],
        "type": n_type,
        "title": title,
        "body": body,
        "agent": agent,
        "task_id": task_id,
        "status": "open",  # open | approved | denied | dismissed
        "created_at": time.time(),
        "context": context or {},
    }
    items.append(notif)
    items = items[-100:]
    _save_notifications(items)
    return notif


def _task_lookup(task_id: str) -> Optional[AvatarTask]:
    """Find a task by id across all avatar queues (safe when queues not loaded)."""
    for tasks in AVATAR_TASKS.values():
        for t in tasks:
            if t.id == task_id:
                return t
    return None


def _agent_display_name(avatar_key: str) -> str:
    try:
        return HIVE_PERSONAS.get(avatar_key, {}).get("name", avatar_key.title())
    except Exception:
        return avatar_key.title()


def assign_task(
    avatar: str, description: str, assigned_by: str = "admin"
) -> AvatarTask:
    """Assign a task to an avatar's queue."""
    task = AvatarTask(avatar=avatar, description=description, assigned_by=assigned_by)
    AVATAR_TASKS.setdefault(avatar, []).append(task)
    _save_avatar_tasks()
    return task


def get_avatar_tasks(avatar: str, status: str = "") -> list[AvatarTask]:
    """Get tasks for an avatar, optionally filtered by status."""
    tasks = AVATAR_TASKS.get(avatar, [])
    if status:
        tasks = [t for t in tasks if t.status == status]
    return tasks


def get_pending_tasks(avatar: str) -> list[AvatarTask]:
    """Get pending/running tasks for an avatar (shown when avatar is called)."""
    return get_avatar_tasks(avatar, status="")  # all tasks
    # Filter to pending + running + needs_input (actionable)


def update_task_status(
    task_id: str, status: str, result: str = "", progress: str = "", question: str = ""
) -> Optional[AvatarTask]:
    """Update a task's status across all avatar queues.

    Also pushes toast notifications: task_complete / task_failed toasts when a
    task finishes, and an approval_request notification when an avatar asks a
    question (so the admin can confirm or clarify from the hamburger menu).
    """
    for avatar_key, tasks in AVATAR_TASKS.items():
        for task in tasks:
            if task.id == task_id:
                prev_status = task.status
                task.status = status
                if result:
                    task.result = result
                if progress:
                    task.progress.append({"ts": time.time(), "text": progress})
                if question:
                    task.question = question
                    task.status = "needs_input"
                if status == "running" and not task.started_at:
                    task.started_at = time.time()
                if status in ("completed", "failed"):
                    task.completed_at = time.time()
                _save_avatar_tasks()

                # Toast notifications when the state transitions
                a_name = _agent_display_name(avatar_key)
                if task.status == "completed" and prev_status != "completed":
                    push_notification(
                        "task_complete",
                        title="✅ " + a_name + " finished a task",
                        body=(task.description[:140])
                        + (" — " + (task.result or "")[:180] if task.result else ""),
                        agent=avatar_key,
                        task_id=task.id,
                        context={"status": "completed"},
                    )
                elif task.status == "failed" and prev_status != "failed":
                    push_notification(
                        "task_failed",
                        title="❌ " + a_name + " hit a problem",
                        body=(task.description[:140])
                        + (" — " + (task.result or "")[:180] if task.result else ""),
                        agent=avatar_key,
                        task_id=task.id,
                        context={"status": "failed"},
                    )
                elif task.status == "needs_input" and prev_status != "needs_input":
                    push_notification(
                        "approval_request",
                        title="🧭 " + a_name + " needs direction",
                        body=(task.description[:140])
                        + (" — " + (task.question or "confirm or clarify")[:180]),
                        agent=avatar_key,
                        task_id=task.id,
                        context={"status": "needs_input", "question": task.question},
                    )
                return task
    return None


def get_all_active_tasks() -> list[dict]:
    """Get all pending/running tasks across all avatars (admin overview)."""
    active = []
    for avatar_key, tasks in AVATAR_TASKS.items():
        for task in tasks:
            if task.status in ("pending", "running", "needs_input"):
                active.append(task.to_dict())
    return active


def build_task_context_for_avatar(avatar: str) -> str:
    """Build a context string of the avatar's tasks for injection into LLM prompt.

    Called when an avatar is activated (via wake word or delegation).
    Shows pending/running tasks + recent completions.
    """
    tasks = AVATAR_TASKS.get(avatar, [])
    if not tasks:
        return ""

    lines = []
    # Pending tasks (need attention)
    pending = [t for t in tasks if t.status == "pending"]
    if pending:
        lines.append("YOUR PENDING TASKS:")
        for t in pending[:3]:
            lines.append(f"  [{t.id}] {t.description} (assigned by {t.assigned_by})")

    # Running tasks (in progress)
    running = [t for t in tasks if t.status == "running"]
    if running:
        lines.append("YOUR RUNNING TASKS:")
        for t in running[:3]:
            elapsed = int(time.time() - t.started_at) if t.started_at else 0
            lines.append(f"  [{t.id}] {t.description} — running for {elapsed}s")

    # Needs input (avatar has a question)
    needs_input = [t for t in tasks if t.status == "needs_input"]
    if needs_input:
        lines.append("TASKS NEEDING YOUR INPUT:")
        for t in needs_input:
            lines.append(f"  [{t.id}] {t.question}")

    # Recent completions (for awareness)
    completed = [t for t in tasks if t.status == "completed"]
    if completed:
        recent = completed[-2:]  # last 2
        lines.append("RECENTLY COMPLETED:")
        for t in recent:
            lines.append(f"  [{t.id}] {t.description} — {t.result[:80]}")

    return "\n".join(lines) if lines else ""


# ─── Team discussion + agent executor ──────────────────────────────────
# When the admin delegates a task, a small team of avatars "talks it over"
# (LLM generation in character). Their takes are stored on the task so the
# web UI can show + speak them in the group-chat style. If any avatar needs
# more detail, the task goes to needs_input and an approval_request lands in
# the notification feed for the admin to confirm or clarify.

_DISCUSS_TEAM = ["fox", "cat", "bear", "bunny", "owl", "raccoon", "deer"]


async def _run_agent_for_task(task: AvatarTask):
    """Execute a task via the coding agent (agent_core) in the background."""
    try:
        update_task_status(task.id, "running", progress="Coding agent started")
        from agent_core import execute_task

        agent_prompt = f"[Avatar Task for {task.avatar}] {task.description}\n\nYou are acting as the {task.avatar} avatar agent. Complete this task and report results."
        result = await execute_task(agent_prompt, user_email=ADMIN_EMAIL)
        update_task_status(task.id, "completed", result=(result or "")[:2000])
        logger.info(
            f"✅ Agent completed task {task.id} for {task.avatar}: {(result or '')[:100]}"
        )
    except Exception as e:
        update_task_status(task.id, "failed", result=str(e)[:500])
        logger.error(f"❌ Agent failed task {task.id}: {e}")


async def _discuss_task(task: AvatarTask) -> list[dict]:
    """Have a small team of avatars discuss the task. Returns transcript lines."""
    ordered = [task.avatar] if task.avatar in HIVE_PERSONAS else ["puppy"]
    ordered += [t for t in _DISCUSS_TEAM if t != task.avatar]
    ordered = ordered[:4]

    roster = "\n".join(
        f"  - {HIVE_PERSONAS[c]['emoji']} {HIVE_PERSONAS[c]['name']} ({HIVE_PERSONAS[c]['role']})"
        for c in ordered
    )

    async def one(char_key: str) -> dict:
        persona = HIVE_PERSONAS[char_key]
        system_prompt = (
            f"{persona['voice_prompt'].strip()}\n"
            f"You are part of a hive-mind team discussing a shared task together. "
            f"TEAM:\n{roster}\n"
            f"Give YOUR quick take on this task in 1-2 sentences, staying in character and speaking as yourself. "
            f"Build on or gently disagree with your teammates. "
            f"If you genuinely cannot proceed without more detail, end your reply with a short question. "
            f"NEVER say 'like and subscribe' or similar."
        )
        reply = strip_json_wrapper(
            await llama_backend.chat(
                [
                    {"role": "system", "content": system_prompt},
                    {"role": "user", "content": "Task: " + task.description},
                ],
                temperature=0.7,
                max_tokens=70,
                timeout=20,
            )
        )
        reply = (reply or "").strip()
        if not reply:
            reply = "I'm ready when you are."
        return {
            "char": char_key,
            "name": persona["name"],
            "emoji": persona["emoji"],
            "text": reply,
        }

    try:
        return await asyncio.gather(*[one(c) for c in ordered])
    except Exception as e:
        logger.error(f"group discussion error: {e}")
        return []


def _discussion_needs_input(transcript: list[dict]) -> Optional[dict]:
    """Return the first line that asks a clarifying question, if any."""
    for line in transcript:
        text = (line.get("text") or "").strip()
        if text.endswith("?"):
            return line
        lowered = text.lower()
        if any(
            kw in lowered
            for kw in (
                "clarif",
                "more detail",
                "more info",
                "what do you mean",
                "which one",
                "could you",
                "should we",
                "need to know",
            )
        ):
            return line
    return None


async def _discuss_assigned_task(task: AvatarTask):
    """Background: run the team discussion, then set task state + notifications."""
    try:
        transcript = await _discuss_task(task)
        task.discussion.extend(transcript)
        if transcript:
            task.progress.append(
                {
                    "ts": time.time(),
                    "text": "Team discussion: "
                    + ", ".join(
                        f"{line['name']}: {line['text']}" for line in transcript
                    ),
                }
            )
        blocker = _discussion_needs_input(transcript)
        if blocker and task.status == "pending":
            task.question = blocker["text"]
            task.status = "needs_input"
            _save_avatar_tasks()
            push_notification(
                "approval_request",
                title="🧭 " + blocker["name"] + " needs direction",
                body=(task.description[:140]) + " — " + blocker["text"][:160],
                agent=blocker["char"],
                task_id=task.id,
                context={
                    "status": "needs_input",
                    "question": blocker["text"],
                    "transcript": transcript,
                },
            )
        else:
            if task.status == "pending":
                task.status = "running"
            _save_avatar_tasks()
            agent_name = _agent_display_name(task.avatar)
            push_notification(
                "group_discussion",
                title="🗣️ The team discussed a task",
                body=(f"{agent_name}: " + (task.description[:120] or ""))
                + (
                    " — approve to run it, or reply with a correction."
                    if not task.question
                    else ""
                ),
                agent=task.avatar,
                task_id=task.id,
                context={"status": task.status, "transcript": transcript},
            )
    except Exception as e:
        logger.error(f"discuss_assigned_task {task.id}: {e}")
        update_task_status(task.id, "failed", result=f"Discussion error: {e}"[:500])


# Load tasks on startup (deferred — HIVE_PERSONAS not yet defined at import time)
_AVATAR_TASKS_LOADED = False


def _ensure_avatar_tasks_loaded():
    global _AVATAR_TASKS_LOADED
    if not _AVATAR_TASKS_LOADED:
        _AVATAR_TASKS_LOADED = True
        # Initialize task queues for all avatars now that HIVE_PERSONAS exists
        for k in HIVE_PERSONAS:
            AVATAR_TASKS.setdefault(k, [])
        _load_avatar_tasks()


# entry appears (approval granted, comment, idea update), the next time any

_APPROVAL_LOG = MEMORY_DIR / "approval_broadcast_log.jsonl"
_AVATAR_KNOWN_IDEAS: dict[
    str, set[str]
] = {}  # avatar -> set of idea ids it has acknowledged
_APPROVAL_LOG_CACHE: list[dict] = []  # cached parsed log (TTL-based)
_APPROVAL_LOG_CACHE_TS: float = 0.0  # last cache refresh timestamp
_APPROVAL_LOG_CACHE_TTL: float = 5.0  # refresh every 5 seconds max
_APPROVAL_LOG_MAX_ENTRIES: int = 500  # cap JSONL file to last 500 entries


def _read_approval_log() -> list[dict]:
    """Read the shared approval broadcast log (cached, one JSON object per line)."""
    global _APPROVAL_LOG_CACHE, _APPROVAL_LOG_CACHE_TS
    now = time.time()
    if _APPROVAL_LOG_CACHE and (now - _APPROVAL_LOG_CACHE_TS) < _APPROVAL_LOG_CACHE_TTL:
        return _APPROVAL_LOG_CACHE
    if not _APPROVAL_LOG.exists():
        return []
    try:
        lines = _APPROVAL_LOG.read_text().strip().split("\n")
        _APPROVAL_LOG_CACHE = [json.loads(line) for line in lines if line.strip()]
        _APPROVAL_LOG_CACHE_TS = now
        return _APPROVAL_LOG_CACHE
    except Exception:
        return []


def _append_approval_log(entry: dict) -> None:
    """Append a broadcast entry so all avatars can read it on their next turn."""
    global _APPROVAL_LOG_CACHE
    try:
        _APPROVAL_LOG.parent.mkdir(parents=True, exist_ok=True)
        with open(_APPROVAL_LOG, "a") as f:
            f.write(json.dumps(entry) + "\n")
        # Invalidate cache
        _APPROVAL_LOG_CACHE = []
        # Cap the JSONL file — keep last N entries to prevent unbounded growth
        if _APPROVAL_LOG.exists():
            try:
                lines = _APPROVAL_LOG.read_text().strip().split("\n")
                if len(lines) > _APPROVAL_LOG_MAX_ENTRIES:
                    lines = lines[-_APPROVAL_LOG_MAX_ENTRIES:]
                    _APPROVAL_LOG.write_text("\n".join(lines) + "\n")
            except Exception:
                pass
    except Exception as e:
        logger.warning(f"Failed to append approval log: {e}")


def _broadcast_to_avatars(cmd: str) -> None:
    """Write a shared-awareness entry that all 9 avatars will pick up.

    This lets the OpenLive approval feed and every avatar stay in sync
    without a live message bus — each avatar reads the log on its next turn.
    """
    # Determine the action type
    # Note: normalize_text() strips punctuation, so match both forms
    if "avatar update" in cmd:
        action = "update"
        detail = cmd.split("avatar update", 1)[-1].strip(": ").strip()
    elif "list pending automation approvals" in cmd:
        action = "list_request"
        detail = ""
    elif cmd.startswith("approve idea "):
        action = "approved"
        detail = cmd.replace("approve idea ", "").strip()
    elif cmd.startswith("comment on idea "):
        action = "commented"
        # Extract idea id and comment
        rest = cmd.replace("comment on idea ", "").strip()
        parts = rest.split(":", 1)
        detail = f"idea {parts[0].strip()}"
    else:
        action = "unknown"
        detail = cmd

    entry = {
        "ts": time.time(),
        "avatar": current_avatar,
        "action": action,
        "detail": detail,
        "raw": cmd,
    }
    _append_approval_log(entry)


def _handle_avatar_broadcast(cmd: str) -> str:
    """Generate a natural-language acknowledgement for an avatar broadcast."""
    if "list pending automation approvals" in cmd:
        items = _read_approval_log()
        pending = [
            e
            for e in items
            if e.get("action") in ("update", "approved", "commented")
            and e.get("detail")
        ]
        if not pending:
            return "No new automation updates to share — all avatars are in sync."
        latest = pending[-1]
        return f"📡 Updated all 9 avatars: {latest.get('detail', 'new automation update')} ({STATUS_LABEL.get(latest.get('action', 'update'), 'updated')})"

    if "avatar update" in cmd:
        detail = cmd.split("avatar update", 1)[-1].strip(": ").strip()
        return f"📡 Logged for all avatars: {detail}"

    return "📡 Noted — all avatars will see this."


def _handle_approval_action(cmd: str) -> str:
    """Handle an approve/comment action and acknowledge."""
    if cmd.startswith("approve idea "):
        idea_id = cmd.replace("approve idea ", "").strip()
        return f"✅ Idea {idea_id} approved — all avatars now know this is greenlit and will track its progress."
    if cmd.startswith("comment on idea "):
        rest = cmd.replace("comment on idea ", "").strip()
        parts = rest.split(":", 1)
        idea_id = parts[0].strip()
        return f"💬 Comment added to idea {idea_id} — all avatars can see your feedback on it."
    return "📡 Noted."


def _recent_unacknowledged_for_avatar(avatar: str) -> list[dict]:
    """Return approval log entries this avatar hasn't acknowledged yet."""
    known = _AVATAR_KNOWN_IDEAS.get(avatar, set())
    entries = _read_approval_log()
    new_entries = [
        e for e in entries if e.get("detail") and e.get("detail") not in known
    ]
    # Mark as seen
    for e in new_entries:
        known.add(e.get("detail", ""))
    _AVATAR_KNOWN_IDEAS[avatar] = known
    return new_entries


STATUS_LABEL = {
    "update": "updated",
    "approved": "approved",
    "commented": "commented",
    "list_request": "listed",
}


def _map_task_status(idea: dict, tasks: list) -> str:
    """Map an idea/task to a display status for the approval feed."""
    idea_id = idea.get("id", idea.get("key", ""))
    # Check if the idea maps to an autopilot task
    for t in tasks:
        if t.get("title", "") == idea.get("title", "") or t.get("id", "") == idea_id:
            status = t.get("status", "pending")
            if status in ("completed", "done"):
                return "completed"
            elif status == "in_progress":
                return "in_progress"
            elif status in ("pending", "todo"):
                return "pending"
    # Check the approval broadcast log for status updates
    for entry in _read_approval_log():
        if entry.get("detail", "").startswith(idea_id):
            action = entry.get("action", "")
            if action == "approved":
                return "approved"
            elif action == "commented":
                return "pending"
    return "pending"


async def _build_memory_hint(mem_dict: dict) -> str:
    """Pull the most useful facts from user_profile and recent memory for the LLM.
    Also recalls relevant L1 atoms from TencentDB memory (user preferences, facts).
    Includes cross-session catch-up context for continuity."""
    hints = []
    # Active hours → infer time-of-day habits
    try:
        prof_data = json.loads((WORKSPACE / "user_profile.json").read_text())
        active_hours = prof_data.get("active_hours", {})
        if active_hours:
            top_hour = max(active_hours, key=lambda h: active_hours[h])
            hints.append(f"User is most active around {top_hour}:00.")
        engagements = prof_data.get("context_engagement", {})
        if engagements:
            top_ctx = max(engagements, key=lambda c: engagements[c])
            hints.append(f"User has shown interest in context: {top_ctx}.")
    except Exception:
        pass
    # Memory summary
    summary = mem_dict.get("summary", "")
    if summary:
        hints.append(f"Conversation summary: {summary}")
    # Last 2 user messages as a quick "what were we just on"
    recent = [e for e in (mem_dict.get("entries") or []) if e.get("role") == "user"][
        -2:
    ]
    if recent:
        topics = "; ".join(e.get("text", "")[:60] for e in recent)
        hints.append(f"Recent topics: {topics}")

    # Cross-session catch-up context (NEW)
    try:
        catchup = await asyncio.wait_for(
            get_catchup_context(current_avatar, n_sessions=3), timeout=1.5
        )
        if catchup:
            hints.append(f"Past sessions: {catchup}")
    except Exception:
        pass  # Catch-up is optional, don't block

    # Daily memory context — recent days for continuity (per-user, privacy-safe)
    try:
        if _daily_recent_summaries:
            day_lines = [
                f"{s['date']}: {s['summary'][:120]}"
                for s in _daily_recent_summaries[:3]
            ]
            hints.append(f"Recent days context: {'; '.join(day_lines)}")
        if _daily_recent_entries:
            last_user_msgs = [
                e.get("text", "")[:60]
                for e in _daily_recent_entries
                if e.get("role") == "user"
            ]
            if last_user_msgs:
                hints.append(f"Yesterday's topics: {'; '.join(last_user_msgs)}")
    except Exception:
        pass  # Daily context is optional

    # Recent conversation history from permanent JSONL log
    try:
        recent_history = await asyncio.wait_for(
            _load_recent_conversation_history(n=10), timeout=0.5
        )
        if recent_history:
            # Extract last few user messages for context
            user_msgs = [
                h.get("user", "")[:80] for h in recent_history[-3:] if h.get("user")
            ]
            if user_msgs:
                hints.append(f"Recent conversation: {'; '.join(user_msgs)}")
            # Extract topics from history
            topics = await asyncio.wait_for(
                _get_conversation_topics(days=3), timeout=0.5
            )
            if topics:
                hints.append(f"Topics discussed recently: {', '.join(topics[:8])}")
    except Exception:
        pass  # History is optional

    # Brain 🧠 — Recall L1 atoms from TencentDB memory (async)
    mem = await _get_lilly_memory()
    if mem is not None:
        try:
            # Read L3 Core (persona profile) — contains user name, avatar preferences
            core = await mem.client.read_core()
            core_content = core.get("data", {}).get("content", "")
            if core_content:
                # Extract user name from core profile
                if "Name:" in core_content:
                    name_line = core_content.split("Name:")[1].split("\n")[0].strip()
                    hints.append(f"User name: {name_line}")
                hints.append(f"Core profile: {core_content[:300]}")

            # Search L1 atoms for user preferences and facts
            facts = await mem.search_facts(
                "user preference OR user fact OR avatar", limit=5
            )
            if facts:
                fact_parts = []
                for f in facts:
                    k = f.get("id") or f.get("key") or "unknown"
                    v = f.get("content") or f.get("value") or ""
                    fact_parts.append(f"{k}={str(v)[:80]}")
                fact_str = "; ".join(fact_parts)[:300]
                if fact_str:
                    hints.append(f"Memory facts: {fact_str}")
        except Exception:
            pass  # Memory not available, continue without it
    return " | ".join(hints) if hints else ""


async def handle_intent(
    text: str, from_text: bool = False, user_name: str = ""
) -> dict:
    global \
        PENDING_INTENT, \
        PENDING_CONFIRM, \
        GAME_STATE, \
        WAITING_FOR_PROMPT, \
        PENDING_DEEP_ANSWER, \
        WAKE_STATE, \
        LILLY_IS_THINKING, \
        LILLY_MOOD, \
        CURSOR_X, \
        CURSOR_Y, \
        CHILD_MODE, \
        PENDING_LOOK_AT
    global CONVERSATION_MODE, CONVERSATION_LAST_ACTIVITY
    global PENDING_OPEN_URL, _current_user_id
    global PENDING_AUTOMATION

    # Resolve the effective user name for this request
    effective_name = user_name or _get_user_name(_current_user_id)

    phrase = normalize_text(text)
    if not phrase or len(phrase) <= 2 or phrase in PHANTOMS:
        return {"action": "ignored", "text": ""}

    has_wake, wake_conf = fuzzy_wake_match(phrase, current_avatar)

    # In conversation mode, all speech is treated as user input (no wake word needed)
    in_conversation = CONVERSATION_MODE
    needs_wake = not (
        WAITING_FOR_PROMPT
        or PENDING_INTENT
        or GAME_STATE["active"]
        or WAKE_STATE["listening"]
        or in_conversation
    )

    if not from_text and needs_wake and not has_wake:
        return {"action": "ignored", "text": ""}

    # If wake word detected and not already in conversation, enter conversation mode
    if has_wake and not in_conversation:
        CONVERSATION_MODE = True
        CONVERSATION_LAST_ACTIVITY = time.time()

    # Update conversation activity timestamp
    CONVERSATION_LAST_ACTIVITY = time.time()

    # Strip wake word from command
    cmd = phrase
    for prefix in _get_wake_targets(current_avatar):
        if cmd.startswith(prefix):
            cmd = cmd[len(prefix) :].strip()
            break
    if not cmd:
        cmd = "hello"

    # ── WELCOME BACK: Check if this is the first message of a new session ──
    # If we have recent conversation history, inject a welcome-back context
    # so Lilly can reference what was discussed before.
    if not hasattr(handle_intent, "_session_started"):
        handle_intent._session_started = True
        try:
            recent_history = await asyncio.wait_for(
                _load_recent_conversation_history(n=5), timeout=0.5
            )
            if recent_history:
                # Extract last user message and topic
                last_user_msg = (
                    recent_history[-1].get("user", "") if recent_history else ""
                )
                last_topics = await asyncio.wait_for(
                    _get_conversation_topics(days=3), timeout=0.5
                )
                if last_topics:
                    # Add a subtle welcome-back hint to the system prompt
                    welcome_hint = f"Welcome back! You were recently discussing: {', '.join(last_topics[:5])}. "
                    if last_user_msg:
                        welcome_hint += (
                            f"Last thing the user said: '{last_user_msg[:100]}'. "
                        )
                    welcome_hint += "Reference this naturally if relevant — don't just say 'welcome back'."
                    # Store for injection into system prompt
                    handle_intent._welcome_hint = welcome_hint
                else:
                    handle_intent._welcome_hint = ""
            else:
                handle_intent._welcome_hint = ""
        except Exception:
            handle_intent._welcome_hint = ""

    # ── PENDING CONFIRMATION (casual mode gate) ──
    # Lilly just asked "Should I open YouTube...?" — resolve the user's
    # yes/no follow-up BEFORE processing any new intent. Ambient speech
    # that accidentally triggers an app intent still gets confirmed, so
    # false-positive phone actions are impossible.
    if PENDING_CONFIRM is not None:
        if time.time() > PENDING_CONFIRM.get("expires", 0):
            PENDING_CONFIRM = None
        else:
            conf = _confirm_response(cmd)
            if conf == "yes":
                pending = PENDING_CONFIRM
                PENDING_CONFIRM = None
                # A confirmed notification follow-up counts as actioned.
                if isinstance(pending, dict) and pending.get("notif_tag"):
                    _mark_notif_actioned(pending["notif_tag"], "voice_confirm")
                pending_skill = (
                    pending.get("skill") if isinstance(pending, dict) else None
                )
                # Notification follow-up: open a URL on the phone
                pending_url = (
                    pending.get("open_url") if isinstance(pending, dict) else None
                )
                if pending_url:
                    PENDING_OPEN_URL = pending_url
                    reply = "Opening it now."
                    await memory.add("user", text)
                    await memory.add("assistant", reply)
                    await save_memory()
                    await speak(reply)
                    return {"action": "handled", "text": reply, "open_url": pending_url}
                # Notification follow-up: read the full content aloud
                pending_detail = (
                    pending.get("notif_detail") if isinstance(pending, dict) else None
                )
                if pending_detail:
                    reply = f"Here's the full thing: {pending_detail}"
                    await memory.add("user", text)
                    await memory.add("assistant", reply)
                    await save_memory()
                    await speak(reply)
                    return {"action": "handled", "text": reply}
                # Ops bridge follow-up: confirmed server/phone shell commands
                pending_ops = pending.get("ops") if isinstance(pending, dict) else None
                if pending_ops:
                    reply = await _execute_ops_action(pending_ops)
                    await memory.add("user", text)
                    await memory.add("assistant", reply)
                    await save_memory()
                    await speak(reply)
                    return {"action": "handled", "text": reply}
                # Automation confirm: create the rule instead of a skill run
                if pending_skill == "_auto_create":
                    reply = await _create_automation_from_confirm(
                        pending.get("skill_arg", "")
                    )
                    await memory.add("user", text)
                    await memory.add("assistant", reply)
                    await save_memory()
                    await speak(reply)
                    return {"action": "handled", "text": reply}
                if not pending_skill:
                    reply = "OK, ready when you are."
                else:
                    reply = await _run_skill_action(
                        pending_skill, pending.get("skill_arg", "")
                    )
                if not reply:
                    reply = f"On it — {pending.get('desc', 'doing that now')}."
                await memory.add("user", text)
                await memory.add("assistant", reply)
                await save_memory()
                await speak(reply)
                return {"action": "handled", "text": reply}
            if conf == "no":
                pending_no = PENDING_CONFIRM
                PENDING_CONFIRM = None
                # Explicitly declining a notification follow-up = handled.
                if isinstance(pending_no, dict) and pending_no.get("notif_tag"):
                    _mark_notif_actioned(pending_no["notif_tag"], "voice_declined")
                reply = "OK, no problem — I'll leave it."
                await memory.add("user", text)
                await memory.add("assistant", reply)
                await save_memory()
                await speak(reply)
                return {"action": "handled", "text": reply}
            # A different utterance: treat it as a fresh intent, drop the
            # stale pending action (it expires anyway after CONFIRM_TIMEOUT).
            PENDING_CONFIRM = None

    # ── AUTOMATION CLARIFY: the user answered Lilly's clarity question ──
    # Their reply merges into the partial rule, then progresses to the final
    # create-it confirmation (one more question only if still ambiguous).
    if PENDING_AUTOMATION is not None:
        if time.time() > PENDING_AUTOMATION.get("expires", 0):
            PENDING_AUTOMATION = None
        else:
            pend = PENDING_AUTOMATION
            PENDING_AUTOMATION = None
            merged = await _automation_merge_answer(pend, cmd)
            follow_up_q = _automation_clarify_question(merged) if merged else None
            if follow_up_q and pend.get("clarifications", 0) < 1:
                PENDING_AUTOMATION = {
                    "rule": merged or pend.get("rule"),
                    "original_cmd": pend.get("original_cmd", ""),
                    "question": follow_up_q,
                    "clarifications": pend.get("clarifications", 0) + 1,
                    "expires": time.time() + 300,
                }
                reply = follow_up_q
            elif merged:
                _rc = merged.get("condition", {}) or {}
                _f = _rc.get("field", "condition")
                _o = _rc.get("op", "")
                _v = str(_rc.get("value", ""))
                PENDING_CONFIRM = {
                    "desc": "create automation " + merged.get("name", "New Rule"),
                    "skill": "_auto_create",
                    "skill_arg": json.dumps(merged),
                    "expires": time.time() + 120,
                }
                reply = (
                    f"Got it — so: '{merged.get('name', 'New Rule')}' "
                    f"— if {_f} {_o} {_v}, then "
                    f"{merged.get('action_type', 'notify')}. Create it?"
                )
            else:
                reply = (
                    "I still couldn't shape that into a rule. "
                    "Try: 'if battery drops below 20, then notify me'."
                )
            await memory.add("user", text)
            await memory.add("assistant", reply)
            await save_memory()
            await speak(reply)
            return {"action": "handled", "text": reply}

    # ── APPROVAL BROADCAST: commands from the OpenLive approval feed
    # are relayed to ALL 9 avatars so they become aware of automations,
    # approvals, comments, and progress updates in shared memory.
    # Triggers: "avatar update: ...", "approve idea <id>", "comment on idea <id>: <text>"
    # Note: normalize_text() strips punctuation, so "avatar update:" → "avatar update"
    # Note: "list pending automation approvals" is handled separately below — it
    # returns structured JSON for the UI, not a broadcast.
    if "avatar update" in cmd:
        # Broadcast to all avatars via shared memory file
        _broadcast_to_avatars(cmd)
        # Let the current avatar also acknowledge
        reply = _handle_avatar_broadcast(cmd)
        await memory.add("user", cmd)
        await memory.add("assistant", reply)
        await save_memory()
        await speak(reply)
        return {"action": "handled", "text": reply}

    if cmd.startswith("approve idea ") or cmd.startswith("comment on idea "):
        _broadcast_to_avatars(cmd)
        reply = _handle_approval_action(cmd)
        await memory.add("user", cmd)
        await memory.add("assistant", reply)
        await save_memory()
        await speak(reply)
        return {"action": "handled", "text": reply}

    # ── TTS Troubleshooting — detect common TTS failure reports and respond with
    #   specific diagnostic steps instead of a generic fallback. Triggered by
    #   phrases like "TTS not working", "no audio", "can't hear", etc.
    #   This runs early (before skill/LLM lookup) so users get immediate help.
    tts_trouble_patterns = [
        "tts not working",
        "tts is not working",
        "no audio",
        "no sound",
        "cant hear",
        "not speaking",
        "not saying",
        "voice not working",
        "no voice",
        "audio is broken",
        "broken audio",
        "piper not working",
    ]
    if trig_in(cmd, *tts_trouble_patterns):
        # Run a quick diagnostic
        diagnostics = []
        piper_ok = os.path.exists(PIPER_BIN)
        voice_ok = os.path.exists(PIPER_VOICE)
        espeak_ok = os.path.exists(
            os.environ.get("ESPEAK_DATA_PATH", "/usr/local/share/espeak-ng-data")
        )

        diagnostics.append(
            f"Piper binary: {'OK' if piper_ok else 'MISSING'} ({PIPER_BIN})"
        )
        diagnostics.append(
            f"Voice model: {'OK' if voice_ok else 'MISSING'} ({PIPER_VOICE})"
        )
        diagnostics.append(f"eSpeak data: {'OK' if espeak_ok else 'MISSING'}")
        diagnostics.append(
            f"Audio cache entries: {len(AUDIO_CACHE) if AUDIO_CACHE else 0}"
        )

        # Quick test synthesis
        try:
            import subprocess

            _diag_voice = CHAR_VOICE.get(current_avatar, CHAR_VOICE["puppy"])
            _diag_onnx = _diag_voice.get("onnx", "")
            if _diag_onnx:
                _diag_voice_path = str(
                    Path(__file__).parent / "lillyos" / "voices" / _diag_onnx
                )
            else:
                _diag_voice_path = PIPER_VOICE

            proc = subprocess.Popen(
                [
                    PIPER_BIN,
                    "--model",
                    _diag_voice_path,
                    "--output-raw",
                    "--noise-scale",
                    f"{_diag_voice['noise_scale']:.3f}",
                    "--noise-w",
                    f"{_diag_voice['noise_w']:.3f}",
                    "--length-scale",
                    f"{_diag_voice['length_scale']:.2f}",
                ],
                stdin=subprocess.PIPE,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
            )
            raw, stderr = proc.communicate(input="test\n".encode(), timeout=5)
            if proc.returncode == 0 and raw and len(raw) > 1000:
                diagnostics.append("Synthesis test: PASS")
            else:
                diagnostics.append(f"Synthesis test: FAIL (rc={proc.returncode})")
        except Exception as e:
            diagnostics.append(f"Synthesis test: ERROR ({e})")

        # Build a helpful, avatar-appropriate response
        from datetime import datetime as _dt

        _now = _dt.now().strftime("%H:%M")
        diag_str = " | ".join(diagnostics)
        reply = f"Let me check that for you, {_now}. TTS diagnostics: {diag_str}"

        # If Piper or voice is missing, give targeted fix
        if not (piper_ok and voice_ok):
            fixes = []
            if not piper_ok:
                fixes.append("install Piper: pip install piper-tts")
            if not voice_ok:
                fixes.append(f"copy voice model to {PIPER_VOICE}")
            reply += f" To fix: {'; '.join(fixes)}"
        else:
            reply += (
                " If audio still isn't playing, check your device volume "
                "and make sure the browser tab has sound permissions."
            )

        await memory.add("user", cmd)
        await memory.add("assistant", reply)
        await save_memory()
        await speak(reply)
        return {"action": "handled", "text": reply}

    # ── SUPPORT AUTOMATOR: trigger proactive diagnostics from conversation
    #   User can say: "run diagnostics", "check system", "system status",
    #   "check for issues", or ask Lilly to "report problems"
    support_triggers = [
        "run diagnostics",
        "check system",
        "system status",
        "system check",
        "check for issues",
        "report problems",
        "run support check",
        "check lilly",
        "is everything working",
        "any problems",
        "how is everything",
        "check health",
        "health check",
        "automated check",
        "run automator",
    ]
    if any(s in cmd for s in support_triggers):
        # Inline diagnostics (fast checks, no LLM test for speed)
        piper_ok = os.path.exists(PIPER_BIN)
        voice_ok = os.path.exists(PIPER_VOICE)
        llm_ok = False
        try:
            async with httpx.AsyncClient(timeout=3.0) as _oc:
                _r = await _oc.get(f"{OLLAMA_URL}/api/tags")
                llm_ok = _r.status_code == 200
        except Exception:
            pass

        sensor_ok = False
        try:
            async with httpx.AsyncClient(timeout=3.0) as _client:
                _r = await _client.get(f"{SENSOR_SERVER_URL}/sensors/all")
                sensor_ok = _r.status_code == 200
        except Exception:
            pass

        checks = [
            f"Piper TTS: {'OK' if piper_ok and voice_ok else 'ISSUE'}",
            f"LLM backend: {'OK' if llm_ok else 'ISSUE'}",
            f"Sensor server: {'OK' if sensor_ok else 'ISSUE'}",
            f"Audio cache: {len(AUDIO_CACHE) if AUDIO_CACHE else 0} entries",
        ]

        all_ok = piper_ok and voice_ok and llm_ok and sensor_ok
        reply = (
            "System check complete. Everything looks good: " + "; ".join(checks) + "."
            if all_ok
            else "System check complete. Here's what I found: "
            + "; ".join(checks)
            + "."
            f" {'I can help fix these — want me to try?' if not all_ok else ''}"
        )

        await memory.add("user", cmd)
        await memory.add("assistant", reply)
        await save_memory()
        await speak(reply)
        return {"action": "handled", "text": reply}

    # ── AUTOPILOT INTEGRATION: discuss self-improvement ideas ──────────────
    # User can ask: "what should I improve", "any improvement ideas",
    # "what does my autopilot say", "show me my ideas", "what's my health"
    improvement_triggers = [
        "improvement ideas",
        "what should i improve",
        "what to improve",
        "improve lilly",
        "improve yourself",
        "new ideas",
        "feature ideas",
        "autopilot",
        "what does my autopilot",
        "show me my ideas",
        "what ideas",
        "self improvement",
        "build suggestions",
        "what should i build",
        "health score",
        "system health",
        "how healthy",
        "product health",
        "list pending automation approvals",
    ]
    if trig_in(cmd, *improvement_triggers):
        # Fetch ideas and health from autopilot
        autopilot_ideas = []
        autopilot_health = None
        autopilot_tasks = []
        autopilot_mod = None

        try:
            import importlib

            autopilot_mod = importlib.import_module("lilly_autopilot_client")

            autopilot_ideas = await autopilot_mod.get_lilly_improvement_ideas()
            autopilot_health = await autopilot_mod.get_lilly_health()

            if autopilot_mod.LillyAutopilotClient:
                _client = await autopilot_mod.LillyAutopilotClient()
                autopilot_tasks = await _client.list_tasks()
                await _client.close()

        except Exception as e:
            logger.debug(f"Autopilot fetch error: {e}")

        # ── If this is from OpenLive's approval feed, return structured JSON
        # so the UI can render a full approval feed with complexity, effort,
        # comments, and progress tracking.
        if "list pending automation approvals" in cmd:
            _approvals = []
            for idea in autopilot_ideas:
                _approvals.append(
                    {
                        "id": idea.get("id", idea.get("key", str(len(_approvals)))),
                        "title": idea.get("title", idea.get("name", "Untitled")),
                        "description": idea.get("description", ""),
                        "category": idea.get("category", "improvement"),
                        "impact_score": idea.get("impact_score", idea.get("score", 5)),
                        "feasibility_score": idea.get("feasibility_score", 5),
                        "complexity": idea.get("complexity", "M"),
                        "estimated_effort_hours": idea.get(
                            "estimated_effort_hours", idea.get("effort_hours", 5)
                        ),
                        "status": _map_task_status(idea, autopilot_tasks),
                        "technical_approach": idea.get("approach", ""),
                        "risks": idea.get("risks", []),
                        "tags": idea.get("tags", []),
                        "comments": [],
                        "created_at": idea.get("created_at", idea.get("timestamp", "")),
                    }
                )
            return {"action": "handled", "text": json.dumps({"approvals": _approvals})}

        parts = []

        # Health score
        if autopilot_health and isinstance(autopilot_health, dict):
            _score = autopilot_health.get(
                "ec8e611b-6f2a-4f9c-90f6-f7e3505bc180", autopilot_health.get("score", 0)
            )
            parts.append(f"My system health score is {_score}%")

        # Ideas
        if autopilot_ideas and autopilot_mod is not None:
            _idea_text = autopilot_mod.format_ideas_for_lilly(autopilot_ideas)
            parts.append(_idea_text)
        else:
            parts.append(
                "My research system doesn't have new ideas right now — want me to generate some?"
            )

        # Tasks
        if autopilot_tasks:
            _task_names = [
                t.get("title", "") for t in autopilot_tasks if t.get("title")
            ]
            _in_progress = [
                t for t in autopilot_tasks if t.get("status") == "in_progress"
            ]
            _todo = [
                t for t in autopilot_tasks if t.get("status") in ("todo", "pending")
            ]
            if _in_progress:
                parts.append(
                    f"I'm currently working on: {', '.join(t['title'] for t in _in_progress)}"
                )
            if _todo:
                parts.append(f"Next up: {', '.join(t['title'] for t in _todo[:2])}")

        reply = "; ".join(p for p in parts if p)

        await memory.add("user", cmd)
        await memory.add("assistant", reply)
        await save_memory()
        await speak(reply)
        return {"action": "handled", "text": reply}

    # ── KID MODE TOGGLE via text command ──
    kid_on = any(
        w in cmd
        for w in [
            "kid mode on",
            "kid mode",
            "child mode on",
            "child mode",
            "socratic mode",
            "learning mode",
            "teach me",
        ]
    )
    kid_off = any(
        w in cmd
        for w in [
            "kid mode off",
            "exit kid mode",
            "exit child mode",
            "normal mode",
            "adult mode",
            "stop kid mode",
            "stop child mode",
        ]
    )
    if kid_off and CHILD_MODE:
        CHILD_MODE = False
        await speak("Back to normal mode!")
        return {"action": "handled", "text": "Kid mode deactivated."}
    if kid_on and not CHILD_MODE:
        CHILD_MODE = True
        await speak("Kid mode on! Let's explore and learn together!")
        return {"action": "handled", "text": "Kid mode activated — Socratic learning."}

    archetype_inferrer.record_conversation(text)
    user_profile.record_interaction()
    keyword_learner.record_conversation(text)

    # ── 0a. REMINDERS / SCHEDULED TASKS ──
    # Skip this handler if the command is a sensor-condition-based automation
    # (e.g. "remind me when battery drops below 20%") — those are handled later
    # by the automation-from-chat handler.
    _remind_condition_words = [
        "battery",
        "charging",
        "sensor",
        "light",
        "notification",
        "bluetooth",
        "wifi",
        "step",
        "motion",
        "temperature",
        "pressure",
        "haven't moved",
        "i'm not moving",
        "plugged",
        "unplugged",
        "drops below",
        "goes above",
        "reaches",
        "above",
        "below",
    ]
    _is_time_reminder = not any(w in cmd for w in _remind_condition_words)
    remind_match = (
        re.search(
            r"(?:remind\s+me|set\s+(?:a\s+)?reminder|schedule|set\s+(?:a\s+)?(?:task|alarm|timer))\s+(?:to\s+)?(.+)",
            cmd,
            re.IGNORECASE,
        )
        if _is_time_reminder
        else None
    )
    if remind_match:
        raw = remind_match.group(1).strip()
        trigger_time = parse_relative_time(raw)
        if trigger_time:
            # Strip the time portion to get the task text
            task_text = _re.sub(
                r"\b(?:in\s+\d+\s*(?:min(?:ute)?s?|hr|hour|h|sec(?:ond)?s?|s)|at\s+\d{1,2}:\d{2}\s*(?:am|pm)?|tomorrow(?:\s+at\s+\d{1,2}:\d{2}\s*(?:am|pm)?)?|half\s+an?\s+hour|an?\s+hour)\b",
                "",
                raw,
                flags=_re.IGNORECASE,
            ).strip()
            if not task_text:
                task_text = "something you wanted me to remind you about"
            task = task_scheduler.add(task_text, trigger_time)
            eta = trigger_time - time.time()
            if eta < 3600:
                mins = int(eta / 60)
                reply = f"Got it! I'll remind you to {task_text} in {mins} minute{'s' if mins != 1 else ''}."
            elif eta < 86400:
                hours = int(eta / 3600)
                reply = f"Got it! I'll remind you to {task_text} in {hours} hour{'s' if hours != 1 else ''}."
            else:
                import datetime as _dt

                target = _dt.datetime.fromtimestamp(trigger_time)
                reply = f"Got it! I'll remind you to {task_text} on {target.strftime('%A at %I:%M %p')}."
            await speak(reply)
            return {"action": "handled", "text": reply}
        else:
            reply = (
                "When should I remind you? Try 'in 30 minutes' or 'tomorrow at 9am'."
            )
            await speak(reply)
            return {"action": "handled", "text": reply}

    # "what are my reminders" / "upcoming tasks"
    if any(
        w in cmd
        for w in [
            "my reminders",
            "upcoming tasks",
            "what reminders",
            "my tasks",
            "show reminders",
        ]
    ):
        upcoming = task_scheduler.upcoming()
        if upcoming:
            lines = []
            for t in upcoming[:5]:
                eta = t["eta_seconds"]
                if eta < 3600:
                    when = f"in {int(eta / 60)} min"
                elif eta < 86400:
                    when = f"in {int(eta / 3600)}h"
                else:
                    when = f"in {int(eta / 86400)}d"
                lines.append(f"{t['text']} ({when})")
            reply = f"You have {len(upcoming)} upcoming: " + "; ".join(lines) + "."
        else:
            reply = "No upcoming reminders."
        await speak(reply)
        return {"action": "handled", "text": reply}

    # "cancel reminder X"
    cancel_match = re.search(
        r"(?:cancel|remove|delete)\s+(?:reminder|task|alarm)\s+(.+)", cmd, re.IGNORECASE
    )
    if cancel_match:
        query = cancel_match.group(1).strip()
        found = None
        for t in task_scheduler.tasks:
            if not t.fired and query in t.text.lower():
                found = t
                break
        if found:
            task_scheduler.remove(found.id)
            reply = f"Cancelled: {found.text}."
        else:
            reply = "I couldn't find that reminder."
        await speak(reply)
        return {"action": "handled", "text": reply}

    # ── 0. TEACHING PHRASES: learn contexts & place names ──
    teaching_match = re.match(
        r"(?:we(?:'re| are) (?:in|at|on) the |this (?:is|place is|place is called) |it'?s (?:called|the) |call this |this area is )(.+)",
        cmd,
    )
    if teaching_match:
        label = teaching_match.group(1).strip()
        snap = await take_snapshot()
        await learn_context(label, snap)
        await speak(f"Got it! I'll remember this as {label}.")
        # Also try to learn as a place name
        asyncio.create_task(learn_place_name(label))
        return {"action": "handled", "text": f"I'll remember this as {label}."}

    # Geo query: "where are we" / "what's this place" / "have i been here"
    geo_query = any(
        w in cmd
        for w in [
            "where are we",
            "what's this place",
            "where is this",
            "have i been here",
            "what's around",
            "whats around",
            "name this place",
            "what's nearby",
        ]
    )
    if geo_query:
        loc = await current_location()
        if loc:
            lat, lon, name, addr, *_ = loc
            _last_location_name = name
            places = load_places()
            key = place_key(lat, lon)
            if key in places and places[key].get("user_label"):
                reply = f"We're at {places[key]['name']}."
            elif key in places and places[key].get("address"):
                a = places[key]["address"]
                parts = []
                for k in ["road", "neighbourhood", "suburb", "village", "town", "city"]:
                    if a.get(k):
                        parts.append(a[k])
                reply = f"We're at {', '.join(parts) or name}."
            else:
                parts = []
                for k in ["road", "neighbourhood", "suburb", "village", "town", "city"]:
                    if addr.get(k):
                        parts.append(addr[k])
                reply = f"I think this is {', '.join(parts) or name}."
            await speak(reply)
            return {"action": "handled", "text": reply}
        else:
            await speak("I can't get a location fix right now.")
            return {"action": "handled", "text": "No location fix."}

    # ── 1. PENDING INTENT ROUTING ──
    if PENDING_INTENT:
        intent_action_type = PENDING_INTENT.get("action_type", "")
        pkg = PENDING_INTENT.get("package", "")
        intent_action = PENDING_INTENT.get("intent_action", "")
        uri_template = PENDING_INTENT.get("uri_template", "")
        if intent_action_type == "shell_command":
            cmd_to_run = PENDING_INTENT.get("command", "")
            subcmd = PENDING_INTENT.get("subcommand", "")
            args = PENDING_INTENT.get("args", [])
            full_cmd = (
                [cmd_to_run] + ([subcmd] if subcmd else []) + (args or []) + [cmd]
            )
            try:
                proc = await asyncio.create_subprocess_exec(
                    *full_cmd,
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.PIPE,
                )
                stdout, stderr = await asyncio.wait_for(
                    proc.communicate(), timeout=30.0
                )
                output = stdout.decode().strip() or stderr.decode().strip()
                reply = f"Done: {output[:200]}" if output else "Command executed."
            except asyncio.TimeoutError:
                reply = "Command timed out."
            except FileNotFoundError:
                reply = f"Command '{cmd_to_run}' not found."
        elif intent_action_type in (
            "intent_launch",
            "prompt_argument",
            "hybrid_intent_tap",
        ):
            await app_process_monkey_intent(pkg, intent_action, uri_template, cmd)
            reply = "On it!"
        else:
            await app_process_monkey_intent(pkg, intent_action, uri_template, cmd)
            reply = "On it!"
        PENDING_INTENT = None
        await speak(reply)
        return {"action": "handled", "text": reply}

    # ── 2. GAME: SPELLING ──
    if "stop game" in cmd or "quit game" in cmd:
        GAME_STATE["active"] = False
        reply = "Game stopped. Want to try something else?"
        await speak(reply)
        return {"action": "handled", "text": reply}

    if GAME_STATE["active"] and GAME_STATE["type"] == "spelling":
        cleaned = cmd.strip().lower()
        target = GAME_STATE["target_word"].lower()
        # Accept exact match OR high word-overlap (fuzzy / partial answer)
        heard_words = cleaned.split()
        target_words = target.split()
        overlap = len(set(heard_words) & set(target_words)) / max(len(target_words), 1)
        if cleaned == target or overlap >= 0.75:
            reply = f"Correct! '{GAME_STATE['target_word'].title()}' — nailed it! 🎯"
            GAME_STATE["active"] = False
            GAME_STATE["misses"] = 0
        else:
            GAME_STATE["misses"] = GAME_STATE.get("misses", 0) + 1
            if GAME_STATE["misses"] >= 3:
                reply = f"Out of tries! The word was '{GAME_STATE['target_word'].title()}' — {GAME_STATE['hint']}. We'll try another later!"
                GAME_STATE["active"] = False
                GAME_STATE["misses"] = 0
            else:
                remaining = 3 - GAME_STATE["misses"]
                reply = f"Not quite. Here's your hint: {GAME_STATE['hint']}. Give it another shot! ({remaining} {'try' if remaining == 1 else 'tries'} left)"
        await speak(reply)
        return {"action": "handled", "text": reply}

    if "spelling" in cmd or "spelling game" in cmd:
        words = [
            {"word": "adventure", "hint": "An exciting journey or experience"},
            {"word": "curious", "hint": "Eager to learn or know something"},
            {"word": "explore", "hint": "To travel through an unfamiliar place"},
            {"word": "incredible", "hint": "So extraordinary it's hard to believe"},
            {"word": "knowledge", "hint": "Facts and information you've learned"},
        ]
        chosen = random.choice(words)
        GAME_STATE.update(
            {
                "active": True,
                "type": "spelling",
                "target_word": chosen["word"],
                "hint": chosen["hint"],
            }
        )
        reply = f"Spelling challenge! Your clue: {chosen['hint']}. Type your answer!"
        await speak(reply)
        return {"action": "handled", "text": reply}

    # ── 3. PENDING FOLLOW-UP ──
    if WAITING_FOR_PROMPT:
        WAITING_FOR_PROMPT = False
        if cmd in ["yes", "yeah", "sure", "ok", "please", "tell me", "yep", "go ahead"]:
            reply = PENDING_DEEP_ANSWER if PENDING_DEEP_ANSWER else "Hmm..."
            PENDING_DEEP_ANSWER = ""
            await speak(reply)
            return {"action": "handled", "text": reply}
        elif cmd in ["no", "nope", "nah", "nevermind", "pass"]:
            PENDING_DEEP_ANSWER = ""
            reply = "Ok."
            await speak(reply)
            return {"action": "handled", "text": reply}

    WAITING_FOR_PROMPT = False

    # ── 4. FAST PATH: SMALL TALK ──
    canned = check_small_talk(cmd)
    if canned:
        # Occasionally ask an LLM for a variant to keep it fresh (5% chance)
        if random.random() < 0.05:
            LILLY_IS_THINKING = True
            llm_variant = await llama_backend.chat(
                [
                    {
                        "role": "system",
                        "content": "You are Lilly — a warm, natural friend living in a phone. Respond like an old friend casually chatting. One sentence max, full words, maybe a word filler like 'uh' or 'like' or 'you know'. Never say 'AI assistant' or claim to be an AI.",
                    },
                    {"role": "user", "content": cmd},
                ],
                temperature=0.9,
                max_tokens=60,
            )
            if llm_variant:
                canned = llm_variant
        LILLY_IS_THINKING = False
        await speak(canned)
        await memory.add("user", cmd)
        await memory.add("assistant", canned)
        return {"action": "handled", "text": canned}

    # ── 5. OS NAVIGATION ──
    nav_action = fuzzy_nav(cmd)
    if nav_action:
        nav_map = {
            "back": ["4"],
            "home": ["3"],
            "recent apps": ["187"],
            "notifications": ["40"],
            "quick settings": ["41"],
            "screenshot": ["120"],
            "power menu": ["26"],
            "volume up": ["24"],
            "volume down": ["25"],
        }
        if nav_action in nav_map:
            await _input_keyevent(*nav_map[nav_action])
        elif nav_action == "settings":
            await termux_run(
                [
                    "am",
                    "start",
                    "-a",
                    "android.settings.SETTINGS",
                    "-p",
                    "com.android.settings",
                ],
                timeout=5.0,
            )
        elif nav_action == "dark mode":
            await termux_run(
                ["settings", "put", "secure", "ui_night_mode", "1"], timeout=3.0
            )
        elif nav_action == "light mode":
            await termux_run(
                ["settings", "put", "secure", "ui_night_mode", "0"], timeout=3.0
            )
        return {"action": "handled", "text": ""}

    # ── 5b. FACE IDENTITY (remember / results / who / forget) ──
    try:
        face_cmd = await _handle_face_command(cmd)
    except Exception as e:
        logger.debug(f"face command failed: {e}")
        face_cmd = None
    if face_cmd:
        return face_cmd

    # ── 6. CURSOR CONTROL (precise position) ──
    cursor_aliases = [
        "cursor up",
        "cursor down",
        "cursor left",
        "cursor right",
        "cursor home",
        "cursor reset",
        "mouse up",
        "mouse down",
        "mouse left",
        "mouse right",
        "pointer up",
        "pointer down",
        "pointer left",
        "pointer right",
    ]
    for a in cursor_aliases:
        if a in cmd:
            if "up" in a:
                CURSOR_Y = max(0, CURSOR_Y - CURSOR_STEP)
            elif "down" in a:
                CURSOR_Y = min(2000, CURSOR_Y + CURSOR_STEP)
            elif "left" in a:
                CURSOR_X = max(0, CURSOR_X - CURSOR_STEP)
            elif "right" in a:
                CURSOR_X = min(1080, CURSOR_X + CURSOR_STEP)
            if "home" in a or "reset" in a:
                CURSOR_X, CURSOR_Y = 540, 960
            await _input_swipe(CURSOR_X, CURSOR_Y, CURSOR_X, CURSOR_Y)
            await speak(f"Cursor at {CURSOR_X}, {CURSOR_Y}")
            return {"action": "handled", "text": ""}

    # ── 7. swipe / scroll ──
    # Swipe is a single gesture; "scroll" is a held repeated dpad keyevent
    # so it feels natural — "scroll down" keeps pressing DPAD_DOWN rapidly
    swipe_map = {
        "swipe down": (500, 1500, 500, 500),
        "swipe up": (500, 500, 500, 1500),
        "swipe left": (900, 800, 100, 800),
        "swipe right": (100, 800, 900, 800),
    }
    for trigger, (x1, y1, x2, y2) in swipe_map.items():
        if trigger in cmd:
            await _input_swipe(x1, y1, x2, y2)
            return {"action": "handled", "text": ""}

    # ── 7b. DPAD / directional keys — spoken navigation ──
    # Single tap: "dpad up/down/left/right", "go up/down/left/right", "up/down/left/right"
    # Scroll (held repeat): "scroll up/down/left/right" → fires DPAD key N times rapidly
    _SCROLL_REPEATS = 6  # how many keyevents constitute one "scroll"

    async def _dpad_repeat(key: str, repeats: int = _SCROLL_REPEATS):
        """Fire a dpad keyevent multiple times quickly to simulate a scroll."""
        for _ in range(repeats):
            await _input_keyevent(key)
            await asyncio.sleep(0.05)

    dpad_single = {
        "dpad up": "19",
        "dpad down": "20",
        "dpad left": "21",
        "dpad right": "22",
        "go up": "19",
        "go down": "20",
        "go left": "21",
        "go right": "22",
        "move up": "19",
        "move down": "20",
        "move left": "21",
        "move right": "22",
        "navigate up": "19",
        "navigate down": "20",
        "navigate left": "21",
        "navigate right": "22",
        "press enter": "23",
        "press select": "23",
        "press": "23",
    }
    dpad_scroll = {
        "scroll up": "19",
        "scroll down": "20",
        "scroll left": "21",
        "scroll right": "22",
    }

    # Check scroll first (more specific)
    for trigger, key in dpad_scroll.items():
        if trigger in cmd:
            # Extract optional count: "scroll down 3 times" → 3 × _SCROLL_REPEATS
            count_match = re.search(r"(\d+)\s*(?:times?|x)", cmd)
            repeats = (
                int(count_match.group(1)) * _SCROLL_REPEATS
                if count_match
                else _SCROLL_REPEATS
            )
            await _dpad_repeat(key, repeats)
            return {"action": "handled", "text": ""}

    for trigger, key in dpad_single.items():
        if trigger in cmd:
            await _input_keyevent(key)
            return {"action": "handled", "text": ""}

    # ── 8. TAP / SELECT (cursor position) ──
    if (
        cmd in ["select", "tap", "click"]
        or cmd.startswith("tap ")
        or cmd.startswith("click ")
    ):
        await _input_tap(CURSOR_X, CURSOR_Y)
        await speak(f"Tapped at {CURSOR_X}, {CURSOR_Y}")
        return {"action": "handled", "text": ""}

    # ── 9. CLOSE / QUIT ──
    if cmd in ["close", "quit", "exit"] or cmd.startswith("close "):
        await _input_keyevent("3")
        reply = "Going home!"
        await speak(reply)
        return {"action": "handled", "text": reply}

    # ── 9b. NEARBY PLACES (runs before skill matching to catch "where" / "find" patterns) ──
    # Skip if this is a Bluetooth/device query — let section 11 handle it
    _bt_skip = any(
        w in cmd
        for w in [
            "bluetooth",
            "device",
            "who",
            "who's",
            "whos",
            "anyone",
            "paired",
            "connected",
            "wireless",
            "nearby device",
        ]
    )
    nearby_trigger = re.search(
        r"(?:nearest|nearby|around here|near me|close to me|close by|in the area|close to here)\s*(.*)",
        cmd,
        re.IGNORECASE,
    )
    if nearby_trigger and not _bt_skip:
        query = nearby_trigger.group(1).strip()
        if not query:
            alt = re.search(
                r"(?:find|get|buy|eat|look for|search for)\s+(.+)", cmd, re.IGNORECASE
            )
            if alt:
                query = alt.group(1).strip()
        loc = await current_location()
        if loc:
            lat, lon, name, addr, *_ = loc
            _last_location_name = name
            search_q = urllib.parse.quote(query) if query else ""
            maps_url = f"https://www.google.com/maps/search/{search_q}/@{lat},{lon},14z"
            await termux_run(["termux-open", maps_url], timeout=5.0)
            reply = (
                f"Looking for {query} near you. Maps is open on your phone."
                if query
                else f"Showing nearby places. You're near {name or 'your location'}."
            )
            await speak(reply)
            addr_str = ""
            if isinstance(addr, dict):
                addr_str = addr.get("formatted", "") or addr.get("road", "") or ""
            elif isinstance(addr, str):
                addr_str = addr
            return {
                "action": "handled",
                "text": reply,
                "phone_action": {
                    "app": "Maps",
                    "package": "com.google.android.apps.maps",
                    "status": "launched",
                    "arg": query or "My Location",
                },
                "display": {
                    "type": "map",
                    "lat": lat,
                    "lng": lon,
                    "label": f"{name or 'Your location'}{(' — ' + addr_str) if addr_str else ''}",
                },
            }
        else:
            reply = "I can't get your location right now. Try again when you have a GPS fix."
        await speak(reply)
        return {"action": "handled", "text": reply}

    # ── PERSONA SELF-IMPROVEMENT (authorized) ──────────────────────────────
    # Lilly can propose changes to her own persona. She always asks first.
    # Triggers: "update your persona", "change how you talk", "improve yourself",
    #           "adjust your personality", "update lilly", "refine yourself", etc.
    _self_improve_triggers = [
        "update your persona",
        "change how you talk",
        "improve yourself",
        "adjust your personality",
        "update lilly",
        "refine yourself",
        "update yourself",
        "change your personality",
        "tweak your persona",
        "evolve yourself",
        "self-improve",
        "optimize yourself",
        "change how you respond",
        "update your voice",
        "update your prompt",
    ]
    if trig_in(cmd, *_self_improve_triggers):
        # Check if user is providing a specific change request or just enabling it
        _proposed_change = cmd
        for t in _self_improve_triggers:
            _proposed_change = _proposed_change.replace(t, "").strip()
        _proposed_change = _proposed_change.strip(" :.,-")

        if not _proposed_change:
            # Generic enable — ask what they want changed
            reply = "What specifically do you want me to adjust? Tone, how I handle certain topics, something I keep getting wrong?"
        else:
            # They gave a specific change — propose it and ask for approval
            _pending_persona_change = {
                "change": _proposed_change,
                "requested_at": time.time(),
                "persona": current_avatar,
            }
            # Store pending change for confirmation
            handle_intent._pending_persona_change = _pending_persona_change
            PENDING_CONFIRM = {
                "desc": f"update my persona: {_proposed_change[:80]}",
                "skill": "_persona_update",
                "skill_arg": _proposed_change,
                "expires": time.time() + 120,
            }
            reply = (
                f"Got it — I'd adjust: {_proposed_change[:100]}. Want me to apply that?"
            )
        await memory.add("user", text)
        await memory.add("assistant", reply)
        await save_memory()
        await speak(reply)
        return {"action": "handled", "text": reply}

    # Apply persona update if confirmed
    if (
        PENDING_CONFIRM
        and PENDING_CONFIRM.get("skill") == "_persona_update"
        and cmd in ("yes", "yeah", "sure", "do it", "apply it", "go ahead", "confirmed")
        and time.time() < PENDING_CONFIRM.get("expires", 0)
    ):
        _change_arg = PENDING_CONFIRM.get("skill_arg", "")
        PENDING_CONFIRM = None
        _applied = False
        _apply_msg = ""
        if PERSONA_OPTIMIZER_AVAILABLE and persona_optimizer and _change_arg:
            try:
                # Read current voice prompt
                _cur_prompt = HIVE_PERSONAS[current_avatar]["voice_prompt"]
                # Append the user's requested change as a new instruction
                _new_note = f"\n\n[User-authorized update: {_change_arg}]"
                if _new_note not in _cur_prompt:
                    _updated_prompt = _cur_prompt + _new_note
                    # Patch in-memory persona
                    HIVE_PERSONAS[current_avatar]["voice_prompt"] = _updated_prompt
                    # Persist to persona_configs.json
                    persona_optimizer.set_voice_prompt(current_avatar, _updated_prompt)
                    _applied = True
                    _apply_msg = (
                        f"Done. Applied: {_change_arg[:80]}. I'll remember this."
                    )
            except Exception as _pe:
                logger.warning(f"Persona update failed: {_pe}")
        if not _applied:
            # Fallback: patch in-memory only
            try:
                _cur_prompt = HIVE_PERSONAS[current_avatar]["voice_prompt"]
                _new_note = f"\n\n[User-authorized update: {_change_arg}]"
                if _new_note not in _cur_prompt:
                    HIVE_PERSONAS[current_avatar]["voice_prompt"] = (
                        _cur_prompt + _new_note
                    )
                _apply_msg = f"Applied in this session: {_change_arg[:80]}. Won't survive a restart without the optimizer."
            except Exception:
                _apply_msg = "Couldn't apply that change — something went wrong."
        reply = _apply_msg
        await memory.add("user", text)
        await memory.add("assistant", reply)
        await save_memory()
        await speak(reply)
        return {"action": "handled", "text": reply}

    # ── AUTOMATION FROM CHAT ────────────────────────────────────────────────
    # Lilly can create automation rules from plain-English requests.
    # "remind me when battery drops below 20%"
    # "alert me if I haven't moved in 2 hours"
    # "create automation: notify me when charging starts"
    # "set up automation: ..."
    # "add a rule to ..."
    _auto_create_triggers = [
        "remind me when",
        "alert me when",
        "alert me if",
        "notify me when",
        "notify me if",
        "create automation",
        "set up automation",
        "add a rule",
        "add automation",
        "automate:",
        "automation:",
        "when battery",
        "when charging",
        "if battery",
        "if i haven",
        "if i'm not",
    ]
    # Only treat as automation (not time-based reminder) if it references
    # a sensor condition or event keyword — not a time ("in 30 minutes", "at 9am")
    _auto_condition_words = [
        "battery",
        "charging",
        "sensor",
        "light",
        "notification",
        "bluetooth",
        "wifi",
        "step",
        "motion",
        "temperature",
        "pressure",
        "haven't moved",
        "i'm not moving",
        "plugged",
        "unplugged",
        "drops below",
        "goes above",
        "reaches",
        "above",
        "below",
    ]
    _is_condition_based = any(w in cmd for w in _auto_condition_words)
    _auto_list_triggers = [
        "list automations",
        "show automations",
        "what automations",
        "my automations",
    ]
    _auto_delete_triggers = [
        "delete automation",
        "remove automation",
        "cancel automation",
        "disable automation",
    ]

    if trig_in(cmd, *_auto_list_triggers):
        if PHONE_BROKER_AVAILABLE and phone_broker:
            _rules = phone_broker.automation.get_rules()
            if _rules:
                _rule_lines = [
                    f"- {r['name']}: {r.get('condition', {})} → {r.get('action_type', '')}"
                    for r in _rules[:10]
                ]
                reply = "Active automations:\n" + "\n".join(_rule_lines)
            else:
                reply = "No automations set up yet."
        else:
            reply = "Automation engine isn't available right now."
        await memory.add("user", text)
        await memory.add("assistant", reply)
        await save_memory()
        await speak(reply)
        return {"action": "handled", "text": reply}

    if trig_in(cmd, *_auto_delete_triggers):
        # Ask which one
        if PHONE_BROKER_AVAILABLE and phone_broker:
            _rules = phone_broker.automation.get_rules()
            if _rules:
                _names = ", ".join(r["name"] for r in _rules[:5])
                reply = f"Which one? Active: {_names}"
            else:
                reply = "No automations to remove."
        else:
            reply = "Automation engine isn't available."
        await memory.add("user", text)
        await memory.add("assistant", reply)
        await save_memory()
        await speak(reply)
        return {"action": "handled", "text": reply}

    _if_then = (
        _is_condition_based
        and " then " in f" {cmd} "
        and (cmd.startswith("if ") or " if " in f" {cmd} " or "whenever" in cmd)
    )
    if (trig_in(cmd, *_auto_create_triggers) or _if_then) and _is_condition_based:
        # First try regex parsing for common patterns (fast, no LLM needed)
        _auto_rule = None
        _batt_m = re.search(
            r"battery\s+(drops?\s+)?(below|under|less than|<)\s*(\d+)",
            cmd,
            re.IGNORECASE,
        )
        _batt_above_m = re.search(
            r"battery\s+(goes?\s+)?(above|over|more than|>)\s*(\d+)", cmd, re.IGNORECASE
        )
        _charge_m = re.search(
            r"(start|begin|stop|finish)\s+charging|plugged\s+in|unplugged",
            cmd,
            re.IGNORECASE,
        )
        if _batt_m:
            _val = int(_batt_m.group(3))
            _auto_rule = {
                "name": f"Battery below {_val}%",
                "topic": "battery",
                "condition": {"field": "battery_level", "op": "<", "value": _val},
                "action_type": "notify",
                "action_payload": {
                    "title": "Battery Low",
                    "body": f"Battery dropped below {_val}%.",
                },
                "cooldown_seconds": 300.0,
            }
        elif _batt_above_m:
            _val = int(_batt_above_m.group(3))
            _auto_rule = {
                "name": f"Battery above {_val}%",
                "topic": "battery",
                "condition": {"field": "battery_level", "op": ">", "value": _val},
                "action_type": "notify",
                "action_payload": {
                    "title": "Battery Charged",
                    "body": f"Battery reached {_val}%.",
                },
                "cooldown_seconds": 300.0,
            }
        elif _charge_m:
            _auto_rule = {
                "name": "Charging state changed",
                "topic": "battery",
                "condition": {"field": "charging", "op": "==", "value": True},
                "action_type": "notify",
                "action_payload": {
                    "title": "Charging",
                    "body": "Charging state changed.",
                },
                "cooldown_seconds": 60.0,
            }
        if _auto_rule is None:
            # Fall back to LLM for complex cases
            _auto_parse_messages = [
                {
                    "role": "system",
                    "content": (
                        "Extract automation rule parameters from the user request. "
                        "Return ONLY a JSON object: {name, topic, condition:{field,op,value}, "
                        "action_type, action_payload:{title,body}}. Nothing else."
                    ),
                },
                {"role": "user", "content": cmd},
            ]
            try:
                _raw = await asyncio.wait_for(
                    two_tier_backend.chat(
                        _auto_parse_messages, temperature=0.2, max_tokens=200
                    ),
                    timeout=8.0,
                )
                _raw = strip_json_wrapper(_raw or "").strip()
                _jm = re.search(r"\{.*\}", _raw, re.DOTALL)
                if _jm:
                    _auto_rule = json.loads(_jm.group(0))
            except Exception as _ae:
                logger.warning(f"Auto rule LLM parse failed: {_ae}")
        # Clarity step: if the extracted rule is ambiguous, ask ONE targeted
        # question first — the answer merges in, then we progress to create.
        _clarify_q = _automation_clarify_question(_auto_rule) if _auto_rule else None
        if _clarify_q:
            PENDING_AUTOMATION = {
                "rule": _auto_rule,
                "original_cmd": cmd,
                "question": _clarify_q,
                "clarifications": 0,
                "expires": time.time() + 300,
            }
            reply = _clarify_q
            await memory.add("user", text)
            await memory.add("assistant", reply)
            await save_memory()
            await speak(reply)
            return {"action": "handled", "text": reply}

        if _auto_rule:
            _rule_name = _auto_rule.get("name", "New Rule")
            _rule_cond = _auto_rule.get("condition", {})
            _rule_action = _auto_rule.get("action_type", "notify")
            handle_intent._pending_auto_rule = _auto_rule
            PENDING_CONFIRM = {
                "desc": "create automation " + _rule_name,
                "skill": "_auto_create",
                "skill_arg": json.dumps(_auto_rule),
                "expires": time.time() + 120,
            }
            _f = _rule_cond.get("field", "condition")
            _o = _rule_cond.get("op", "")
            _v = str(_rule_cond.get("value", ""))
            reply = f'I\'d set up: "{_rule_name}" \u2014 when {_f} {_o} {_v} \u2192 {_rule_action}. Create it?'
        else:
            reply = "I couldn't parse that into a rule. Try: 'remind me when battery drops below 20%'."
        await memory.add("assistant", reply)
        await save_memory()
        await speak(reply)
        return {"action": "handled", "text": reply}

    # Confirm automation creation
    if (
        PENDING_CONFIRM
        and PENDING_CONFIRM.get("skill") == "_auto_create"
        and cmd
        in ("yes", "yeah", "sure", "do it", "create it", "go ahead", "confirmed", "ok")
        and time.time() < PENDING_CONFIRM.get("expires", 0)
    ):
        _rule_json = PENDING_CONFIRM.get("skill_arg", "{}")
        PENDING_CONFIRM = None
        reply = await _create_automation_from_confirm(_rule_json)
        await memory.add("user", text)
        await memory.add("assistant", reply)
        await save_memory()
        await speak(reply)
        return {"action": "handled", "text": reply}

    # ── 10. SKILLS / APP LAUNCHER ──
    # Try matching against registered skills
    # Priority: exact match → stripped prefix match → prefix in skill keys
    target = cmd.strip()

    # SAFETY: Skip all skill matching for long messages (>50 chars) —
    # they're conversational, not app commands. This prevents false triggers
    # like "I want to show you something" matching the "show" skill.
    skill = None
    skill_arg = ""
    if len(target) <= 50:
        # ── 10a. PROACTIVE ALIAS DISCOVERY — enrich existing skills from novel user keywords ──
        words_in_cmd = set(normalize_text(w) for w in target.split() if len(w) > 2)
        if words_in_cmd:
            existing_aliases = set()
            for s in SKILLS.values():
                for a in s.get("aliases", []):
                    existing_aliases.add(normalize_text(a))
                existing_aliases.add(normalize_text(s.get("label", "")))
            novel_words = words_in_cmd - existing_aliases
            if novel_words:
                for key, s in list(SKILLS.items()):
                    label_norm = normalize_text(s.get("label", ""))
                    # If a novel word is semantically close to this skill's label, offer alias
                    for nw in novel_words:
                        if len(nw) > 3 and (nw in label_norm or label_norm in nw):
                            if normalize_text(nw) not in [
                                normalize_text(a) for a in s.get("aliases", [])
                            ]:
                                # Auto-register the alias
                                s.setdefault("aliases", []).append(nw)
                                SKILLS[normalize_text(nw)] = s
                                raw = (
                                    json.loads(SKILLS_FILE.read_text())
                                    if SKILLS_FILE.exists()
                                    else {}
                                )
                                if key in raw:
                                    raw[key].setdefault("aliases", []).append(nw)
                                    SKILLS_FILE.write_text(json.dumps(raw, indent=2))
                                logger.info(
                                    f"Auto-registered alias '{nw}' for skill '{key}'"
                                )
        stripped = re.sub(
            r"^(run|use|click|tap|open|launch|search|find|what|show|start)\s+",
            "",
            target,
        ).strip()
        skill = SKILLS.get(target) or SKILLS.get(stripped)

        # If no direct match, look for a skill key that prefixes the command.
        # Guard: keys shorter than 4 chars never prefix-match ("do" hijacked
        # every "do you..." question into an unrelated skill).
        if not skill:
            for key in sorted(SKILLS.keys(), key=len, reverse=True):
                if len(key) < 4:
                    continue
                if target.startswith(key + " "):
                    skill = SKILLS[key]
                    skill_arg = target[len(key) :].strip()
                    break

        # ── NLP pre-parse ──
        # Natural phrasings like "I want to watch youtube videos on true crime"
        # don't keyword-match. Parse them into (app skill, query) here before
        # falling through to LLM skill inference, which would lose the query.
        if not skill:
            nlp_skill, nlp_arg = parse_nlp_intent(target)
            if nlp_skill:
                skill = nlp_skill
                skill_arg = nlp_arg

    if skill:
        # Skip configuration/meta-skills (e.g. _context_aware) that have no
        # executable action_type and no type field — they are documentation,
        # not real action triggers.
        if not skill.get("action_type") and not skill.get("type"):
            skill = None

    if skill:
        # ── Ad skipping shortcut ──
        if skill.get("label", "").lower() == "skip ad":
            reply = await skip_ad()
            await speak(reply)
            return {"action": "handled", "text": reply}

        action = skill.get("action_type") or skill.get("type", "intent_launch")
        pkg = skill.get("package", "")

        # Canned demo mode — speak intent without phone execution if SSH is unavailable
        if not PHONE_SSH_OK and (
            action
            in ("intent_launch", "hybrid_intent_tap", "context_launch", "shell_command")
        ):
            label = skill.get("label", "app")
            if action == "shell_command":
                reply = f"Opening {label} on your phone! In demo mode — would open: {' '.join(skill.get('args', []))}"
            elif skill_arg:
                reply = f"Searching for {skill_arg} in {label}!"
            elif skill.get("canned_reply"):
                reply = skill["canned_reply"]
            else:
                reply = f"Launching {label}!"
            await speak(reply)
            return {"action": "handled", "text": reply}

        if action == "prompt_argument":
            if skill_arg:
                # Confirm before opening a search/URL on the phone
                gated = await _gate_phone_action(skill, skill_arg)
                if gated:
                    return {"action": "handled", "text": gated}
                url_query = urllib.parse.quote(skill_arg)
                if skill.get("uri_template"):
                    url = skill["uri_template"].replace("{}", url_query)
                else:
                    url = f"https://www.google.com/search?q={url_query}"
                # In Docker/browser context return URL for window.open; fallback to termux-open on Android
                is_docker = not shutil.which("termux-open")
                if is_docker:
                    reply = f"Searching for {skill_arg}!"
                    await speak(reply)
                    PENDING_OPEN_URL = url
                    return {"action": "handled", "text": reply, "open_url": url}
                await termux_run(["termux-open", url], timeout=5.0)
                reply = f"Searching for {skill_arg}!"
            else:
                PENDING_INTENT = skill
                reply = skill.get("canned_reply", "What would you like to look for?")
        elif action in ("intent_launch", "hybrid_intent_tap", "context_launch") and pkg:
            intent_action = skill.get("intent_action", "")
            uri_template = skill.get("uri_template", "")
            if uri_template and "{}" in uri_template and not skill_arg:
                PENDING_INTENT = skill
                reply = skill.get("canned_reply", f"What would you like to search for?")
                await speak(reply)
                return {"action": "handled", "text": reply}
            # Confirm before launching an app / opening a URL on the phone
            gated = await _gate_phone_action(skill, skill_arg)
            if gated:
                return {"action": "handled", "text": gated}
            # YouTube: launch on phone (not browser PiP) — browser shows now-playing card
            if pkg in (
                "com.google.android.youtube",
                "com.google.android.apps.youtube.music",
            ):
                url = uri_template or "https://www.youtube.com"
                if skill_arg and "{}" in url:
                    url = url.replace("{}", urllib.parse.quote(skill_arg))
                elif skill_arg:
                    url = (
                        "https://www.youtube.com/results?search_query="
                        + urllib.parse.quote(skill_arg)
                    )
                await app_process_monkey_intent(
                    pkg, intent_action, uri_template, skill_arg
                )
                reply = f"Playing {skill_arg or 'YouTube'} on your phone!"
                await speak(reply)
                return {
                    "action": "handled",
                    "text": reply,
                    "phone_action": {
                        "app": skill.get("label", "YouTube"),
                        "package": pkg,
                        "status": "launched",
                        "arg": skill_arg or "",
                    },
                }
            await app_process_monkey_intent(pkg, intent_action, uri_template, skill_arg)
            reply = f"Launching {skill.get('label', 'app')} on your phone!"
            return {
                "action": "handled",
                "text": reply,
                "phone_action": {
                    "app": skill.get("label", "app"),
                    "package": pkg,
                    "status": "launched",
                    "arg": skill_arg or "",
                },
            }
        elif action == "shell_command":
            cmd_to_run = skill.get("command", "")
            subcmd = skill.get("subcommand", "")
            args = skill.get("args", [])
            no_arg = skill.get("no_arg", False)
            if no_arg:
                full_cmd = [cmd_to_run] + (args or [])
            elif skill_arg:
                full_cmd = (
                    [cmd_to_run]
                    + ([subcmd] if subcmd else [])
                    + (args or [])
                    + [skill_arg]
                )
            else:
                PENDING_INTENT = skill
                reply = skill.get(
                    "canned_reply",
                    f"What argument for {skill.get('label', 'command')}?",
                )
                await speak(reply)
                return {"action": "handled", "text": reply}
            # Confirm before running a shell command
            gated = await _gate_phone_action(skill, skill_arg)
            if gated:
                return {"action": "handled", "text": gated}
            try:
                proc = await asyncio.create_subprocess_exec(
                    *full_cmd,
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.PIPE,
                )
                stdout, stderr = await asyncio.wait_for(
                    proc.communicate(), timeout=30.0
                )
                output = stdout.decode().strip() or stderr.decode().strip()
                reply = f"Done: {output[:200]}" if output else "Command executed."
            except asyncio.TimeoutError:
                reply = "Command timed out."
            except FileNotFoundError:
                reply = f"Command '{cmd_to_run}' not found in container."
        elif action == "termux":
            # Termux:API tool (runs on the phone over SSH)
            binary = skill.get("binary", "")
            if not binary:
                reply = "Running that now."
            else:
                gated = await _gate_phone_action(skill, skill_arg)
                if gated:
                    return {"action": "handled", "text": gated}
                cmd_to_run = [binary] + (skill.get("args", []) or [])
                if not skill.get("no_arg") and skill_arg:
                    cmd_to_run.append(skill_arg)
                stdout, stderr = await termux_run(cmd_to_run, timeout=15.0)
                output = stdout.strip() or stderr.strip()
                reply = (
                    output[:300]
                    if output
                    else f"Done — {skill.get('label', 'command')}."
                )
        elif action == "openhuman_skill":
            # OpenHuman community skill — download/execute the SKILL.md workflow.
            skill_id = skill.get("skill_id") or skill.get("label", "")
            skill_arg_text = skill_arg if skill_arg else cmd
            reply = await execute_openhuman_skill(skill_id, current_avatar)
            # Pass the skill argument through as context for the skill runner
            if skill_arg_text and skill_arg_text != cmd:
                reply = f"{reply} — with input: {skill_arg_text}"
            await speak(reply)
            return {"action": "handled", "text": reply}
        else:
            reply = "Running that now."
        await speak(reply)
        return {"action": "handled", "text": reply}

    # ── 10b. PROACTIVE SKILL INFERENCE — LLM detects unregistered app intents ──
    async def infer_and_create_skill(cmd: str) -> Optional[dict]:
        infer_prompt = (
            "You are a skill extractor. Given a user command, determine if they are asking "
            "to open or use a mobile app or website. If yes, respond with valid JSON:\n"
            '{"skill": true, "key": "app_name_key", "label": "Human Readable Name", '
            '"package": "com.example.app", "uri_template": "https://...", '
            '"aliases": ["alias1", "alias2"], "canned_reply": "Opening app!"}\n'
            'If no app is detected, respond with: {"skill": false}\n'
            "Be proactive — if the user mentions an app that doesn't exist as a skill, "
            "infer the Android package name and a reasonable URI.\n"
            f"User said: {cmd}"
        )
        try:
            resp = await llama_backend.chat(
                [
                    {
                        "role": "system",
                        "content": "You are a skill extractor. Output ONLY valid JSON.",
                    },
                    {"role": "user", "content": infer_prompt},
                ],
                temperature=0.2,
                max_tokens=200,
            )
            resp_clean = resp.strip().strip("```json").strip("```").strip()
            inferred = json.loads(resp_clean)
            if inferred.get("skill"):
                new_key = inferred["key"]
                new_skill = {
                    "package": inferred.get("package", ""),
                    "action_type": "intent_launch",
                    "type": "intent_launch",
                    "intent_action": "android.intent.action.VIEW",
                    "label": inferred["label"],
                    "canned_reply": inferred.get(
                        "canned_reply", f"Opening {inferred['label']}!"
                    ),
                    "aliases": inferred.get("aliases", []),
                }
                if inferred.get("uri_template"):
                    new_skill["uri_template"] = inferred["uri_template"]
                # Persist to skills file
                raw = (
                    json.loads(SKILLS_FILE.read_text()) if SKILLS_FILE.exists() else {}
                )
                raw[new_key] = new_skill
                SKILLS_FILE.write_text(json.dumps(raw, indent=2))
                # Reload in memory
                SKILLS[normalize_text(new_key)] = new_skill
                for a in new_skill.get("aliases", []):
                    SKILLS[normalize_text(a)] = new_skill
                logger.info(
                    f"Proactively created skill '{new_key}' from user command: {cmd}"
                )
                return new_skill
        except Exception as e:
            logger.debug(f"Skill inference failed (non-critical): {e}")
        return None

    if not skill:
        inferred_skill = await infer_and_create_skill(cmd)
        if inferred_skill:
            pkg = inferred_skill.get("package", "")
            intent_action = inferred_skill.get("intent_action", "")
            uri_template = inferred_skill.get("uri_template", "")
            await app_process_monkey_intent(pkg, intent_action, uri_template, "")
            reply = f"Opening {inferred_skill['label']}!"
            await speak(reply)
            return {"action": "handled", "text": reply}

