async def capture_vision_frame() -> Optional[bytes]:
    """Capture a frame from the first available webcam using a persistent capture."""
    cv2 = _try_import_cv2()
    if cv2 is None:
        return None
    cap = get_video_capture()
    if cap is None or not cap.isOpened():
        return None
    try:
        for _ in range(3):
            ret, frame = cap.read()
            if ret:
                break
        if not ret:
            return None
        ret2, buf = cv2.imencode(".jpg", frame, [cv2.IMWRITE_JPEG_QUALITY, 85])
        if ret2:
            return buf.tobytes()
    except Exception:
        pass
    return None


def _draw_detections(frame, detections):
    """Draw bounding boxes and labels on the frame."""
    cv2 = _try_import_cv2()
    if cv2 is None:
        return frame
    for det in detections:
        x1, y1, x2, y2 = int(det["x1"]), int(det["y1"]), int(det["x2"]), int(det["y2"])
        label = det["label"]
        conf = det.get("confidence", 0.0)
        color = (50, 200, 120)
        cv2.rectangle(frame, (x1, y1), (x2, y2), color, 2)
        text = f"{label} {conf:.0%}" if conf > 0 else label
        (tw, th), _ = cv2.getTextSize(text, cv2.FONT_HERSHEY_SIMPLEX, 0.5, 1)
        cv2.rectangle(frame, (x1, y1 - th - 6), (x1 + tw + 6, y1), color, -1)
        cv2.putText(
            frame,
            text,
            (x1 + 3, y1 - 3),
            cv2.FONT_HERSHEY_SIMPLEX,
            0.5,
            (255, 255, 255),
            1,
        )
    return frame


def _load_coco_model():
    """Load the COCO model (80 classes) for dual detection. Auto-downloads if missing."""
    global _YOLO_MODEL_COCO
    if _YOLO_MODEL_COCO is not None:
        return _YOLO_MODEL_COCO
    YOLO = _try_import_ultralytics()
    if not YOLO:
        return None
    search_paths = [
        WORKSPACE / "yolov8x.pt",
        WORKSPACE / "yolov8s.pt",
        WORKSPACE / "yolov8n.pt",
        Path.home() / ".lilly" / "yolov8x.pt",
        Path.home() / ".lilly" / "yolov8s.pt",
        Path.home() / ".lilly" / "yolov8n.pt",
    ]
    model_path = None
    for p in search_paths:
        if p.exists():
            model_path = p
            break
    if model_path is None:
        model_path = Path.home() / ".lilly" / "yolov8x.pt"
        model_path.parent.mkdir(parents=True, exist_ok=True)
        logger.info("Vision: Downloading YOLOv8x COCO model (80 classes, first run)...")
        import urllib.request

        urllib.request.urlretrieve(
            "https://github.com/ultralytics/assets/releases/download/v8.2.0/yolov8x.pt",
            str(model_path),
        )
    _YOLO_MODEL_COCO = YOLO(str(model_path))
    logger.info(f"Vision: COCO model loaded from {model_path}")
    return _YOLO_MODEL_COCO


def _run_dual_detection(frame) -> list[dict]:
    """Run both COCO (80 classes) and Open Images V7 (601 classes) models.
    Merge results, deduplicate by overlapping boxes, keep highest confidence."""
    global _YOLO_MODEL, _YOLO_MODEL_COCO

    YOLO = _try_import_ultralytics()
    if not YOLO:
        return []

    # Load Open Images V7 model (primary, 601 classes) — prefer yolov8x for max accuracy
    if _YOLO_MODEL is None:
        search_paths = [
            WORKSPACE / "yolov8x.pt",
            WORKSPACE / "yolov8l.pt",
            WORKSPACE / "yolov8m.pt",
            WORKSPACE / "yolov8s.pt",
            WORKSPACE / "yolov8n-oiv7.pt",
            Path.home() / ".lilly" / "yolov8x.pt",
            Path.home() / ".lilly" / "yolov8s.pt",
            Path.home() / ".lilly" / "yolov8n-oiv7.pt",
            WORKSPACE / "yolov8n.pt",
            Path.home() / ".lilly" / "yolov8n.pt",
        ]
        for p in search_paths:
            if p.exists():
                _YOLO_MODEL = YOLO(str(p))
                break

    # Load COCO model (secondary, 80 classes, high accuracy)
    _load_coco_model()

    all_detections = []

    # Run Open Images V7 (601 classes)
    if _YOLO_MODEL:
        try:
            results = _YOLO_MODEL(frame, verbose=False)
            for r in results:
                for box in r.boxes:
                    x1, y1, x2, y2 = box.xyxy[0].tolist()
                    cls = int(box.cls[0])
                    conf = float(box.conf[0])
                    label = _YOLO_MODEL.names.get(cls, f"obj_{cls}")
                    if conf > 0.45:
                        all_detections.append(
                            {
                                "label": label,
                                "confidence": conf,
                                "x1": x1,
                                "y1": y1,
                                "x2": x2,
                                "y2": y2,
                                "source": "oiv7",
                            }
                        )
        except Exception as e:
            logger.debug(f"Open Images V7 detection error: {e}")

    # Run COCO (80 classes) — fills gaps where COCO is more accurate
    if _YOLO_MODEL_COCO:
        try:
            results = _YOLO_MODEL_COCO(frame, verbose=False)
            for r in results:
                for box in r.boxes:
                    x1, y1, x2, y2 = box.xyxy[0].tolist()
                    cls = int(box.cls[0])
                    conf = float(box.conf[0])
                    label = (
                        COCO_CLASSES[cls] if cls < len(COCO_CLASSES) else f"obj_{cls}"
                    )
                    if conf > 0.45:
                        all_detections.append(
                            {
                                "label": label,
                                "confidence": conf,
                                "x1": x1,
                                "y1": y1,
                                "x2": x2,
                                "y2": y2,
                                "source": "coco",
                            }
                        )
        except Exception as e:
            logger.debug(f"COCO detection error: {e}")

    # Deduplicate: if two boxes overlap significantly, keep higher confidence
    merged = []
    used = set()
    for i, d1 in enumerate(all_detections):
        if i in used:
            continue
        best = d1
        for j, d2 in enumerate(all_detections):
            if j <= i or j in used:
                continue
            # Check box overlap (IoU)
            ix1 = max(d1["x1"], d2["x1"])
            iy1 = max(d1["y1"], d2["y1"])
            ix2 = min(d1["x2"], d2["x2"])
            iy2 = min(d1["y2"], d2["y2"])
            inter = max(0, ix2 - ix1) * max(0, iy2 - iy1)
            area1 = (d1["x2"] - d1["x1"]) * (d1["y2"] - d1["y1"])
            area2 = (d2["x2"] - d2["x1"]) * (d2["y2"] - d2["y1"])
            iou = inter / (area1 + area2 - inter + 1e-6)
            if iou > 0.5:  # Significant overlap
                if d2["confidence"] > best["confidence"]:
                    used.add(i)
                    best = d2
                else:
                    used.add(j)
        merged.append(best)

    return merged


async def detect_objects(frame_bytes: bytes) -> tuple[bytes, list[dict]]:
    """Run object detection on a JPEG frame, return labeled JPEG + detections."""
    global _YOLO_MODEL

    # ── External vision server proxy ─────────────────────────────
    if VISION_SERVER_URL and not PREFER_LOCAL_DETECTION:
        proxy_resp = await _proxy_vision_frame(frame_bytes)
        if proxy_resp and proxy_resp.get("detections"):
            cv2 = _try_import_cv2()
            detections = []
            h, w = 1, 1
            frame = None
            if cv2 is not None:
                try:
                    import numpy as np

                    nparr = np.frombuffer(frame_bytes, np.uint8)
                    frame = cv2.imdecode(nparr, cv2.IMREAD_COLOR)
                    if frame is not None:
                        h, w = frame.shape[:2]
                except Exception:
                    pass

            for d in proxy_resp["detections"]:
                label = d.get("label", "object")
                conf = float(d.get("conf", d.get("confidence", 0)))
                nx = float(d.get("x", 0))
                ny = float(d.get("y", 0))
                nw = float(d.get("w", 0))
                nh = float(d.get("h", 0))
                x1 = nx * w
                y1 = ny * h
                x2 = (nx + nw) * w
                y2 = (ny + nh) * h
                detections.append(
                    {
                        "label": label,
                        "confidence": conf,
                        "x1": x1,
                        "y1": y1,
                        "x2": x2,
                        "y2": y2,
                    }
                )

            if frame is not None and cv2 is not None:
                frame = _draw_detections(frame, detections)
                ret2, buf = cv2.imencode(".jpg", frame, [cv2.IMWRITE_JPEG_QUALITY, 85])
                if ret2:
                    return buf.tobytes(), detections

            return frame_bytes, detections

    cv2 = _try_import_cv2()
    if cv2 is None:
        return frame_bytes, []

    try:
        import numpy as np

        nparr = np.frombuffer(frame_bytes, np.uint8)
        frame = cv2.imdecode(nparr, cv2.IMREAD_COLOR)
        if frame is None:
            return frame_bytes, []
    except Exception:
        return frame_bytes, []

    detections = []

    # Try YOLO — dual mode (COCO + Open Images V7) or single model
    YOLO = _try_import_ultralytics()
    if YOLO and _vision_enabled:
        try:
            if _DUAL_DETECTION:
                detections = _run_dual_detection(frame)
            else:
                # Single model mode (fallback)
                if _YOLO_MODEL is None:
                    search_paths = [
                        WORKSPACE / "yolov8x.pt",
                        WORKSPACE / "yolov8l.pt",
                        WORKSPACE / "yolov8m.pt",
                        WORKSPACE / "yolov8s.pt",
                        WORKSPACE / "yolov8n-oiv7.pt",
                        Path.home() / ".lilly" / "yolov8x.pt",
                        Path.home() / ".lilly" / "yolov8s.pt",
                        Path.home() / ".lilly" / "yolov8n-oiv7.pt",
                        WORKSPACE / "yolov8n.pt",
                        Path.home() / ".lilly" / "yolov8n.pt",
                    ]
                    for p in search_paths:
                        if p.exists():
                            _YOLO_MODEL = YOLO(str(p))
                            break
                if _YOLO_MODEL:
                    results = _YOLO_MODEL(frame, verbose=False)
                    for r in results:
                        for box in r.boxes:
                            x1, y1, x2, y2 = box.xyxy[0].tolist()
                            cls = int(box.cls[0])
                            conf = float(box.conf[0])
                            label = _YOLO_MODEL.names.get(cls, f"obj_{cls}")
                            detections.append(
                                {
                                    "label": label,
                                    "confidence": conf,
                                    "x1": x1,
                                    "y1": y1,
                                    "x2": x2,
                                    "y2": y2,
                                }
                            )
        except Exception as e:
            logger.debug(f"Vision detect error: {e}")

    # ── Face recognition: rename "person" → "John" etc. ──────────
    _person_labels = {
        "person",
        "Man",
        "Woman",
        "man",
        "woman",
        "Boy",
        "Girl",
        "boy",
        "girl",
    }
    if _vision_enabled and any(d.get("label") in _person_labels for d in detections):
        try:
            from face_recognition_engine import get_face_engine

            face_eng = get_face_engine()
            # Convert detections to normalized format for face engine
            h, w = frame.shape[:2]
            norm_dets = []
            for d in detections:
                norm_dets.append(
                    {
                        "label": d["label"],
                        "x": d["x1"] / w,
                        "y": d["y1"] / h,
                        "w": (d["x2"] - d["x1"]) / w,
                        "h": (d["y2"] - d["y1"]) / h,
                        "x1": d["x1"] / w,
                        "y1": d["y1"] / h,
                        "x2": d["x2"] / w,
                        "y2": d["y2"] / h,
                    }
                )
            enriched = face_eng.enrich_person_detections(frame, norm_dets)
            # Merge back — replace label if face engine renamed it
            for i, ed in enumerate(enriched):
                orig = ed.get("original_label", "")
                if orig and orig in _person_labels and ed["label"] != orig:
                    detections[i]["label"] = ed["label"]
                    detections[i]["face_confidence"] = ed.get("face_confidence")
        except Exception as e:
            logger.debug(f"Face recognition error (non-fatal): {e}")

    frame = _draw_detections(frame, detections)
    ret2, buf = cv2.imencode(".jpg", frame, [cv2.IMWRITE_JPEG_QUALITY, 85])
    if ret2:
        return buf.tobytes(), detections

    return frame_bytes, detections


async def vision_describe(frame_bytes: bytes) -> str:
    """Use LLM to describe what's visible in the frame."""
    detections = await detect_objects(frame_bytes)
    _ = detections[0]  # labeled image
    objects = detections[1]
    if not objects:
        return "I can see the camera feed but I'm not detecting any specific objects right now."
    obj_list = ", ".join(sorted(set(d["label"] for d in objects)))
    prompt = (
        f"You are Lilly. The camera sees: {obj_list}. "
        f"Describe the scene naturally in 1 sentence. Don't just list objects — say what's happening."
    )
    try:
        desc = await llama_backend.chat(
            [
                {
                    "role": "system",
                    "content": "You are Lilly, a friend AI with vision.",
                },
                {"role": "user", "content": prompt},
            ],
            temperature=0.6,
            max_tokens=80,
        )
        if desc:
            return desc
    except Exception:
        pass
    return f"I see {obj_list} in the frame."


_video_capture = None


def get_video_capture():
    global _video_capture
    if _video_capture is not None and _video_capture.isOpened():
        return _video_capture
    cv2 = _try_import_cv2()
    if cv2:
        if _video_capture is not None:
            try:
                _video_capture.release()
            except Exception:
                pass
        _video_capture = cv2.VideoCapture(0)
        _video_capture.set(cv2.CAP_PROP_FRAME_WIDTH, 640)
        _video_capture.set(cv2.CAP_PROP_FRAME_HEIGHT, 480)
    return _video_capture


async def grab_and_label_frame() -> tuple[bytes, list[dict]]:
    """Grab a frame, run detection, return labeled JPEG + detections."""
    raw = await capture_vision_frame()
    if raw is None:
        return b"", []
    labeled, detections = await detect_objects(raw)
    return labeled, detections


def _webcam_capture_loop():
    """Background thread: continuously capture webcam frames and run YOLO."""
    global _webcam_detections, _webcam_description, _webcam_ts, _webcam_frame_b64
    global _webcam_running
    import base64 as _b64

    cv2 = _try_import_cv2()
    if cv2 is None:
        logger.warning("Webcam loop: OpenCV not available")
        _webcam_running = False
        return

    cap = get_video_capture()
    if cap is None or not cap.isOpened():
        logger.warning("Webcam loop: No webcam available (headless server?)")
        _webcam_running = False
        return

    logger.info("Webcam loop: Starting continuous YOLO capture")
    _webcam_running = True

    while _webcam_running:
        try:
            ret, frame = cap.read()
            if not ret:
                logger.info("Webcam loop: Frame read failed, retrying in 5s")
                time.sleep(5)
                # Try to reopen the capture
                try:
                    cap.release()
                except Exception:
                    pass
                global _video_capture
                _video_capture = None
                cap = get_video_capture()
                if cap is None or not cap.isOpened():
                    logger.warning("Webcam loop: Reopen failed, stopping")
                    _webcam_running = False
                    break
                continue

            ret2, buf = cv2.imencode(".jpg", frame, [cv2.IMWRITE_JPEG_QUALITY, 80])
            if not ret2:
                time.sleep(_WEBCAM_INTERVAL)
                continue

            frame_bytes = buf.tobytes()
            # Run YOLO detection (sync wrapper for the background thread)
            loop = asyncio.new_event_loop()
            try:
                _, detections = loop.run_until_complete(detect_objects(frame_bytes))
            finally:
                loop.close()

            obj_list = sorted(set(d["label"] for d in detections))
            desc = "Camera sees: " + ", ".join(obj_list) if obj_list else ""

            # Store results
            _webcam_detections = detections
            _webcam_description = desc
            _webcam_ts = time.time()
            _webcam_frame_b64 = (
                "data:image/jpeg;base64," + _b64.b64encode(frame_bytes).decode()
            )

            if detections:
                logger.info(
                    f"Webcam loop: {len(detections)} objects detected — {', '.join(obj_list[:5])}"
                )

        except Exception as e:
            logger.warning(f"Webcam loop error: {e}")

        time.sleep(_WEBCAM_INTERVAL)

    logger.info("Webcam loop: Stopped")


def start_webcam_loop():
    """Start the background webcam capture thread (idempotent)."""
    global _webcam_thread, _webcam_running
    if not WEBCAM_ENABLED:
        return
    if _webcam_thread is not None and _webcam_thread.is_alive():
        return
    _webcam_running = True
    _webcam_thread = threading.Thread(target=_webcam_capture_loop, daemon=True)
    _webcam_thread.start()


def stop_webcam_loop():
    """Stop the background webcam capture thread."""
    global _webcam_running
    _webcam_running = False


# ─── TASK SCHEDULER & REMINDERS ─────────────────────────────────
import re as _re

TASKS_FILE = WORKSPACE / "scheduled_tasks.json"


@dataclass
class ScheduledTask:
    id: str
    text: str  # what to remind about
    trigger_time: float  # unix timestamp when to fire
    created: float = field(default_factory=time.time)
    repeat: Optional[str] = None  # None | "daily" | "weekly"
    context: str = ""  # optional context tag
    fired: bool = False


class TaskScheduler:
    def __init__(self):
        self.tasks: list[ScheduledTask] = []
        self._load()

    def _load(self):
        if TASKS_FILE.exists():
            try:
                data = json.loads(TASKS_FILE.read_text())
                for t in data:
                    self.tasks.append(ScheduledTask(**t))
            except Exception:
                self.tasks = []

    def _save(self):
        try:
            TASKS_FILE.write_text(
                json.dumps(
                    [
                        {
                            "id": t.id,
                            "text": t.text,
                            "trigger_time": t.trigger_time,
                            "created": t.created,
                            "repeat": t.repeat,
                            "context": t.context,
                            "fired": t.fired,
                        }
                        for t in self.tasks
                    ],
                    indent=2,
                )
            )
        except Exception:
            pass

    def add(
        self,
        text: str,
        trigger_time: float,
        repeat: Optional[str] = None,
        context: str = "",
    ) -> ScheduledTask:
        tid = f"task_{int(time.time())}_{random.randint(100, 999)}"
        task = ScheduledTask(
            id=tid, text=text, trigger_time=trigger_time, repeat=repeat, context=context
        )
        self.tasks.append(task)
        self._save()
        return task

    def due_tasks(self) -> list[ScheduledTask]:
        now = time.time()
        return [t for t in self.tasks if not t.fired and t.trigger_time <= now]

    def mark_fired(self, task: ScheduledTask):
        if task.repeat:
            # Reschedule recurring tasks
            interval = 86400 if task.repeat == "daily" else 604800
            task.trigger_time += interval
            task.fired = False
        else:
            task.fired = True
        self._save()

    def remove(self, task_id: str) -> bool:
        before = len(self.tasks)
        self.tasks = [t for t in self.tasks if t.id != task_id]
        if len(self.tasks) < before:
            self._save()
            return True
        return False

    def upcoming(self, limit: int = 10) -> list[dict]:
        now = time.time()
        upcoming = [t for t in self.tasks if not t.fired and t.trigger_time > now]
        upcoming.sort(key=lambda t: t.trigger_time)
        return [
            {
                "id": t.id,
                "text": t.text,
                "trigger_time": t.trigger_time,
                "repeat": t.repeat,
                "eta_seconds": round(t.trigger_time - now),
            }
            for t in upcoming[:limit]
        ]


def parse_relative_time(text: str) -> Optional[float]:
    """Parse 'in 30 minutes', 'in 2 hours', 'tomorrow at 9am', 'every day at 8am' etc.
    Returns (trigger_time, repeat) or None."""
    text = text.lower().strip()
    now = time.time()

    # "in X minutes/hours/seconds"
    m = _re.search(r"in\s+(\d+)\s*(min(?:ute)?s?|hr|hour|h|sec(?:ond)?s?|s)\b", text)
    if m:
        val = int(m.group(1))
        unit = m.group(2)
        if unit.startswith("h"):
            delta = val * 3600
        elif unit.startswith("m"):
            delta = val * 60
        else:
            delta = val
        return now + delta

    # "at HH:MM" or "at HH:MM am/pm"
    m = _re.search(r"at\s+(\d{1,2}):(\d{2})\s*(am|pm)?", text)
    if m:
        hour = int(m.group(1))
        minute = int(m.group(2))
        ampm = m.group(3)
        if ampm == "pm" and hour < 12:
            hour += 12
        elif ampm == "am" and hour == 12:
            hour = 0
        import datetime as _dt

        target = _dt.datetime.now().replace(
            hour=hour, minute=minute, second=0, microsecond=0
        )
        if target.timestamp() <= now:
            target += _dt.timedelta(days=1)
        return target.timestamp()

    # "tomorrow at HH:MM" or "tomorrow"
    if "tomorrow" in text:
        base = now + 86400
        m2 = _re.search(r"tomorrow\s+(?:at\s+)?(\d{1,2}):(\d{2})\s*(am|pm)?", text)
        if m2:
            hour = int(m2.group(1))
            minute = int(m2.group(2))
            ampm = m2.group(3)
            if ampm == "pm" and hour < 12:
                hour += 12
            elif ampm == "am" and hour == 12:
                hour = 0
            import datetime as _dt

            target = _dt.datetime.fromtimestamp(base).replace(
                hour=hour, minute=minute, second=0, microsecond=0
            )
            return target.timestamp()
        return base

    # "in an hour" / "in half an hour"
    if "half an hour" in text:
        return now + 1800
    if "an hour" in text or "1 hour" in text:
        return now + 3600

    return None


