@app.get("/api/admin/sessions")
async def admin_list_sessions(request: Request):
    """List all recent sessions from any path (admin only)."""
    if not AUTH_AVAILABLE:
        pass
    else:
        user = await get_current_user(request)
        if (
            not user
            or (user.get("email", "") or "").strip().lower()
            != ADMIN_EMAIL.strip().lower()
        ):
            return JSONResponse({"error": "Admin access required"}, status_code=403)
    sessions = []
    # 1. Session history files
    history_dir = MEMORY_DIR / "session_history"
    if history_dir.exists():
        for f in sorted(
            history_dir.glob("*.json"), key=lambda p: p.stat().st_mtime, reverse=True
        )[:20]:
            try:
                data = json.loads(f.read_text())
                data["_file"] = f.name
                data["_source"] = "session_history"
                sessions.append(data)
            except Exception:
                pass
    # 2. Daily memory files (today + recent)
    if AUTH_AVAILABLE:
        try:
            today = datetime.now().strftime("%Y-%m-%d")
            for uid_dir in (WORKSPACE / "data" / "users").glob("*"):
                for mem_f in sorted(
                    uid_dir.glob(f"memory_*_{today}.json"),
                    key=lambda p: p.stat().st_mtime,
                    reverse=True,
                )[:5]:
                    try:
                        data = json.loads(mem_f.read_text())
                        sessions.append(
                            {
                                "_file": mem_f.name,
                                "_source": "daily_memory",
                                "_user": uid_dir.name,
                                "entry_count": len(data.get("entries", [])),
                                "summary": data.get("summary", "")[:200],
                            }
                        )
                    except Exception:
                        pass
        except Exception:
            pass
    # 3. Conversation history JSONL (last 20 entries)
    hist_file = MEMORY_DIR / "conversation_history.jsonl"
    if hist_file.exists():
        try:
            lines = hist_file.read_text().strip().split("\n")[-20:]
            for line in lines:
                if line.strip():
                    entry = json.loads(line)
                    sessions.append(
                        {
                            "_source": "conversation_log",
                            "avatar": entry.get("avatar", ""),
                            "user": entry.get("user", "")[:80],
                            "assistant": entry.get("assistant", "")[:80],
                            "ts": entry.get("ts", 0),
                        }
                    )
        except Exception:
            pass
    return {"sessions": sessions[:50]}


@app.post("/api/wake")
async def trigger_wake():
    """Wake endpoint — signals next mic chunk to be treated as a command."""
    global WAKE_STATE, LAST_HEARD
    WAKE_STATE["listening"] = True
    WAKE_STATE["pending_wake"] = True
    return {"wake": True, "listening": True}


@app.post("/api/start_ssh")
async def start_ssh():
    success, msg = await ssh_start_on_phone()
    # Re-check after attempt
    await asyncio.sleep(1.0)
    ok = await ssh_check()
    global PHONE_SSH_OK
    PHONE_SSH_OK = ok
    return {"success": ok, "message": msg}


@app.post("/api/stop_ssh")
async def stop_ssh():
    success, msg = await ssh_stop_on_phone()
    global PHONE_SSH_OK
    PHONE_SSH_OK = False
    return {"success": success, "message": msg}


@app.get("/api/child_mode")
async def get_child_mode():
    return {"active": CHILD_MODE}


@app.post("/api/child_mode")
async def toggle_child_mode(data: dict = None):
    global CHILD_MODE
    if data and "active" in data:
        CHILD_MODE = bool(data["active"])
    else:
        CHILD_MODE = not CHILD_MODE
    mode = "Socratic learning" if CHILD_MODE else "normal"
    if CHILD_MODE:
        await speak("Kid mode on! Let's explore and learn together!")
    else:
        await speak("Back to normal mode!")
    return {"active": CHILD_MODE, "mode": mode}


