@app.post("/api/vision/chat")
async def vision_chat(
    file: UploadFile = File(...),
    text: str = Form(""),
    avatar: str = Form(""),
):
    """Accept an image upload from the chat UI, run YOLO detection + LLM description,
    and return a conversational reply the user can display as a chat message.

    Form fields:
      file   — JPEG/PNG image (required)
      text   — optional user question about the image, e.g. "what is this?"
      avatar — avatar key to use; defaults to current_avatar
    """
    _char = resolve_persona_key(avatar) if avatar else (current_avatar or "puppy")

    data = await file.read()
    if not data or len(data) < 200:
        return JSONResponse(
            {"ok": False, "error": "image too small or empty"}, status_code=400
        )

    # ── 1. Run YOLO detection on the uploaded image ──────────────────────────
    detections: list[dict] = []
    labels: list[str] = []
    try:
        if VISION_SERVER_URL:
            # Proxy to external vision server
            proxy = await _proxy_vision_frame(data, avatar=_char)
            if proxy and proxy.get("detections"):
                detections = proxy["detections"]
                labels = sorted(
                    set(d.get("label", "") for d in detections if d.get("label"))
                )
        else:
            # Local YOLO — use the shared detect_objects() which handles
            # model loading, fallback, and the _YOLO_MODEL global correctly.
            _labeled_jpg, _dets = await detect_objects(data)
            if _dets:
                detections = [
                    {
                        "label": d.get("label", "object"),
                        "confidence": d.get("confidence", 0),
                    }
                    for d in _dets
                ]
                labels = sorted(set(d["label"] for d in detections))
    except Exception as _ve:
        logger.warning(f"vision/chat YOLO error: {_ve}")

    # ── 2. Build LLM prompt ──────────────────────────────────────────────────
    _user_q = text.strip() if text.strip() else "What do you see in this image?"
    if labels:
        _vision_ctx = f"Objects detected in the image: {', '.join(labels[:12])}."
    else:
        _vision_ctx = (
            "No specific objects were detected (low confidence or unusual image)."
        )

    messages = [
        {"role": "system", "content": build_avatar_system_prompt(_char)},
        {
            "role": "user",
            "content": (
                f"The user shared an image with you.\n"
                f"{_vision_ctx}\n"
                f"User says: {_user_q}\n\n"
                f"Respond naturally — describe what you see, answer the question, "
                f"or react to it in character. Be specific about what's actually detected. "
                f"2-3 sentences max."
            ),
        },
    ]

    reply = await two_tier_backend.chat(messages, temperature=0.8, max_tokens=120)
    reply = strip_json_wrapper(reply or "").strip()
    if not reply:
        reply = f"I can see {', '.join(labels[:4]) if labels else 'something'} in that image."

    # ── 3. Speak + return ───────────────────────────────────────────────────
    audio_id = await speak(reply, char_key=_char)

    # Record in memory
    _mem_text = f"[image shared] {_user_q}"
    await memory.add("user", _mem_text)
    await memory.add("assistant", reply)
    await save_memory()

    return {
        "ok": True,
        "reply": reply,
        "audio_id": audio_id,
        "detections": [
            {"label": d["label"], "confidence": d.get("confidence", 0)}
            for d in detections[:20]
        ],
        "labels": labels,
    }


@app.post("/api/cmd")
async def text_command(cmd: TextCommand, request: Request):
    _cmd_start = time.time()
    global memory, current_avatar, _current_user_id
    # Extract user from Auth0 session using full async verification
    user_info = await get_current_user(request) if AUTH_AVAILABLE else None
    user_id = user_info.get("id") if user_info else None
    _user_name = _extract_real_name(user_info) if user_info else ""
    logger.info(
        f"[CHAT-TIMER] /api/cmd start: text='{cmd.text[:50]}...' avatar={cmd.avatar}"
    )

    # ── Set the per-request user context so save_memory() inside handle_intent writes
    #    to the correct user-scoped file throughout the entire request lifecycle.
    _current_user_id = user_id or ""

    # Swap to the correct memory for this user+avatar
    # Normalize any emoji / display-name avatar (e.g. "🐶" → "puppy") so the
    # memory file and persona resolution use the canonical key.
    if cmd.avatar and cmd.avatar != current_avatar:
        cmd.avatar = resolve_persona_key(cmd.avatar)

    # Cross-avatar wake word in text (e.g. user typed "Hey Fox" while on Lilly)
    _text_wake_avatar = match_wake_across_avatars(cmd.text)
    if _text_wake_avatar and _text_wake_avatar != (cmd.avatar or current_avatar):
        cmd.avatar = _text_wake_avatar

    # Global state for daily memory context (used by _build_memory_hint)
    _daily_recent_summaries: list = []
    _daily_recent_entries: list = []

    if user_id:
        # Load daily memory: today's entries + recent days for context
        if AUTH_AVAILABLE:
            _recent = load_user_recent_memory(user_id, cmd.avatar or current_avatar)
            _daily_recent_summaries = _recent.get("recent_summaries", [])
            _daily_recent_entries = _recent.get("recent_entries", [])
            # Rebuild memory from today's entries
            _today_data = {
                "entries": _recent.get("entries", []),
                "summary": _recent.get("summary", ""),
            }
            memory = ConversationMemory.from_dict(_today_data)
        else:
            user_mem_data = load_user_memory(user_id)
            memory = ConversationMemory.from_dict(user_mem_data)
    elif cmd.avatar != current_avatar:
        path = _avatar_memory_file(cmd.avatar)
        if path.exists():
            try:
                data = json.loads(path.read_text())
                memory = ConversationMemory.from_dict(data)
            except Exception:
                memory = ConversationMemory()
        else:
            memory = ConversationMemory()
        current_avatar = cmd.avatar  # type: ignore[assignment]

    _handle_start = time.time()
    try:
        res = await handle_intent(cmd.text, from_text=True, user_name=_user_name)
    except Exception as e:
        logger.error(f"[CHAT] /api/cmd handle_intent error: {e}", exc_info=True)
        res = {"action": "error", "text": f"Something went wrong: {str(e)[:200]}"}
    _handle_elapsed = time.time() - _handle_start

    # Final explicit save (belt-and-suspenders — handle_intent already called save_memory)
    if user_id:
        data = await memory.to_dict()
        save_user_memory(user_id, data)
    else:
        await save_memory()
    # Clear user context after request completes
    _current_user_id = ""

    _cmd_elapsed = time.time() - _cmd_start
    logger.info(
        f"[CHAT-TIMER] /api/cmd done: handle_intent={_handle_elapsed:.2f}s "
        f"total={_cmd_elapsed:.2f}s action={res.get('action', '')} "
        f"reply_len={len(res.get('text', ''))}"
    )

    response = {
        "reply": res.get("text", ""),
        "audio_id": AUDIO_CACHE_ID if AUDIO_CACHE else 0,
        "look_at": res.get("look_at"),
        "open_url": res.get("open_url"),
        "user": user_info.get("name") if user_info else None,
    }
    if res.get("phone_action"):
        response["phone_action"] = res["phone_action"]
    if res.get("display"):
        response["display"] = res["display"]
    if res.get("delegate_to"):
        response["delegate_to"] = res["delegate_to"]
        response["delegate_emoji"] = res["delegate_emoji"]
        response["delegate_name"] = res["delegate_name"]
    return response


@app.post("/api/cmd_stream")
async def text_command_stream(cmd: TextCommand, request: Request):
    """Stream chat responses token-by-token using Server-Sent Events (SSE).

    This enables live chat display — the user sees the assistant's reply
    appear word-by-word as it's generated, rather than waiting for the full
    response. When used with voice input, the user's transcribed text is
    also shown in the chat immediately for the streaming duration.

    Response format (SSE):
      data: {"type":"token","value":"..."}      — incremental tokens
      data: {"type":"done","reply":"full text"}  — final reply
      data: {"type":"audio","audio_id":123}     — TTS audio when ready
    """
    _stream_start = time.time()
    global memory, current_avatar, _current_user_id
    logger.info(
        f"[CHAT-TIMER] /api/cmd_stream start: text='{cmd.text[:50]}...' avatar={cmd.avatar}"
    )

    user_info = await get_current_user(request) if AUTH_AVAILABLE else None
    user_id = user_info.get("id") if user_info else None
    _current_user_id = user_id or ""
    _user_name = _extract_real_name(user_info) if user_info else ""

    if cmd.avatar and cmd.avatar != current_avatar:
        cmd.avatar = resolve_persona_key(cmd.avatar)

    # Cross-avatar wake word in text (e.g. user typed "Hey Raccoon" while on Lilly)
    _text_wake_avatar = match_wake_across_avatars(cmd.text)
    if _text_wake_avatar and _text_wake_avatar != (cmd.avatar or current_avatar):
        cmd.avatar = _text_wake_avatar

    # Global state for daily memory context (used by _build_memory_hint)
    _daily_recent_summaries: list = []
    _daily_recent_entries: list = []

    if user_id:
        # Load daily memory: today's entries + recent days for context
        if AUTH_AVAILABLE:
            _recent = load_user_recent_memory(user_id, cmd.avatar or current_avatar)
            _daily_recent_summaries = _recent.get("recent_summaries", [])
            _daily_recent_entries = _recent.get("recent_entries", [])
            _today_data = {
                "entries": _recent.get("entries", []),
                "summary": _recent.get("summary", ""),
            }
            memory = ConversationMemory.from_dict(_today_data)
        else:
            user_mem_data = load_user_memory(user_id)
            memory = ConversationMemory.from_dict(user_mem_data)
    elif cmd.avatar != current_avatar:
        path = _avatar_memory_file(cmd.avatar)
        if path.exists():
            try:
                data = json.loads(path.read_text())
                memory = ConversationMemory.from_dict(data)
            except Exception:
                memory = ConversationMemory()
        else:
            memory = ConversationMemory()
        current_avatar = cmd.avatar

    async def event_stream():
        # Yield a marker so the client knows streaming started
        yield f"data: {json.dumps({'type': 'started'})}\n\n"

        try:
            # ── LILLY ORCHESTRATOR ROUTING ────────────────────────────────
            # Strict routing to the Vision/Builder/Execution pipelines. Replies
            # are ALWAYS plain natural language in Lilly's voice — pipeline
            # JSON/state is never surfaced to the user.
            if ORCHESTRATOR_MODE and ORCHESTRATOR_RUNTIME_AVAILABLE:
                _route_decision = _orchestrator_route_task(cmd.text)
                _orchestrator_remember_route(_route_decision)
                if _route_decision["pipeline"] == "vision":
                    _vision = await _orchestrator_dispatch(
                        "vision", {"text": cmd.text, "image_ref": ""}
                    )
                    if _vision.get("ok"):
                        _reply = _format_orchestrator_reply("vision", _vision)
                        yield f"data: {json.dumps({'type': 'token', 'value': _reply})}\n\n"
                        yield (
                            f"data: {json.dumps({'type': 'done', 'reply': _reply, 'pipeline': 'vision'})}\n\n"
                        )
                        return
                    # No cached frame yet — fall through to normal chat so Lilly
                    # can naturally ask the user to open the camera.
                elif _route_decision["pipeline"] == "execute" and _is_direct_execute(
                    cmd.text
                ):
                    # Direct, concrete execution requests (fetch/run) go to the
                    # Execution Agent immediately and wait for state.
                    _exec = await _orchestrator_dispatch(
                        "execute",
                        {
                            "action": "shell"
                            if not cmd.text.startswith(("fetch", "load", "get "))
                            else "http_request",
                            "params": {"command": cmd.text, "timeout": 30},
                            "text": cmd.text,
                        },
                    )
                    if _exec.get("ok"):
                        _reply = _format_orchestrator_reply("execute", _exec)
                        yield f"data: {json.dumps({'type': 'token', 'value': _reply})}\n\n"
                        yield (
                            f"data: {json.dumps({'type': 'done', 'reply': _reply, 'pipeline': 'execute'})}\n\n"
                        )
                        return
                # Build requests flow through the standard agent loop below
                # (agent_core is the Builder/Doer implementation); routing was
                # already recorded for observability.

            # ── AGENT LOOP ROUTING ─────────────────────────────────────────
            # If this looks like a task (not conversational), route to the
            # agentic orchestration engine instead of the standard LLM path.
            if AGENT_CORE_AVAILABLE and intent_is_agentic(cmd.text):
                session = create_session(
                    task=cmd.text, user_email=_user_name or "laurencekidney@gmail.com"
                )
                async for event in session.run_stream():
                    yield f"data: {json.dumps(event)}\n\n"
                    # If agent needs user input, pause and wait — the frontend
                    # sends the reply via POST /api/agent/reply
                    if event.get("type") == "ask":
                        # Emit a special hold event so the UI knows to collect input
                        yield f"data: {json.dumps({'type': 'agent_ask', 'question': event['question'], 'session_id': session.session_id})}\n\n"
                        # Wait for reply to come in via /api/agent/reply endpoint
                        reply = await session._await_user(
                            event["question"], timeout=120.0
                        )
                cleanup_session(session.session_id)
                return
            # ── END AGENT ROUTING ──────────────────────────────────────────

            # For skill-based commands, handle synchronously (skills aren't streamable).
            # Check if the text matches a skill in the SKILLS dict first.
            # SAFETY: Skip skill matching for long messages (>50 chars) — they're
            # conversational, not app commands. This prevents false triggers.
            phrase = normalize_text(cmd.text)
            skill = None
            if len(phrase) <= 50:
                stripped = re.sub(
                    r"^(run|use|click|tap|open|launch|search|find|what|show|start)\s+",
                    "",
                    phrase,
                ).strip()
                skill = SKILLS.get(phrase) or SKILLS.get(stripped)
                if not skill:
                    for key in sorted(SKILLS.keys(), key=len, reverse=True):
                        if phrase.startswith(key + " "):
                            skill = SKILLS[key]
                            break

                # NLP fallback — "I want to watch youtube videos on true crime"
                if not skill:
                    nlp_skill, _ = parse_nlp_intent(phrase)
                    if nlp_skill:
                        skill = nlp_skill

            if skill and (
                skill.get("action_type") == "openhuman_skill"
                or skill.get("type") == "openhuman_skill"
                or skill.get("action_type")
                in (
                    "intent_launch",
                    "context_launch",
                    "shell_command",
                    "hybrid_intent_tap",
                )
            ):
                # Non-streaming skill path — use handle_intent
                res = await handle_intent(
                    cmd.text, from_text=True, user_name=_user_name
                )
                reply = res.get("text", "")
                yield f"data: {json.dumps({'type': 'token', 'value': reply})}\n\n"
                done_evt = {"type": "done", "reply": reply}
                # Include phone_action metadata if present (for browser card display)
                if res.get("phone_action"):
                    done_evt["phone_action"] = res["phone_action"]
                # Include display data if present (e.g., map coordinates)
                if res.get("display"):
                    done_evt["display"] = res["display"]
                yield f"data: {json.dumps(done_evt)}\n\n"
                if AUDIO_CACHE_ID:
                    yield f"data: {json.dumps({'type': 'audio', 'audio_id': AUDIO_CACHE_ID})}\n\n"
                return

            # Build the message context (same logic as handle_intent but streaming)
            # We call a streaming variant of the LLM path
            _stream_delegate = None
            if current_avatar == "puppy":
                _stream_delegate = _choose_delegate(cmd.text)
            messages = await _build_streaming_context(
                cmd.text, avatar=_stream_delegate, user_name=_user_name
            )

            # Stream tokens from the LLM
            full_reply = ""
            async for token in llama_backend.chat_stream(
                messages, temperature=0.7, max_tokens=200
            ):
                if token:
                    full_reply += token
                    yield f"data: {json.dumps({'type': 'token', 'value': token})}\n\n"

            # Post-process the full reply
            full_reply = strip_json_wrapper(full_reply)
            full_reply = _filter_hallucination_patterns(full_reply)
            full_reply = _strip_emoji(full_reply)

            if not full_reply or len(full_reply) < 5:
                full_reply = (
                    "Not sure where to go with that one — try coming at it differently."
                )

            done_payload = {
                "type": "done",
                "reply": full_reply,
                "avatar_key": current_avatar,
            }
            if _stream_delegate:
                done_payload["delegate_to"] = _stream_delegate
                done_payload["delegate_emoji"] = HIVE_PERSONAS[_stream_delegate][
                    "emoji"
                ]
                done_payload["delegate_name"] = HIVE_PERSONAS[_stream_delegate]["name"]
            yield f"data: {json.dumps(done_payload)}\n\n"

            # Generate TTS
            try:
                audio_id = await generate_tts_for_char(full_reply, current_avatar)
                yield f"data: {json.dumps({'type': 'audio', 'audio_id': audio_id})}\n\n"
            except Exception as e:
                logger.warning(f"TTS generation failed during stream: {e}")

            # Save memory
            await save_memory()

        except Exception as e:
            _stream_elapsed = time.time() - _stream_start
            logger.error(
                f"[CHAT-TIMER] /api/cmd_stream error after {_stream_elapsed:.2f}s: {e}"
            )
            yield f"data: {json.dumps({'type': 'error', 'error': str(e)})}\n\n"
        finally:
            _stream_elapsed = time.time() - _stream_start
            logger.info(
                f"[CHAT-TIMER] /api/cmd_stream done: total={_stream_elapsed:.2f}s reply_len={len(full_reply) if 'full_reply' in dir() else 0}"
            )
            _current_user_id = ""
            yield f"data: {json.dumps({'type': 'end'})}\n\n"

    return StreamingResponse(event_stream(), media_type="text/event-stream")


async def _build_streaming_context(
    text: str, avatar: str | None = None, user_name: str = ""
) -> list[dict]:
    """Build the same message context that handle_intent uses, for streaming."""
    global memory, current_avatar
    _avatar = avatar or current_avatar

    mem_dict = await memory.to_dict()
    context = []

    # Memory context
    mem_summary = mem_dict.get("summary", "")
    if mem_summary:
        context.append({"role": "system", "content": f"SUMMARY:{mem_summary}"})

    # Memory hints
    try:
        hints = await _build_memory_hint(mem_dict)
        if hints:
            context.append({"role": "system", "content": f"CONTEXT_ABOUT_USER:{hints}"})
    except Exception:
        pass

    # Sensor context
    try:
        _snap = await asyncio.wait_for(get_sensor_snapshot(), timeout=0.5)
        if _snap:
            sensor_str = snapshot_to_narrative(_snap)
            if sensor_str:
                context.append(
                    {
                        "role": "system",
                        "content": f"LIVE SENSOR DATA (right now): {sensor_str}",
                    }
                )
    except Exception:
        pass

    # Conversation history
    context_entries = await memory.context_window(24)
    for entry in context_entries:
        context.append(
            {
                "role": entry.role if hasattr(entry, "role") else "user",
                "content": entry.content if hasattr(entry, "content") else str(entry),
            }
        )

    # Awareness note — injected as system message, NOT appended to user text.
    # Appending to user text makes the LLM think it's part of the user's question.
    _pending_awareness = _recent_unacknowledged_for_avatar(current_avatar)
    if _pending_awareness:
        _latest = _pending_awareness[-1]
        _detail = _latest.get("detail", "")
        _action = _latest.get("action", "updated")
        _src = _latest.get("avatar", "someone")
        context.append(
            {
                "role": "system",
                "content": (
                    f"APPROVAL FEED AWARENESS: {_src} {_action} something: {_detail}. "
                    "STRICT RULE: Only mention this if the user explicitly asks about "
                    "automations, approvals, projects, or asks 'what's new'. Otherwise, "
                    "ignore it completely and answer the user's actual question."
                ),
            }
        )

    system_content = build_avatar_system_prompt(_avatar, user_name)
    messages = [{"role": "system", "content": system_content}]
    messages.extend(context)
    messages.append({"role": "user", "content": text})
    messages.append(
        {
            "role": "system",
            "content": "GROUNDING: Do NOT fabricate facts, readings, or events. If sensor data is not provided, do not invent it. If you don't know something, say so — never guess. You are a real friend living in this phone, not a chatbot.",
        }
    )

    return messages


@app.post("/api/story_stream")
async def story_stream(cmd: TextCommand, request: Request):
    """Stream a sensor-grounded story token by token using the fast model."""
    from fastapi.responses import StreamingResponse

    global memory, current_avatar, LILLY_IS_THINKING, LILLY_MOOD, _current_user_id

    # Resolve per-user memory (Auth0 auth)
    story_user_id: str = ""
    if AUTH_AVAILABLE:
        user_info = await get_current_user(request)
        if user_info:
            story_user_id = user_info.get("id", "")
            if story_user_id:
                _current_user_id = story_user_id
                user_mem_data = load_user_memory(story_user_id)
                memory = ConversationMemory.from_dict(user_mem_data)

    # Swap to correct avatar memory (fallback when no auth user)
    if not story_user_id and cmd.avatar != current_avatar:
        cmd.avatar = resolve_persona_key(cmd.avatar)
        path = _avatar_memory_file(cmd.avatar)
        if path.exists():
            try:
                data = json.loads(path.read_text())
                memory = ConversationMemory.from_dict(data)
            except Exception:
                memory = ConversationMemory()
        else:
            memory = ConversationMemory()
        current_avatar = cmd.avatar

    LILLY_IS_THINKING = True
    LILLY_MOOD = "curious"

    # Gather sensor data
    snapshot = await get_sensor_snapshot()
    sensor_narrative = snapshot_to_narrative(snapshot)

    messages = [
        {
            "role": "system",
            "content": (
                "You are Lilly, a curious puppy. Tell a short story (3-5 sentences) "
                "using ONLY the real sensor data provided. Include dialogue with an imaginary friend. "
                "RULES: 1) Only reference provided sensor data. 2) Never invent readings. "
                "3) Use correlations not causation. 4) Playful but grounded. 5) End with a question."
            ),
        },
        {"role": "system", "content": f"SENSOR DATA: {sensor_narrative}"},
        {"role": "user", "content": cmd.text},
    ]

    async def generate():
        full_reply = []
        async for chunk in llama_backend.chat_stream(
            messages, temperature=0.8, max_tokens=150, model=FAST_MODEL
        ):
            full_reply.append(chunk)
            yield chunk
        # Done — speak the full reply and save memory
        final = "".join(full_reply).strip()
        final = _filter_hallucination_patterns(final)
        if final:
            LILLY_IS_THINKING = False
            LILLY_MOOD = "cheerful"
            await memory.add("user", cmd.text)
            await memory.add("assistant", final)
            # Save to per-user file when auth is available, else fall back to avatar file
            if story_user_id and AUTH_AVAILABLE:
                mem_data = await memory.to_dict()
                save_user_memory(story_user_id, mem_data)
            else:
                await save_memory()
            await speak(final)

    return StreamingResponse(generate(), media_type="text/plain")


@app.post("/api/set_name")
async def set_name(data: dict, request: Request):
    user_info = await get_current_user(request) if AUTH_AVAILABLE else None
    user_id = user_info.get("id") if user_info else ""
    name = data.get("name", "").strip()
    if not name or not user_id:
        return {"name": _get_user_name(user_id)}
    # Store per-user so different Google accounts never see each other's names
    _set_user_name(user_id, name)
    # Generate a warm greeting using the LLM
    greeting = None
    try:
        messages = [
            {
                "role": "system",
                "content": "You are Lilly, a sharp curious AI friend. The user just told you their name. Acknowledge it naturally in 1-2 sentences — warm but not over the top. Use their name once. Sound like yourself, not a chatbot.",
            },
            {"role": "user", "content": f"My name is {name}"},
        ]
        greeting = await llama_backend.chat(messages, temperature=0.8, max_tokens=60)
    except Exception:
        pass
    # Fallback greeting if LLM fails
    if not greeting:
        import random

        greetings = [
            f"Good to meet you, {name}. I'll keep that.",
            f"{name} — noted. What are we doing?",
            f"Nice. {name}. I'll remember that.",
            f"Got it, {name}. Good to know.",
        ]
        greeting = random.choice(greetings)
    # Speak the greeting
    audio_id = await speak(greeting)
    return {"name": name, "greeting": greeting, "audio_id": audio_id}


@app.post("/api/memory/clear")
async def clear_memory(data: dict = {}):
    global memory, current_avatar
    avatar = data.get("avatar", current_avatar)
    await memory.clear()
    current_avatar = avatar
    await save_memory()
    return {"status": "cleared", "avatar": avatar}


