# ─── v6.0 UNIFIED PAIRING ──────────────────────────────────────────────
@app.post("/api/pair/initiate")
async def pair_initiate(request: Request):
    """Generate a 6-digit pairing code for WebUI -> overlay pairing.

    Auth-free flow: anyone may generate a code; the code itself is what the
    app presents back at /api/pair/confirm (proves possession of the screen).
    If Auth0 is available AND there is a session, tag the user for display.
    """
    user_id = "web_session"
    user_name = "WebUI"
    if AUTH_AVAILABLE:
        try:
            user = await get_current_user(request)
            if user and user.get("id"):
                user_id = user["id"]
                user_name = user.get("name", user.get("email", user_id))
        except Exception:
            pass
    code = _generate_pairing_code()
    _pairing_codes[code] = {
        "user_id": user_id,
        "user_name": user_name,
        "created": time.time(),
        "expires": time.time() + _PAIRING_CODE_TTL,
    }
    return {
        "ok": True,
        "code": code,
        "expires_in": _PAIRING_CODE_TTL,
        "version": "6.0",
    }


@app.post("/api/pair/confirm")
async def pair_confirm(request: Request):
    """Exchange a 6-digit pairing code for a persistent device token."""
    body = await request.json()
    code = (body.get("code") or "").strip()
    if not code or len(code) != 6 or not code.isdigit():
        raise HTTPException(
            status_code=400, detail="Invalid pairing code (must be 6 digits)"
        )
    entry = _pairing_codes.pop(code, None)
    if not entry:
        raise HTTPException(status_code=400, detail="Invalid or expired pairing code")
    if time.time() > entry["expires"]:
        raise HTTPException(status_code=400, detail="Pairing code expired")
    token = _generate_device_token()
    _device_tokens[token] = {
        "user_id": "overlay_device",
        "user_name": "Lilly Overlay v6",
        "created": time.time(),
        "version": "6.0",
    }
    # Build server URL from the actual request so the app learns where the web UI lives
    scheme = request.url.scheme
    host = request.url.hostname
    port = request.url.port
    if port and port not in (80, 443):
        server_url = f"{scheme}://{host}:{port}"
    else:
        server_url = f"{scheme}://{host}"
    return {
        "ok": True,
        "token": token,
        "user_name": "Lilly Overlay v6",
        "server_url": server_url,
        "version": "6.0",
    }


@app.get("/api/pair/status")
async def pair_status(request: Request):
    """Check if a pairing code is valid and not expired."""
    code = request.query_params.get("code", "").strip()
    if not code or len(code) != 6:
        return {"ok": False, "valid": False, "reason": "missing_code"}
    entry = _pairing_codes.get(code)
    if not entry:
        return {"ok": False, "valid": False, "reason": "not_found"}
    if time.time() > entry["expires"]:
        _pairing_codes.pop(code, None)
        return {"ok": False, "valid": False, "reason": "expired"}
    return {
        "ok": True,
        "valid": True,
        "expires_in": int(entry["expires"] - time.time()),
    }


@app.post("/api/phone_pair")
async def phone_pair(request: Request):
    """Legacy pairing endpoint (v4.x compat). Now delegates to v6.0 flow."""
    body = await request.json()
    token = (body.get("token") or "").strip().upper()
    if not token or len(token) != 8:
        raise HTTPException(
            status_code=400, detail="Invalid pairing token (must be 8 characters)"
        )
    # v6.0: auto-generate a 6-digit code for this legacy token
    code = _generate_pairing_code()
    _pairing_codes[code] = {
        "created": time.time(),
        "expires": time.time() + _PAIRING_CODE_TTL,
        "legacy_token": token,
    }
    _device_tokens[token] = {
        "user_id": "overlay_device",
        "user_name": "Lilly Overlay v6",
        "created": time.time(),
        "version": "6.0",
    }
    return {
        "ok": True,
        "token": token,
        "user_name": "Lilly Overlay v6",
        "server_url": f"https://droolingwithsanity.ca",
        "message": "Overlay paired successfully (v6.0 compat)",
        "version": "6.0",
    }


@app.post("/api/phone_cmd")
async def phone_cmd(request: Request):
    """Proxy phone commands to the Termux phone server."""
    body = await request.json()
    cmd_type = body.get("type", "")
    token = body.get("token", "")
    # Verify pairing token if provided
    if token and token not in _device_tokens:
        # Also accept overlay 8-char tokens
        if len(token) == 8 and token in _device_tokens:
            pass
        else:
            raise HTTPException(status_code=401, detail="Invalid device token")
    try:
        async with httpx.AsyncClient(timeout=30.0) as client:
            r = await client.post(
                f"{PHONE_SERVER_URL}/api/phone_cmd",
                json=body,
                headers={"Content-Type": "application/json"},
            )
            return Response(
                content=r.content,
                status_code=r.status_code,
                media_type=r.headers.get("content-type", "application/json"),
            )
    except Exception as e:
        return {"ok": False, "error": str(e)}


# ─── FILE SHARE ──────────────────────────────────────────────────
FILE_SHARE_DIR = Path(WORKSPACE) / "file_share"
FILE_SHARE_DIR.mkdir(parents=True, exist_ok=True)

_WORKSPACE_DIR = "~/Lilly_Workspace"


async def _read_workspace_file(filename: str) -> str | None:
    """Read a file from Termux ~/Lilly_Workspace/ via SSH. Returns content or None."""
    if not filename or ".." in filename or "/" in filename:
        return None
    try:
        out, err = await termux_run(
            ["cat", f"{_WORKSPACE_DIR}/{filename}"], timeout=5.0
        )
        return out if out else None
    except Exception:
        return None


@app.get("/api/workspace/lilly_state.json")
async def workspace_lilly_state():
    content = await _read_workspace_file("lilly_state.json")
    if content is None:
        raise HTTPException(
            status_code=404, detail="lilly_state.json not found in ~/Lilly_Workspace/"
        )
    return PlainTextResponse(content)


@app.get("/api/workspace/normalize_intent.json")
async def workspace_normalize_intent():
    content = await _read_workspace_file("normalize_intent.json")
    if content is None:
        raise HTTPException(
            status_code=404,
            detail="normalize_intent.json not found in ~/Lilly_Workspace/",
        )
    return PlainTextResponse(content)


@app.get("/api/workspace/list")
async def workspace_list():
    out, err = await termux_run(["ls", "-la", _WORKSPACE_DIR], timeout=5.0)
    files = []
    if out:
        for line in out.strip().split("\n"):
            files.append(line)
    return JSONResponse({"files": files, "error": err.strip() if err else ""})


@app.get("/api/files/list")
async def list_files():
    files = []
    for f in FILE_SHARE_DIR.iterdir():
        if f.is_file():
            files.append(
                {
                    "name": f.name,
                    "size": f.stat().st_size,
                    "modified": f.stat().st_mtime,
                }
            )
    return JSONResponse(files)


@app.post("/api/files/upload")
async def upload_file(file: UploadFile = File(...)):
    if not file.filename:
        raise HTTPException(status_code=400, detail="No filename")
    safe_name = re.sub(r"[^\w\.\-]", "_", file.filename)
    dest = FILE_SHARE_DIR / safe_name
    content = await file.read()
    dest.write_bytes(content)
    return {"status": "ok", "filename": safe_name, "size": len(content)}


@app.get("/api/files/{filename}")
async def download_file(filename: str):
    safe_name = re.sub(r"[^\w\.\-]", "_", filename)
    path = FILE_SHARE_DIR / safe_name
    if not path.exists() or not path.is_file():
        raise HTTPException(status_code=404, detail="File not found")
    return FileResponse(str(path), filename=safe_name)


# ─── APK DOWNLOAD API ──────────────────────────────────────────
# Serves the Android overlay / Termux-server APK builds so the phone
# can fetch them straight from the Settings panel.


def _apk_variants() -> list[dict]:
    """Discover available APK builds.

    light — small overlay client (file_share/latest_apk.apk, hitomi-v*.apk,
             else newest lilly-overlay-v*.apk under ~10MB).
    full  — large Termux-server bundle with AI backend (file_share/lilly-overlay-5*.apk).
    """
    variants: list[dict] = []
    fs_dir = FILE_SHARE_DIR

    def _add(kind: str, path: Path) -> None:
        if not path or not path.is_file():
            return
        st = path.stat()
        # variant label from filename (e.g. "hitomi-v0.1.3" → "0.1.3", "v3.10-debug" → "3.10", "lilly-overlay-4.0-debug" → "4.0")
        m = re.search(r"v?(\d+(?:\.\d+)+)", path.name)
        label = m.group(1).strip(".-") if m else "latest"
        variants.append(
            {
                "type": kind,
                "name": path.name,
                "path": str(path),
                "size": st.st_size,
                "variant": label,
                "updated": int(st.st_mtime),
            }
        )

    def _version_tuple(path: Path) -> tuple:
        """Extract a sortable version tuple from an APK filename."""
        m = re.search(r"v?(\d+(?:\.\d+)+)", path.name)
        if not m:
            return (0,)
        return tuple(int(x) for x in m.group(1).split("."))

    def _best_light() -> Path | None:
        # 1) Prefer lilly-overlay-*.apk under ~10MB, sorted by version desc then mtime desc
        overlay = sorted(
            [
                p
                for p in fs_dir.glob("lilly-overlay-*.apk")
                if p.is_file() and p.stat().st_size < 10_000_000
            ],
            key=lambda p: (_version_tuple(p), p.stat().st_mtime),
            reverse=True,
        )
        if overlay:
            return overlay[0]
        # 2) Fallback: newest hitomi-v*.apk by version/mtime
        hitomi = sorted(
            [p for p in fs_dir.glob("hitomi-v*.apk") if p.is_file()],
            key=lambda p: (_version_tuple(p), p.stat().st_mtime),
            reverse=True,
        )
        if hitomi:
            return hitomi[0]
        # 3) Fallback: explicit latest_apk.apk
        latest = fs_dir / "latest_apk.apk"
        if latest.exists():
            return latest
        return None

    light = _best_light()
    if light:
        _add("light", light)
    # Full: newest full-kit bundle (zip — overlay + Termux APKs) first; legacy
    # fallback is the largest lilly-overlay-*.apk >50MB (old Termux-server bundle).
    if fs_dir.exists():
        fullkits = sorted(
            [p for p in fs_dir.glob("lilly-overlay-full-*.zip") if p.is_file()],
            key=lambda p: (_version_tuple(p), p.stat().st_mtime),
            reverse=True,
        )
        full = fullkits[0] if fullkits else None
        if full is None:
            fulls = sorted(
                fs_dir.glob("lilly-overlay-*.apk"),
                key=lambda p: p.stat().st_size,
                reverse=True,
            )
            full = next((p for p in fulls if p.stat().st_size > 50_000_000), None)
        if full:
            _add("full", full)
    return variants


@app.get("/api/apk/variants")
async def apk_variants():
    return _apk_variants()


@app.get("/api/apk/latest")
async def apk_latest():
    """Return the latest light overlay APK info."""
    variants = _apk_variants()
    light = next((v for v in variants if v["type"] == "light"), None)
    if not light:
        raise HTTPException(status_code=404, detail="No overlay build found")
    return light


@app.get("/api/app_version")
async def app_version():
    """Version + download info for the overlay's version badge (/api/app_version)."""
    variants = _apk_variants()
    light = next((v for v in variants if v["type"] == "light"), None)
    if not light:
        return {"version": "", "download_url": ""}
    return {
        "version": light.get("variant", ""),
        "download_url": "/api/apk/download?type=light",
        "name": light.get("name", ""),
        "size": light.get("size", 0),
    }


@app.post("/api/apk/upload")
async def apk_upload(file: UploadFile = File(...)):
    """TEMP upload: stage any file (APK/ZIP/txt/py/html…) from the WebUI into file_share/.

    Used to move build artifacts (e.g. lilly-overlay-v6.6-debug.apk) or share files
    (text, code, configs) from a phone browser onto the host without SSH.
    Accepts any filename — no extension restriction.
    """
    import hashlib

    if not file.filename:
        raise HTTPException(status_code=400, detail="No filename")
    name = file.filename.replace("\\", "/").split("/")[-1]
    safe = re.sub(r"[^\w\.\-]", "_", name)
    FILE_SHARE_DIR.mkdir(parents=True, exist_ok=True)
    dest = FILE_SHARE_DIR / safe
    data = await file.read()
    if not data:
        raise HTTPException(status_code=400, detail="Empty upload")
    dest.write_bytes(data)
    return {
        "status": "ok",
        "filename": safe,
        "path": str(dest),
        "size": len(data),
        "sha256": hashlib.sha256(data).hexdigest(),
        "note": "Staged in file_share/ — temp upload.",
    }


# ─────────────────────────────────────────────────────────────────────────────
# TASK 3 — PERSONA EVOLUTION SCALE DASHBOARD
# GET /api/persona_scores  →  per-persona composite score, rank, evolution history
# ─────────────────────────────────────────────────────────────────────────────


@app.get("/api/persona_scores")
async def get_persona_scores():
    """Return scoring dashboard for all personas — composite score, rank, evolution history."""
    if not PERSONA_OPTIMIZER_AVAILABLE:
        return JSONResponse({"error": "PersonaOptimizer not loaded"}, status_code=503)

    summary = persona_optimizer.scores_summary()

    # Sort personas by avg_score_recent descending so APK can show a ranked list
    ranked = sorted(
        summary.items(),
        key=lambda kv: kv[1].get("avg_score_recent", 0.0),
        reverse=True,
    )

    result = []
    for rank, (persona_key, stats) in enumerate(ranked, start=1):
        evolution = persona_optimizer.evolution_history_for(persona_key)
        score = stats.get("avg_score_recent", 0.0)
        # Grade label — Google/Alexa style: Essential > Useful > Learning > Weak
        if score >= 0.80:
            grade = "Essential"
        elif score >= 0.65:
            grade = "Useful"
        elif score >= 0.45:
            grade = "Learning"
        else:
            grade = "Weak"

        result.append(
            {
                "rank": rank,
                "persona": persona_key,
                "score": round(score, 3),
                "grade": grade,
                "total_interactions": stats.get("total_interactions", 0),
                "version": stats.get("version", 0),
                "recent_window_size": stats.get("recent_window_size", 0),
                "last_optimised": stats.get("last_optimised", 0),
                "evolution_history": evolution[-10:],  # last 10 evolution steps
            }
        )

    return JSONResponse(
        {
            "personas": result,
            "threshold_essential": 0.80,
            "threshold_useful": 0.65,
            "threshold_learning": 0.45,
            "note": "Scores are composite of engagement(45%), accuracy(35%), style_match(20%)",
        }
    )


# ─────────────────────────────────────────────────────────────────────────────
# TASK 4 — NOTIFICATION READING ENDPOINT
# POST /api/notifications/push   — APK pushes current notifications to server
# GET  /api/notifications         — APK or UI reads the cached notification list
# ─────────────────────────────────────────────────────────────────────────────

_cached_notifications: list[dict] = []
_cached_notifications_at: float = 0.0
_NOTIF_CACHE_TTL = 30.0  # seconds — notifications expire after 30s


class NotificationPushRequest(BaseModel):
    notifications: list[dict] = []


@app.post("/api/notifications/push")
async def push_notifications(req: NotificationPushRequest):
    """Receive the current notification list from the Android NotificationListenerService."""
    global _cached_notifications, _cached_notifications_at
    _cached_notifications = req.notifications or []
    _cached_notifications_at = time.time()
    return {"status": "ok", "count": len(_cached_notifications)}


@app.get("/api/notifications")
async def get_notifications():
    """Return the most recent notification list (pushed by the APK NotificationListenerService)."""
    age = time.time() - _cached_notifications_at
    if age > _NOTIF_CACHE_TTL:
        return JSONResponse(
            {
                "notifications": [],
                "fresh": False,
                "age_seconds": round(age, 1),
                "note": "No recent push from device — notification listener may not be active",
            }
        )

    # Build a concise summary for TTS / chat display
    # Priority tolerant: app listener pushes lowercase "high"/"max", push scripts
    # may send uppercase "HIGH"/"MAX" — compare case-insensitively.
    high_priority = [
        n
        for n in _cached_notifications
        if str(n.get("priority", "") or "").upper() in ("HIGH", "MAX")
    ]
    display_list = high_priority if high_priority else _cached_notifications[:5]

    summary_parts = []
    for n in display_list[:5]:
        app_name = (
            n.get("appName") or n.get("package") or n.get("packageName", "Unknown")
        )
        title = (n.get("title") or "").strip()
        # App listener sends "content"; older push paths send "text".
        text = (n.get("text") or n.get("content") or "").strip()
        if title and text:
            summary_parts.append(f"{app_name}: {title} — {text}")
        elif title:
            summary_parts.append(f"{app_name}: {title}")
        elif text:
            summary_parts.append(f"{app_name}: {text}")

    spoken_summary = ""
    if summary_parts:
        if len(summary_parts) == 1:
            spoken_summary = summary_parts[0]
        else:
            spoken_summary = (
                f"You have {len(display_list)} notifications. "
                + ". ".join(summary_parts[:3])
            )
    else:
        spoken_summary = "No active notifications."

    return JSONResponse(
        {
            "notifications": _cached_notifications,
            "count": len(_cached_notifications),
            "fresh": True,
            "age_seconds": round(age, 1),
            "spoken_summary": spoken_summary,
            # Announced notifications still awaiting action on the phone
            "tracked": [
                {
                    "tag": e.get("tag"),
                    "app": e.get("app_label"),
                    "title": e.get("title"),
                    "summary": e.get("summary"),
                    "interests": e.get("interests", []),
                    "announced_at": e.get("announced_at"),
                    "followups_sent": e.get("followups", 0),
                    "actioned": False,
                }
                for e in _NOTIF_TRACKED.values()
            ],
            # Recently actioned (clicked on phone / confirmed / declined)
            "recently_actioned": [
                {
                    "app": e.get("app_label"),
                    "title": e.get("title"),
                    "actioned_at": e.get("actioned_at"),
                    "actioned_via": e.get("actioned_via"),
                }
                for e in _NOTIF_ACTIONED_LOG[-10:]
            ],
        }
    )


@app.post("/api/pushbullet/send")
async def api_pushbullet_send(req: Request):
    """Send a push notification via Pushbullet. Body: {title, body, url?}.

    Works as a direct API endpoint OR as a fallback channel for system notifications.
    """
    try:
        body = await req.json()
    except Exception:
        body = {}
    title = body.get("title", "Lilly")
    content = body.get("body", "")
    url = body.get("url")
    ok = await send_pushbullet_note(title, content, url)
    if ok:
        return {"status": "sent"}
    return JSONResponse(
        {"error": "Pushbullet send failed (check API key)"}, status_code=502
    )


# ─────────────────────────────────────────────────────────────────────────────
# SETTINGS
# GET  /api/settings           — Load user settings
# POST /api/settings/pushbullet — Save Pushbullet API key
# POST /api/settings/sensor    — Save sensor server URL
# POST /api/settings/clear     — Clear all local data
# ─────────────────────────────────────────────────────────────────────────────

_settings_store: dict[str, dict] = {}  # In-memory per-user settings (dev)


def _get_user_settings(user_id: str) -> dict:
    return _settings_store.get(user_id, {})


def _set_user_settings(user_id: str, data: dict):
    cur = _get_user_settings(user_id)
    cur.update(data)
    _settings_store[user_id] = cur


@app.get("/api/settings")
async def get_settings(request: Request):
    user = await get_current_user(request)
    uid = user.get("id") if user else "anonymous"
    s = _get_user_settings(uid)
    return {
        "pushbullet_api_key": s.get("pushbullet_api_key", ""),
        "sensor_server_url": s.get(
            "sensor_server_url", os.environ.get("SENSOR_SERVER_URL", "")
        ),
        "lilly_pair_token": s.get("lilly_pair_token", ""),
        "proactive_notifications": s.get("proactive_notifications", True),
        "notification_sound": s.get("notification_sound", True),
        "pushbullet_fallback": s.get("pushbullet_fallback", False),
        "notif_paused": _NOTIF_PREFS.get("paused", False),
        "notif_daily_cap": _NOTIF_PREFS.get("daily_cap", 3),
    }


@app.post("/api/settings/pushbullet")
async def save_pushbullet_setting(request: Request):
    user = await get_current_user(request)
    uid = user.get("id") if user else "anonymous"
    try:
        body = await request.json()
        key = (body.get("api_key") or "").strip()
    except Exception:
        key = ""
    _set_user_settings(uid, {"pushbullet_api_key": key})
    # Update runtime global so new notifications use the key immediately
    if key:
        os.environ["PUSHBULLET_API_KEY"] = key
        global PUSHBULLET_API_KEY
        PUSHBULLET_API_KEY = key
    return {"ok": True}


